INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-3','MODULE 3: Malicious Code (Fəsil 3)','PUBLISHED',3 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-malicious-code-jo3uuy','Malicious Code','Malicious Code','CompTIA Security+ · MODULE 3: Malicious Code (Fəsil 3)','Module 2-də threat actor-ları (kim), motivasiyalarını (niyə) və threat vector-ları (necə çatır) öyrəndiniz. İndi sual budur: hədəfə çatan hücumçu **konkret olaraq nə** işə salır? Bu room-da kitabın SY0-701 üçün xüsusi vurğuladığı doqquz malware növünü — Ransomware, Trojan, Worm, Spyware, Bloatware, Virus, Keylogger, Logic Bomb, Rootkit — öyrənəcəksiniz. Kitab birbaşa xəbərdarlıq edir: imtahanda sizə indikatorlar (IoC) veriləcək və siz bunlardan hansı malware növü olduğunu müəyyən etməli olacaqsınız — ona görə hər növün **fərqləndirici xüsusiyyətini** dəqiq bilmək vacibdir.','CompTIA Security+','WALKTHROUGH','INTERMEDIATE'::difficulty,'75 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'GREEN',ARRAY['Doqquz əsas malware növünü fərqləndirici xüsusiyyətlərinə görə tanımaq','Hər malware növünün tipik IoC-lərini (Indicator of Compromise) sadalamaq','Worm və Virus arasındakı, Spyware və Bloatware arasındakı əsas fərqləri izah etmək','Malware analiz texnikalarını (sandbox, VirusTotal, manual kod analizi) tanımaq']::text[],'drive/1UfG5knZS7ROqfJw2wZwRAP0XuQJo3UUy.md','PUBLISHED',1,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-3' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Ransomware, Trojan və Bot/Botnet','75 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"# ROOM 1: Malicious Code\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 3 — Malicious Code (Fəsil 3)\n**Mənbə:** CompTIA Security+ Study Guide, 9th Ed. — \"Malware\" bölməsi\n**Domain uyğunluğu:** 2.0 Threats, Vulnerabilities, and Mitigations (22%) — obyektiv 2.4\n**Çətinlik:** Medium\n**Təxmini vaxt:** 75 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)\n\n## Room haqqında\n\nModule 2-də threat actor-ları (kim), motivasiyalarını (niyə) və threat vector-ları (necə çatır) öyrəndiniz. İndi sual budur: hədəfə çatan hücumçu **konkret olaraq nə** işə salır? Bu room-da kitabın SY0-701 üçün xüsusi vurğuladığı doqquz malware növünü — Ransomware, Trojan, Worm, Spyware, Bloatware, Virus, Keylogger, Logic Bomb, Rootkit — öyrənəcəksiniz. Kitab birbaşa xəbərdarlıq edir: imtahanda sizə indikatorlar (IoC) veriləcək və siz bunlardan hansı malware növü olduğunu müəyyən etməli olacaqsınız — ona görə hər növün **fərqləndirici xüsusiyyətini** dəqiq bilmək vacibdir.\n\n## Öyrənmə nəticələri\n\n- Doqquz əsas malware növünü fərqləndirici xüsusiyyətlərinə görə tanımaq\n- Hər malware növünün tipik IoC-lərini (Indicator of Compromise) sadalamaq\n- Worm və Virus arasındakı, Spyware və Bloatware arasındakı əsas fərqləri izah etmək\n- Malware analiz texnikalarını (sandbox, VirusTotal, manual kod analizi) tanımaq\n\n**Ransomware** — kompüteri ələ keçirib fidyə (ödəniş) tələb edən malware-dir. Ən çox yayılmış forması **crypto malware**-dir — faylları şifrələyib fidyə ödənənə qədər girov saxlayır. Digər variantlar: qurbanı qanunsuz proqram/pornoqrafiyaya görə hüquq-mühafizə orqanlarına şikayət etməklə hədələmək, yaxud sərt diskdəki həssas məlumatı/şəkilləri ifşa etməklə hədələmək. Ransomware hücumlarının böyük hissəsi phishing kampaniyaları vasitəsilə çatdırılır, amma RDP (Remote Desktop Protocol) və ya zəif servislərə birbaşa hücum da geniş yayılıb.\n\n**Ransomware-in tipik IoC-ləri:** C&C trafiki, sistemi nəzarətdə saxlamaq üçün qanuni alətlərin qeyri-normal istifadəsi, digər sistemlərə \"lateral movement\" cəhdləri, faylların şifrələnməsi, istifadəçiyə fidyə tələbi bildirişi, böyük fayl transferləri (data exfiltration).\n\n**Ən vacib müdafiə** — ayrı, təsirlənməyəcək yerdə saxlanılan effektiv backup sistemidir. Kitab vurğulayır: bəzi hallarda fidyə ödəmək faylların qaytarılmasına səbəb olub, digər hallarda hücumçular sadəcə daha çox pul tələb edib — ona görə təşkilat əvvəlcədən öz reaksiya strategiyasını müəyyənləşdirməlidir.\n\n---\n\n**Trojan (Troya Atı)** — qanuni proqram təminatı kimi maskalanmış malware-dir. \"Troya atı\" adlanmasının səbəbi — istifadəçinin özünün, bilmədən, onu işə salmasına əsaslanmasıdır. Kitabın nümunəsi: Triada Trojan-ı, WhatsApp-ın \"təkmilləşdirilmiş\" versiyası kimi paylanır — işə salınanda cihaz ID-si, abunəçi ID-si, hardware ünvanı kimi məlumatları toplayıb uzaq serverə qeydiyyatdan keçirir, sonra əlavə zərərli kod yüklənir.\n\n**RAT (Remote Access Trojan)** — hücumçuya sistemə uzaqdan çıxış təmin edən Trojan növüdür. Çətinlik burasındadır ki, bəzi **qanuni** uzaqdan dəstək alətləri də RAT kimi istifadə oluna bilər — bu, \"qanuni alət\" ilə \"zərərli RAT\" arasında fərq qoymağı çətinləşdirir; antimalware alətləri bəzən yalançı-müsbət (false positive) verə bilər, amma bu aşkarlamanı söndürmək RAT-ların gözdən qaçmasına səbəb ola bilər.\n\n**Trojan-ın tipik IoC-ləri:** konkret malware tətbiqi/fayl üçün imzalar, C&C sisteminin hostname/IP ünvanları, hədəf cihazda yaradılan qovluq/fayllar.\n\n---\n\n**Bots, Botnets və Command and Control (C&C)** — bir çox malware növü hücumçulara ona nə etməli olduğunu deməyə imkan verən komanda-nəzarət (C&C) texnikalarından istifadə edir. Mərkəzi komanda altındakı sistem qrupları **botnet**, fərdi sistemlər isə **bot** adlanır. C&C getdikcə şifrələnmiş HTTP bağlantılarından istifadə edir (müşahidədən qaçmaq üçün tez-tez dəyişən uzaq host-lara qoşularaq), amma IRC (port 6667) kimi köhnə texnikalar da hələ populyardır. Müdafiəçi kimi, naməlum host-lara \"əl uzadan\" sistemin botnet-in hissəsi ola biləcəyini necə aşkarlamağı bilmək vacibdir.\n\n| Növ | Fərqləndirici xüsusiyyət | Əsas IoC |\n|---|---|---|\n| Ransomware | Fidyə tələb edir, faylları şifrələyir | Fayl şifrələnməsi, fidyə bildirişi |\n| Trojan | Qanuni proqram kimi maskalanır | C&C hostname/IP, yeni fayl/qovluqlar |\n| RAT | Uzaqdan tam nəzarət verir | Qanuni alətə bənzəyir — çətin aşkarlanır |\n\n**Sual 1**\nCrypto malware nədir və Ransomware-in hansı formasıdır?\n\n**Sual 2**\nTrojan niyə \"Troya atı\" adlanır — hansı prinsipə əsaslanır?\n\n**Sual 3**\nBotnet və bot arasındakı fərq nədir?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-malicious-code-jo3uuy' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Worms və Viruses: Özünü Yayan Malware','75 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"**Worm** — Trojan-dan fərqli olaraq, **istifadəçi qarşılıqlı əlaqəsi tələb etmədən özünü yayır**. Worm-lar adətən zəif servislərə hücumla yayılmaqla əlaqələndirilir, amma email əlavələri, şəbəkə fayl paylaşımları, zəif IoT cihazları/telefonlar vasitəsilə də yayıla bilər. Worm-lar həmçinin **özünü quraşdırır** — istifadəçinin klik etməsini tələb etmir, bu da onları xüsusilə təhlükəli edir.\n\n**Stuxnet (2010)** — kibersilah kimi işlədilən ilk worm nümunəsi sayılır. İran nüvə proqramını hədəf almışdı, air-gapped (fiziki cəhətdən şəbəkəyə bağlı olmayan) kompüterləri keçmək üçün özünü flash-lara köçürürdü. Etibarlı rəqəmsal sertifikatdan istifadə etmək, İran nüvə proqramında istifadə olunduğu bilinən konkret ICS (Industrial Control System) sistemlərini axtarmaq, sentrifuqalara zərər verərkən nəzarətçilərə saxta monitorinq datası göndərmək kimi qabaqcıl texnikalardan istifadə edirdi ki, zərər çox gec aşkarlansın.\n\n**Raspberry Robin** — müasir worm nümunəsi, ransomware-öncəsi fəaliyyətin bir hissəsi kimi istifadə olunur. İlkin yayılması yoluxmuş USB sürücülər (LNK fayl vasitəsilə) idi, işə düşəndən sonra Windows-un öz alətlərindən istifadə edərək davamlılıq (persistence) əldə edir ki, reboot-dan sonra da sağ qalsın.\n\n**Worm mitigasiyası** əsasən şəbəkə-səviyyəli nəzarətlərdən (firewall, IPS, seqmentasiya) başlayır — kompromis olmuş cihazlar digər zəif cihazlarla əlaqə saxlaya bilmirsə, infeksiya yayıla bilmir. Patching və servisləri konfiqurasiya edərək attack surface-i azaltmaq da vacibdir.\n\n---\n\n**Virus** — worm-lardan fərqli olaraq, virus **özünü avtomatik yaymır** — bir və ya bir neçə infeksiya mexanizmi (thumb drive-a köçürmə, şəbəkə paylaşımı) tələb edir. Virus adətən **trigger** (icra şərtini müəyyən edən) və **payload** (virusun etdiyi hərəkət) komponentlərindən ibarətdir.\n\nVirus növləri:\n- **Memory-resident** — sistem işlədiyi müddətdə yaddaşda qalır\n- **Non-memory-resident** — icra olur, yayılır, sonra bağlanır\n- **Boot sector** — diskin/media-nın boot sektorunda yerləşir\n- **Macro** — söz emalı proqramlarındakı makroslardan/koddan istifadə edərək yayılır\n- **Email** — email əlavəsi kimi, yaxud email client-lərindəki zəifliklərdən istifadə edərək yayılır\n\n**Fileless virus** — spam email və zərərli veb-saytlar vasitəsilə yayılır, brauzer plugin-lərindəki zəifliklərdən istifadə edir. Sistemə uğurla daxil olandan sonra özünü **birbaşa yaddaşa** yeridir — heç vaxt lokal fayl saxlama tələb etmir (yeganə saxlanılan iz, davamlılıq texnikasının özüdür — məsələn, Registry qeydi). Bu, fileless virus-u ənənəvi antivirus üçün xüsusilə çətin aşkarlanan edir, çünki skan ediləcək \"fayl\" yoxdur.\n\n| | Worm | Virus |\n|---|---|---|\n| Yayılma | Özü, istifadəçi qarşılıqlı əlaqəsi olmadan | İnfeksiya mexanizmi tələb edir (thumb drive və s.) |\n| Sürət | Çox sürətli (avtomatik) | Nisbətən yavaş (mexanizmə bağlı) |\n| Nümunə | Stuxnet, Raspberry Robin | Fileless virus, macro virus |\n\n**Sual 1**\nWorm və Virus arasındakı əsas fərq nədir?\n\n**Sual 2**\nStuxnet-in air-gapped sistemləri necə keçdiyini izah edin.\n\n**Sual 3**\nFileless virus niyə ənənəvi antivirus üçün xüsusilə çətin aşkarlanandır?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-malicious-code-jo3uuy' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Spyware, Bloatware və Keyloggers: Məlumat Toplayan Malware','75 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"**Spyware** — fərd, təşkilat və ya sistem barədə məlumat əldə etmək üçün dizayn edilmiş malware-dir. Bəzi spyware nisbətən zərərsizdir (brauzer vərdişlərini izləyir), amma bəziləri həssas məlumatı hədəf alır, veb-kameraya uzaqdan çıxış verir. Spyware **şəxsiyyət oğurluğu, fırıldaqçılıq, reklam/trafik yönləndirmə, DRM monitorinqi** və **stalkerware** (münasibətlərdə partnyoru qanunsuz izləmək üçün istifadə olunan spyware növü) ilə əlaqələndirilir.\n\nVacib nüans: spyware başqa malware növlərinin (Trojan, worm, virus) yayılma metodlarından istifadə edə bilər — onu spyware kimi təyin edən **davranışı yox, niyyəti/məqsədidir** (məlumat toplamaq). NSO Group-un Pegasus alətı kommersiyalaşdırılmış spyware nümunəsidir.\n\n**Bloatware** — digər malware kateqoriyalarından fərqli olaraq, adətən **qəsdən zərərli deyil**. İstehsalçılar və ya proqram paketləri tərəfindən quraşdırılan istənilməyən tətbiqlərdir. Zəif yazılmış ola bilər, sistem/istifadə barədə məlumat \"evə göndərə\" bilər, yaxud istismar oluna bilən zəiflik daşıya bilər — beləliklə əlavə attack surface yaradır.\n\n**Kitabın Exam Note-u — Spyware vs Bloatware fərqi (imtahanda tez-tez qarışdırılır):** İstehsalçıların quraşdırdığı bloatware-də tez-tez \"evə zəng etmə\" funksionallığı olduğu üçün, ikisini ayırmaq çətin ola bilər. Əsas fərqləndirici — **spyware-in birinci niyyəti** istifadəçi, onun sistem istifadəsi və konfiqurasiyası barədə məlumat toplamaqdır, **bloatware isə sadəcə istənilməyən proqramdır** (niyyət yoxdur).\n\n---\n\n**Keyloggers** — klaviaturadan klaviş vuruşlarını tutan proqramlardır (bəziləri siçan hərəkətini, toxunma ekranı girişini, kart sürüşdürmələrini də tuta bilər). Kernel-dən, API/skriptlər vasitəsilə, hətta birbaşa yaddaşdan məlumat tuta bilər. Məqsəd — istifadəçi girişini toplayıb hücumçu tərəfindən analiz/istifadə etməkdir.\n\nKeylogger-lərin əksəriyyəti parolları əldə etməyə yönəldiyi üçün, **çoxfaktorlu autentifikasiya (MFA)** istifadəsi keylogger-in özünü məğlub etməsə də, onun təsirini məhdudlaşdıra bilər. Software keylogger-lərdən əlavə, **hardware keylogger-lər** də mövcuddur və ucuzdur — kitab müəllifləri kollec kampuslarında tələbələrin müəllimlərinin credential-larını əldə etmək (bəzən uğurla, qiymətlərini dəyişmək üçün) cəhdlərinə şahid olduqlarını qeyd edir.\n\n| | Spyware | Bloatware | Keylogger |\n|---|---|---|---|\n| Niyyət | Məlumat toplamaq (məqsədli) | Yoxdur (sadəcə istənilməyən) | Klaviş vuruşlarını tutmaq |\n| Əsas müdafiə | Antimalware, awareness | Silinmə/təmiz OS image | Patching, MFA |\n\n**Sual 1**\nSpyware-i digər malware növlərindən fərqləndirən əsas meyar nədir (davranış, yoxsa niyyət)?\n\n**Sual 2**\nBloatware niyə \"zərərli\" kateqoriyaya daxil edilmir, amma yenə də risk yaradır?\n\n**Sual 3**\nMFA niyə keylogger-i \"məğlub etmir\", amma onun təsirini \"məhdudlaşdırır\"? Fərqi izah edin."}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-malicious-code-jo3uuy' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,4,'Logic Bombs, Rootkits və Malware Analizi','75 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"**Logic Bomb** — digər malware növlərindən fərqli olaraq, **müstəqil proqram deyil**. Əvəzinə, başqa proqramların daxilinə yerləşdirilmiş, müəyyən şərtlər ödəndikdə aktivləşən funksiya/koddur. Digər malware növləri də öz funksiyalarının bir hissəsi kimi bu tip koddan istifadə edə bilər. Digər malware növlərinə nisbətən nadir olsa da, uğurla aktivləşdikdə ciddi təsir yarada bilər.\n\nLogic bomb kod daxilində olduğu üçün, onun IoC-ləri daha az rast gəlinir — aşkarlama proqramın kodunun/məntiqinin analizini tələb edir, ona görə mitigasiya prosesləri də əsasən **kod baxışına (code review)** fokuslanır.\n\n---\n\n**Rootkits** — hücumçulara sistemə arxa qapı (backdoor) vasitəsilə çıxış imkanı vermək üçün xüsusi dizayn edilmiş malware-dir. Müasir rootkit-lərin çoxu özünü aşkarlanmadan gizlətmək qabiliyyətinə malikdir — fayl sistemi driver-lərini \"hook\" edərək istifadəçilərin rootkit fayllarını görməsinin qarşısını almaqdan tutmuş, diskin Master Boot Record (MBR)-ində başlanğıc koduna yoluxaraq tam disk şifrələmə sistemlərinə qarşı hücuma imkan verməyə qədər.\n\n**Rootkit aşkarlanması çətindir**, çünki bu malware ilə yoluxmuş sistemə etibar edilə bilməz. Ən yaxşı üsul — şübhəli sistemi **etibarlı** bir sistem/cihazdan test etməkdir (məsələn, diski çıxarıb başqa sistemə qoşmaq — beləliklə yoluxmuş OS işləmir və rootkit özünü gizlədə bilmir). Bu mümkün olmadıqda, rootkit aşkarlama alətləri tipik davranış/imzalara baxır; bütövlük yoxlaması (integrity checking) və gözlənilən nəticələrə qarşı data validasiyası da faydalıdır.\n\nRootkit aşkarlandıqdan sonra silinməsi çətin ola bilər — ən çox tövsiyə olunan yanaşma sistemi **yenidən qurmaq və ya etibarlı backup-dan bərpa etmək**dir. Virtual maşınlar, konteynerlər, sistem imicləri getdikcə populyarlaşdığı üçün bu bərpa prosesi sadələşib, çox vaxt rootkit-i tam təmizləməyə çalışmaqdan daha sürətli olur.\n\n> **Qeyd:** Bəzi rootkit-lər **qəsdən** quraşdırılır — DRM sistemlərinin, oyunlardakı hiyləyə-qarşı (anti-cheat) alətlərin və ya surət qorunması mexanizmlərini məğlub etmək üçün alətlərin bir hissəsi kimi. Bunlar texniki olaraq rootkit sayılsa da, siz adətən zərərli aktorlar tərəfindən istifadə olunan alətlərə fokuslanacaqsınız.\n\n**Rootkit-in tipik IoC-ləri:** fayl hash-ları/imzaları, C&C domenləri/IP ünvanları, davranış-əsaslı müəyyənləşdirmə (servis yaradılması, konfiqurasiya dəyişiklikləri, fayl çıxışı), portların açılması və ya reverse proxy tunellərinin yaradılması.\n\n---\n\n**Malware Analizi Texnikaları** — kitab təhlükəsizlik analitikinin şübhəli kodun zərərli olub-olmadığını müəyyənləşdirmək üçün istifadə edə biləcəyi əsas alətləri sadalayır:\n\n- **Online analiz alətləri** (VirusTotal kimi) — malware-in tanınan alət olub-olmadığını yoxlayır, çoxsaylı AV alətinin onu necə identifikasiya etdiyini göstərir\n- **Sandbox alətləri** — malware davranışını qorunmuş mühitdə analiz etmək üçün\n- **Manual kod analizi** — xüsusilə skript və interpretasiya olunan kodlarla (Python, Perl) geniş yayılıb\n- **Strings kimi alətlər** — analiz üçün faydalı ola biləcək bərpa oluna bilən artefaktları axtarmaq üçün\n\n**Sual 1**\nLogic Bomb digər malware növlərindən struktur baxımından necə fərqlənir?\n\n**Sual 2**\nRootkit-i aşkarlamağın \"ən yaxşı üsulu\" kitaba görə nədir və niyə?\n\n**Sual 3**\nRootkit silindikdən sonra niyə çox vaxt \"sistem sıfırlama/yenidən qurma\" tövsiyə olunur, sadəcə antimalware ilə təmizləmə yox?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Doqquz malware növünü sadalayın.\n2. Ransomware-in ən çox yayılmış forması hansıdır və necə işləyir?\n3. Trojan və Worm arasındakı əsas fərq nədir?\n4. Virus-un iki əsas komponentini (trigger, payload) izah edin.\n5. Spyware-i Bloatware-dən fərqləndirən əsas meyar nədir?\n6. Logic Bomb niyə \"müstəqil proqram\" sayılmır?\n7. Rootkit-in ən effektiv aşkarlanma üsulu nədir?\n8. Malware analizi üçün istifadə olunan dörd texnikadan ikisini sadalayın.\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-malicious-code-jo3uuy' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO paths(slug,title,description,category,status,order_index) VALUES ('comptia-security-plus','CompTIA Security+','CompTIA Security+ kurikulumu','CompTIA Security+' ,'PUBLISHED',2) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-2','MODULE 2: Cybersecurity Threat Landscape','PUBLISHED',2 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-threat-data-and-intelligence-ffzo0a','Threat Data and Intelligence','Threat Data and Intelligence','CompTIA Security+ · MODULE 2: Cybersecurity Threat Landscape','Room 1-də kim hücum edir, niyə edir və necə çatır sualına cavab tapdınız. İndi sual budur: **kibertəhlükəsizlik komandası bu haqda necə xəbərdar olur?** Bu room-da threat intelligence (təhdid kəşfiyyatı) proqramının necə qurulduğunu — mənbələrdən (OSINT, closed-source), etibarlılıq qiymətləndirməsindən, standart formatlardan (STIX/TAXII) tutmuş, kollektiv məlumat mübadiləsi təşkilatlarına (ISAC) qədər — öyrənəcəksiniz.','CompTIA Security+','WALKTHROUGH','INTERMEDIATE'::difficulty,'50 dəq',0,'GREEN',ARRAY['Threat intelligence-in məqsədini və əsas komponentlərini (IoC, TTP, CVE) izah etmək','OSINT və closed-source (proprietary) intelligence mənbələrini fərqləndirmək','Threat intelligence-in etibarlılıq (confidence) şkalasını tətbiq etmək','STIX/TAXII-nin nə üçün lazım olduğunu izah etmək','ISAC-ların rolunu təşkilati kontekstdə başa düşmək']::text[],'drive/1HvHfY6o0oOPzdZaSFg38yBA9tPFfzO0A.md','PUBLISHED',2,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-2' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Threat Intelligence Nədir və Nədən İbarətdir?','50 dəq',0,'[{"body":"# ROOM 2: Threat Data and Intelligence\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 2 — Cybersecurity Threat Landscape (Fəsil 2)\n**Mənbə:** CompTIA Security+ Study Guide, 9th Ed. — \"Threat Data and Intelligence\" bölməsi\n**Domain uyğunluğu:** 2.0 Threats, Vulnerabilities, and Mitigations (22%) — obyektiv 2.2\n**Çətinlik:** Medium\n**Təxmini vaxt:** 50 dəq\n\n## Room haqqında\n\nRoom 1-də kim hücum edir, niyə edir və necə çatır sualına cavab tapdınız. İndi sual budur: **kibertəhlükəsizlik komandası bu haqda necə xəbərdar olur?** Bu room-da threat intelligence (təhdid kəşfiyyatı) proqramının necə qurulduğunu — mənbələrdən (OSINT, closed-source), etibarlılıq qiymətləndirməsindən, standart formatlardan (STIX/TAXII) tutmuş, kollektiv məlumat mübadiləsi təşkilatlarına (ISAC) qədər — öyrənəcəksiniz.\n\n## Öyrənmə nəticələri\n\n- Threat intelligence-in məqsədini və əsas komponentlərini (IoC, TTP, CVE) izah etmək\n- OSINT və closed-source (proprietary) intelligence mənbələrini fərqləndirmək\n- Threat intelligence-in etibarlılıq (confidence) şkalasını tətbiq etmək\n- STIX/TAXII-nin nə üçün lazım olduğunu izah etmək\n- ISAC-ların rolunu təşkilati kontekstdə başa düşmək\n\n**Threat Intelligence** — kibertəhlükəsizlik mütəxəssislərinin təhdid mühitindəki dəyişiklikləri öyrənmək üçün istifadə etdiyi fəaliyyət və resurslar toplusudur. Threat intelligence proqramı qurmaq hər təşkilatın kibertəhlükəsizlik yanaşmasının vacib hissəsidir — cari təhdidlərlə tanış olmasanız, təşkilatınızı onlardan qorumaq üçün uyğun müdafiə qura bilməzsiniz. Threat intelligence məlumatı proqnozlaşdırıcı təhlil üçün də istifadə oluna bilər ki, təşkilata ehtimal olunan riskləri müəyyənləşdirsin.\n\nThreat feed-lər (mənbədən asılı olmayaraq) təşkilatınızın istifadə edə biləcəyi formada təhdidlər barədə güncəl detal təqdim etmək üçün nəzərdə tutulub. Adətən bunları ehtiva edir:\n\n- **Texniki detallar** — IP ünvanları, hostname/domain-lər, email ünvanları, URL-lər, fayl hash-ları, fayl yolları, CVE (Common Vulnerabilities and Exposures) qeyd nömrələri\n- **Kontekstual məlumat** — təşkilatınızı niyə hədəf/zəif edə biləcəyi, threat actor təsviri, motivasiya və metodologiya detalları\n\n**Vulnerability databases** — threat intelligence proqramının vacib hissəsidir. Zəiflik hesabatları təşkilatın müdafiə səylərinə istiqamət verir, həm də tədqiqatçıların kəşf etdiyi istismar növləri barədə dəyərli fikir təqdim edir.\n\n**Indicators of Compromise (IoC)** — threat intelligence mənbələrinin təqdim edə biləcəyi digər vacib element — hücumun baş verdiyini göstərən əlamətlərdir (fayl imzaları, log nümunələri, hücumçuların qoyduğu digər sübutlar). IoC-lər fayl və kod repozitoriyalarında da tapıla bilər.\n\n**Sual 1**\nThreat intelligence nədir və niyə hər təşkilat üçün vacibdir?\n\n**Sual 2**\nThreat feed-lərdə ehtiva olunan texniki detallardan üçünü sadalayın.\n\n**Sual 3**\nIndicator of Compromise (IoC) nə deməkdir?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-threat-data-and-intelligence-ffzo0a' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Mənbələr: OSINT, Closed-Source və Dark Web','50 dəq',0,'[{"body":"Threat intelligence mənbələri geniş spektrdə dəyişir — açıq mənbələrdən (public) kommersiya (proprietary) xidmətlərinə qədər.\n\n**Open Source Intelligence (OSINT)** — ictimaiyyətə açıq mənbələrdən əldə edilən threat intelligence. Bir çox təşkilat açıq threat information paylaşımının nə qədər faydalı olduğunu anlayıb, indi çətinlik çox vaxt hansı mənbələrin istifadə ediləcəyinə qərar vermək, onların etibarlı/güncəl olduğunu təmin etmək və onlardan yaxşı istifadə etməkdir. OSINT mənbələrinə misal: hökumət təhlükəsizlik agentliklərinin (CISA kimi) məlumat paylaşım proqramları, sənaye üzrə İnformasiya Paylaşımı və Təhlil Təşkilatları, satıcı təhlükəsizlik bloqları (Microsoft, Cisco), açıq resurslar (SANS Internet Storm Center).\n\n**Closed-Source (Proprietary) Intelligence** — kommersiya təhlükəsizlik satıcıları, hökumət təşkilatları və digər təhlükəsizlik-mərkəzli təşkilatlar öz məlumat toplama və araşdırmalarını aparır, xüsusi alət/analiz modelləri istifadə edərək threat feed-lərini toplayır, kuratorluq edir və saxlayır.\n\n**Dark Web** — standart internet bağlantıları üzərindən işləyən, amma anonim kommunikasiya təmin etmək üçün çoxqatlı şifrələmə istifadə edən şəbəkə. Hakerlər tez-tez məlumat paylaşmaq və hücumlar zamanı oğurlanan credential-ları/məlumatı satmaq üçün dark web saytlarından istifadə edir. Threat intelligence komandaları dark web-lə tanış olmalı və öz təşkilatına/müştərilərinə aid credential-ları tapmaq üçün dark web bazarlarını axtarmalıdır — credential-ların dark web bazarlarında qəflətən görünməsi, uğurlu hücumun baş verdiyini göstərə bilər və əlavə araşdırma tələb edir. Dark web-ə Tor brauzeri vasitəsilə çıxış əldə edilə bilər.\n\n| Mənbə növü | Xüsusiyyət | Nümunə |\n|---|---|---|\n| OSINT | Pulsuz/açıq, çoxsaylı, keyfiyyət dəyişkən | Hökumət feed-ləri, satıcı bloqları |\n| Closed-Source | Kommersiya, kuratorlaşdırılmış, ödənişli | Xüsusi satıcı threat feed xidmətləri |\n| Dark Web | Anonim, çox vaxt qeyri-qanuni fəaliyyət mərkəzi | Oğurlanmış credential bazarları |\n\n**Etibarlılıq (Confidence) Şkalası:** Threat intelligence mütəxəssisləri qiymətləndirmələrinin etibarlılığını rəqəmsal/təsviri şkala ilə ifadə edirlər. Bir yayılmış yanaşma altı səviyyədən ibarətdir:\n\n| Səviyyə | Diapazon | Təsvir |\n|---|---|---|\n| Confirmed | 90-100 | Müstəqil mənbələr/birbaşa analiz təhdidin real olduğunu sübut edir |\n| Probable | 70-89 | Məntiqi nəticəyə əsaslanır, amma birbaşa təsdiq etmir |\n| Possible | 50-69 | Bəzi məlumat razılaşır, amma qiymətləndirmə təsdiqlənməyib |\n| Doubtful | 30-49 | Mümkündür, amma ən ehtimallı seçim deyil, ya da mövcud məlumatla nə sübut, nə də təkzib olunur |\n| Improbable | 2-29 | Mümkündür, amma məntiqi deyil, ya da mövcud məlumatla təkzib olunur |\n| Discredited | 1 | Qiymətləndirmənin qeyri-dəqiq/yanlış olduğu təsdiqlənib |\n\nTəşkilatlar fərqli şkala da istifadə edə bilər (1-5, 1-10, Yüksək/Orta/Aşağı) — məqsəd threat intelligence istifadəçilərinə qiymətləndirmənin və onun əsasında duran məlumatın keyfiyyətini sürətlə qiymətləndirməyə imkan verməkdir.\n\n**Vacib praktiki qeyd:** tək bir threat feed istifadə etmək sizi qaranlıqda saxlaya bilər! Bir çox təşkilat ən güncəl məlumatı əldə etmək üçün çoxsaylı threat feed istifadə edir. Feed-lərin birləşdirilməsi çətin ola bilər, çünki onlar eyni format/təsnifat modelini istifadə etməyə bilər — bunu artıq çoxsaylı feed-i birləşdirən mənbələr tapmaqla və ya STIX kimi eyni təsvir çərçivəsini istifadə edən feed-ləri tapmaqla həll etmək olar (Task 3-də).\n\n**Sual 1**\nOSINT və Closed-Source Intelligence arasındakı fərq nədir?\n\n**Sual 2**\nDark web-də bir təşkilatın credential-larının qəflətən görünməsi nəyə işarə edə bilər?\n\n**Sual 3**\nEtibarlılıq şkalasında \"Probable\" (70-89) ilə \"Confirmed\" (90-100) arasındakı əsas fərq nədir?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-threat-data-and-intelligence-ffzo0a' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Standartlaşdırma (STIX/TAXII) və Məlumat Mübadiləsi Təşkilatları','50 dəq',0,'[{"body":"Hər hansı miqyasda threat information idarə etmək standartlaşdırma və alət tələb edir ki, məlumat avtomatlaşdırılmış üsullarla işlənə və istifadə edilə bilsin. Buna görə strukturlaşdırılmış marka dilləri (structured markup languages) mövcuddur.\n\n**STIX (Structured Threat Information eXpression)** — əvvəlcə ABŞ Vətən Təhlükəsizliyi Departamenti tərəfindən sponsorlaşdırılan XML dilidir. Hazırkı versiyası (STIX 2.1) hücum nümunələri, şəxsiyyətlər, malware, threat actor-lar və alətlər kimi 18 STIX Domain Object müəyyən edir. Bu obyektlər bir-biri ilə iki STIX Relationship Object növündən biri (relationship və ya sighting) vasitəsilə əlaqələndirilir. STIX hazırda OASIS (Organization for the Advancement of Structured Information Standards) tərəfindən idarə olunur.\n\n**TAXII (Trusted Automated eXchange of Intelligence Information)** — STIX-in yoldaşı protokoludur, kibertəhdid məlumatının HTTPS vasitəsilə tətbiq qatında ötürülməsinə imkan verir. TAXII xüsusi olaraq STIX məlumat mübadiləsini dəstəkləmək üçün dizayn edilib.\n\nBu iki standartın praktiki dəyəri: müxtəlif satıcıların/təşkilatların threat feed-ləri fərqli, uyğunsuz formatlarda olarsa, avtomatlaşdırma mümkün olmaz — hər inteqrasiya üçün əl ilə çevirmə lazım gələr. STIX/TAXII ümumi \"dil\" təqdim edərək, müxtəlif mənbələrdən gələn məlumatın avtomatik alətlər/sistemlər tərəfindən sistemli işlənməsinə imkan verir.\n\n**Information Sharing Organizations (ISAC-lar):** Threat intelligence satıcılarına/resurslarına əlavə olaraq, threat information paylaşmaq üçün kollektiv icmalar yaradılıb. ABŞ-da **Information Sharing and Analysis Centers (ISAC)** adlanan təşkilatlar kritik infrastruktur sahiblərinə/operatorlarına threat information paylaşmaqda kömək edir və üzvlərinə alət/dəstək təqdim edir. ISAC konsepti 1998-ci ildə Prezident Qərarı Direktivi-63 (PDD-63) çərçivəsində təqdim olunub, kritik infrastruktur sektorlarından təhdid/zəifliklər barədə məlumat paylaşan təşkilatlar qurmalarını tələb edib. ISAC-lar etimad modeli əsasında işləyir, fiziki və kiber təhdidlər barədə dərin məlumat paylaşımına imkan verir; əksəriyyəti 24/7 işləyir və üzvlərinə insident cavabı və təhdid təhlili təqdim edir.\n\nBundan əlavə, kibertəhlükəsizlik mütəxəssisləri öz araşdırmalarını da davam etdirməlidir — satıcı təhlükəsizlik saytları, RFC sənədləri (internet protokollarının texniki spesifikasiyaları), peşəkar konfranslar, tanınmış təhlükəsizlik mütəxəssislərinin sosial media hesabları kimi mənbələr vasitəsilə. Bu araşdırma zamanı xüsusi diqqət yetirilməli olan bir termin — **TTP (Tactics, Techniques, and Procedures)** — hücumçuların necə fəaliyyət göstərdiyini təsvir edir; hücumçuların işləmə tərzini öyrənmək, öz threat intelligence proqramınızı təkmilləşdirməyə imkan verir.\n\n**Sual 1**\nSTIX və TAXII arasındakı əlaqə nədir — hər biri nəyə xidmət edir?\n\n**Sual 2**\nISAC nədir və hansı prinsipə (model) əsasən işləyir?\n\n**Sual 3**\nTTP nə deməkdir və threat intelligence proqramı üçün niyə faydalıdır?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Threat intelligence-in əsas məqsədini bir cümlə ilə izah edin.\n2. IoC nə deməkdir və nümunə verin.\n3. OSINT və Closed-Source Intelligence arasındakı fərq nədir.\n4. Etibarlılıq şkalasında altı səviyyədən üçünü sadalayın.\n5. STIX nədir və nə üçün istifadə olunur?\n6. ISAC-ın məqsədini izah edin.\n7. Niyə tək bir threat feed-ə güvənmək risklidir?\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-threat-data-and-intelligence-ffzo0a' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
