INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-2','MODULE 2: Cybersecurity Threat Landscape','PUBLISHED',2 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-exploring-cybersecurity-threats-awtqxg','Exploring Cybersecurity Threats','Exploring Cybersecurity Threats','CompTIA Security+ · MODULE 2: Cybersecurity Threat Landscape','Module 1-də kibertəhlükəsizliyin **məqsədlərini** (CIA) və bu məqsədlər pozulanda yaranan **təsiri** (Breach Impact) öyrəndiniz. İndi sual budur: bu pozuntuları kim, niyə və necə edir? Bu room-da hücumçuların (threat actor) təsnifatını, ən çox rast gəlinən növlərini, motivasiyalarını və onların təşkilata çatmaq üçün istifadə etdiyi yolları (threat vector) öyrənəcəksiniz. Kitab bunu "düşməni tanımaq" kimi təqdim edir — effektiv müdafiə qurmazdan əvvəl kimdən müdafiə olunduğunuzu bilməlisiniz.','CompTIA Security+','WALKTHROUGH','INTERMEDIATE'::difficulty,'70 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'GREEN',ARRAY['Threat actor-ları təsnif etmək üçün istifadə olunan dörd atributu (internal/external, sophistication, resources, motivation) tətbiq etmək','"Hat" terminologiyasını (white/black/gray) və əsas threat actor növlərini (unskilled, hacktivist, organized crime, nation-state/APT, insider, shadow IT, competitor) fərqləndirmək','Hücumçu motivasiyalarının doqquz kateqoriyasını tanımaq','Threat vector və attack surface anlayışlarını fərqləndirmək, əsas vector növlərini sadalamaq']::text[],'drive/1PuL-LcpGoRXfhnnfb4N0y8rsVNaWTqxG.md','PUBLISHED',1,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-2' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Threat Actor-ları Necə Təsnif Edirik?','70 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"# ROOM 1: Exploring Cybersecurity Threats\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 2 — Cybersecurity Threat Landscape (Fəsil 2)\n**Mənbə:** CompTIA Security+ Study Guide, 9th Ed. — \"Exploring Cybersecurity Threats\" bölməsi\n**Domain uyğunluğu:** 2.0 Threats, Vulnerabilities, and Mitigations (22%) — obyektiv 2.1, 2.2\n**Çətinlik:** Easy→Medium\n**Təxmini vaxt:** 70 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)\n\n## Room haqqında\n\nModule 1-də kibertəhlükəsizliyin **məqsədlərini** (CIA) və bu məqsədlər pozulanda yaranan **təsiri** (Breach Impact) öyrəndiniz. İndi sual budur: bu pozuntuları kim, niyə və necə edir? Bu room-da hücumçuların (threat actor) təsnifatını, ən çox rast gəlinən növlərini, motivasiyalarını və onların təşkilata çatmaq üçün istifadə etdiyi yolları (threat vector) öyrənəcəksiniz. Kitab bunu \"düşməni tanımaq\" kimi təqdim edir — effektiv müdafiə qurmazdan əvvəl kimdən müdafiə olunduğunuzu bilməlisiniz.\n\n## Öyrənmə nəticələri\n\n- Threat actor-ları təsnif etmək üçün istifadə olunan dörd atributu (internal/external, sophistication, resources, motivation) tətbiq etmək\n- \"Hat\" terminologiyasını (white/black/gray) və əsas threat actor növlərini (unskilled, hacktivist, organized crime, nation-state/APT, insider, shadow IT, competitor) fərqləndirmək\n- Hücumçu motivasiyalarının doqquz kateqoriyasını tanımaq\n- Threat vector və attack surface anlayışlarını fərqləndirmək, əsas vector növlərini sadalamaq\n\nKitab konkret hücumçu növlərinə keçməzdən əvvəl, onları fərqləndirən dörd atributu təqdim edir. Bu atributlar imtahanda birbaşa sınana bilər, çünki hər sual sonda bu siyahıdan birinə bağlanır.\n\n**Internal vs External** — Ən çox təhlükəni xarici rəqiblər, cinayətkarlar və maraqlı şəxslər kimi düşünürük, amma ən təhlükəli təhdidlərin bəziləri öz təşkilatımızın içindən gəlir (insider threat, Task 2-də).\n\n**Level of Sophistication/Capability** — Hücumçular kibertəhlükəsizlik bacarığı baxımından böyük fərqlərə malikdir — başqalarından götürdüyü kodu işə salan sadə hücumçudan tutmuş, öz tədqiqat laboratoriyasında kəşf etdiyi, təhlükəsizlik cəmiyyətinə hələ məlum olmayan zəiflikləri istismar edən Advanced Persistent Threat (APT) aktoruna qədər.\n\n**Resources/Funding** — Yüksək təşkil olunmuş, mütəşəkkil cinayət və ya milli hökumətlər tərəfindən maliyyələşən hücumçuların demək olar ki, sonsuz resursları ola bilər, halbuki az təşkil olunmuş hücumçular sadəcə öz boş vaxtlarında işləyən həvəskarlar ola bilər.\n\n**Intent/Motivation** — Hücumçular motivasiya baxımından da fərqlənir. Sadə bacarıqlı olmayan hücumçu sadəcə hücumun həyəcanı üçün ola bilər, rəqiblər isə yüksək hədəflənmiş korporativ casusluqla məşğul ola bilər.\n\n**Praktiki tövsiyə:** kitab media-da eşitdiyiniz real hücum xəbərlərini bu dörd atributla təhlil etməyi tövsiyə edir. Məsələn, qurbandan ödəniş tələb edən bir ransomware hücumu, korporativ casusluqla məşğul olan rəqibdən çox, maliyyə qazancı axtaran mütəşəkkil cinayətlə əlaqəli olma ehtimalı daha yüksəkdir.\n\n### \"Papaq\" Terminologiyası\n\nKibertəhlükəsizlik icması hücumçuların motivasiyasını təsvir etmək üçün rəngli \"papaq\" jarqonundan istifadə edir — bu, köhnə Qərb (Western) filmlərindən gəlir, burada \"yaxşı adamlar\" ağ, \"pis adamlar\" qara papaq geyinirdi.\n\n| Papaq | Termin | Təsvir |\n|---|---|---|\n| **White-hat** | Authorized attacker | İcazə ilə hərəkət edir, zəiflikləri düzəltmək məqsədilə axtarır (işçi/pentest podratçısı) |\n| **Black-hat** | Unauthorized attacker | Zərərli niyyətlə, nəzarətləri məğlub etmək və CIA-nı pozmaq üçün |\n| **Gray-hat** | Semi-authorized attacker | İcazəsiz hərəkət edir, amma hədəfi zəifliklər barədə məlumatlandırmaq niyyətindədir |\n\nVacib xəbərdarlıq: yaxşı niyyət gray-hat hackinq-i qanuni və ya etik etmir — gray-hat hücumçuların istifadə etdiyi texnikalar hələ də cinayət hesab oluna və cəzalandırıla bilər.\n\n**Sual 1**\nThreat actor-ları təsnif etmək üçün istifadə olunan dörd atributu sadalayın.\n\n**Sual 2**\nRansomware hücumu niyə adətən korporativ casusluqdan çox mütəşəkkil cinayətlə əlaqələndirilir? Hansı atributa (motivasiya) əsaslanır?\n\n**Sual 3**\nGray-hat hacker kimdir və niyə \"yaxşı niyyət\" onun hərəkətlərini avtomatik qanuni etmir?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-exploring-cybersecurity-threats-awtqxg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Threat Actor Növləri','70 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"Kitab imtahan obyektivlərinə uyğun yeddi əsas threat actor növünü təqdim edir.\n\n**Unskilled Attackers (Script Kiddie)** — Hacking texnikalarından istifadə edən, amma məhdud bacarığa malik hücumçular üçün işlədilən kiçildici termin. Çox vaxt internetdən endirdikləri avtomatlaşdırılmış alətlərə demək olar ki, tam etibar edirlər və hücumlarının necə işlədiyi barədə az bilikləri var. Aşağı bacarıq səviyyəsinə baxmayaraq, real təhlükədirlər — birincisi, sadə hakinq alətləri internetdə pulsuz mövcuddur (istənilən kəs DoS hücumunu avtomatlaşdıra, virus yarada bilər), ikincisi, bu hücumçular saysızdırlar və hədəf seçimində diqqətsizdirlər — çox vaxt kimə hücum etdiklərini belə bilmirlər, sadəcə zəif qurbanlar axtarırlar.\n\n**Hacktivists** — Hansısa aktivist məqsədə çatmaq üçün hacking texnikalarından istifadə edir. Onların müəyyənedici xüsusiyyəti — hərəkətləri qanunu pozsa belə, özlərini \"böyük xeyir\" tərəfindən motivasiya olunmuş hesab etmələridir. Buna görə caydırıcı tədbirlər onları digər hücumçular qədər çəkindirmir — bəziləri tutulmağı öz məqsədləri üçün fədakarlıq/şərəf nişanı sayır. Ən tanınan hacktivist qrupu Anonymous-dur. Bəzi işçilər/whistleblower-lar da (məsələn, Edward Snowden) daxili hacktivist sayıla bilər.\n\n**Organized Crime** — Pul qazanılan hər yerdə mütəşəkkil cinayət də mövcuddur, kibercinayət istisna deyil. Onların ortaq xüsusiyyəti — motivasiya sırf qanunsuz maliyyə qazancıdır, siyasi məsələlərlə maraqlanmırlar və diqqəti öz üzərinə çəkməkdən çəkinirlər. Adətən orta-yüksək bacarıq səviyyəsinə malikdirlər və hacktivistlərdən daha çox resursa sahibdirlər.\n\n**Nation-State Attackers / APT** — Advanced Persistent Threat (APT) termini həm texnikanın **advanced** (qabaqcıl, sadəcə internetdən endirilən alətlər deyil), həm də hücumun **persistent** (uzun müddət, bəzən illərlə davam edən) olduğunu bildirir. Yüksək bacarıqlı, əhəmiyyətli resurslara malik hücumçulardır — bir dövlətin işçi qüvvəsi, vaxtı və pulu davamlı, mürəkkəb hücumları maliyyələşdirməyə kifayət edir. Motivasiya siyasi (ənənəvi casusluq — hədəfin müdafiə qabiliyyəti barədə məlumat toplamaq) və ya iqtisadi (əqli mülkiyyət oğurluğu) ola bilər.\n\n> **Zero-Day Hücumları:** APT hücumçuları çox vaxt öz zəiflik araşdırmalarını aparır ki, digər hücumçulara/kibertəhlükəsizlik komandalarına məlum olmayan zəiflikləri tapsınlar. Onlar tapdıqları zəifliyi ifşa etmir, sonrakı istifadə üçün saxlayırlar. Bu zəifliklərdən istifadə edən hücumlar **zero-day hücumları** adlanır — xüsusilə təhlükəlidir, çünki məhsul istehsalçılarına məlum deyil, ona görə heç bir patch mövcud deyil. Stuxnet (ABŞ və İsrail hökumətlərinə aid edilir, İranın uran zənginləşdirmə obyektinin nəzarət şəbəkələrini kompromis edib) bu növün ən tanınan nümunəsidir.\n\n**Insider Threat** — İşçi, podratçı, satıcı və ya sistemlərə icazəli çıxışı olan istənilən şəxsin bu çıxışdan təşkilata qarşı hücum üçün istifadə etməsi. Adətən konfidensial məlumatı ifşa etməyə yönəlib, amma insayder məlumatı dəyişdirməyə və ya biznes proseslərini pozmağa da cəhd edə bilər. İnsayder istənilən bacarıq səviyyəsində ola bilər. Davranış qiymətləndirmələri insayder hücumları müəyyən etməkdə güclü alətdir — kibertəhlükəsizlik komandaları İnsan Resursları ilə işləməlidir ki, qeyri-adi davranış göstərən insayderləri müəyyənləşdirib vəziyyət kəskinləşməzdən əvvəl müdaxilə etsin.\n\n**Shadow IT** — Bəzən işçilər öz məqsədlərinə çatmaq üçün təşkilat tərəfindən təsdiqlənməmiş texnologiya xidmətləri satın alırlar (məsələn, iş faylını şəxsi Dropbox hesabı ilə sinxronlaşdırmaq) — bu, zərərli niyyətlə edilmir, əksinə, məhsuldarlığı artırmaq cəhdidir. Amma bu, həssas məlumatı təşkilatın nəzarətindən kənar satıcıların əlinə verdiyi üçün risk yaradır. Shadow IT-in mövcudluğu, korporativ IT komandasının biznes ehtiyaclarını qarşılamadığının göstəricisidir — shadow IT istifadəçiləri ilə məsləhətləşmək çox vaxt həm biznes ehtiyacını, həm təhlükəsizlik tələbini ödəyən qəbuledilən alternativlər tapmağa kömək edir.\n\n**Competitors** — Rəqiblər, sizin təşkilatınızdan həssas məlumatı oğurlayıb öz biznes üstünlüklərinə çevirmək üçün korporativ casusluqla məşğul ola bilər (müştəri məlumatının oğurlanması, məxfi proqram təminatının oğurlanması, məhsul inkişaf planlarının aşkarlanması). Bəzən narazı insayderdən istifadə edir, bəzən isə dark web-də satılan insayder məlumatını satın alırlar.\n\n**Sual 1**\nYeddi threat actor növünü sadalayın.\n\n**Sual 2**\nAPT termini nəyi bildirir (hər hərfi izah edin) və Stuxnet nümunəsi bunu necə əks etdirir?\n\n**Sual 3**\nShadow IT-in mövcudluğu təşkilat üçün hansı əlavə siqnalı verir — sadəcə təhlükəsizlik riski, yoxsa daha geniş bir problem?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-exploring-cybersecurity-threats-awtqxg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Hücumçu Motivasiyaları','70 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"Kitab hücumçuların hərəkətlərinin arxasındakı əsas motivasiyaları doqquz kateqoriyaya bölür:\n\n| Motivasiya | Təsvir |\n|---|---|\n| **Data exfiltration** | Həssas/məxfi məlumatı (müştəri datası, əqli mülkiyyət) əldə etmək istəyi |\n| **Espionage** | Digər təşkilatlardan sirli məlumat oğurlamaq (dövlətlərarası və ya korporativ) |\n| **Service disruption** | Kritik sistem/şəbəkələri (bank, səhiyyə) dayandırmaq/pozmaq |\n| **Blackmail** | Həssas məlumatı ifşa etmə/əlavə hücum hədəsi ilə pul/güzəşt tələb etmək |\n| **Financial gain** | Oğurluq/fırıldaqla pul qazanmaq (mütəşəkkil cinayətin əsas motivasiyası) |\n| **Philosophical/political belief** | İdeoloji/siyasi səbəb (hacktivistlərin əsas motivasiyası) |\n| **Ethical (white-hat)** | Zəiflikləri ifşa edib təhlükəsizliyi yaxşılaşdırmaq (icazə ilə) |\n| **Revenge** | Şəxs/təşkilatdan qisas almaq, utandırmaq |\n| **Disruption/chaos** | Sadəcə xaos yaratmaq, normal əməliyyatı pozmaq istəyi |\n\nBunlara əlavə olaraq, **müharibə** də kibertəhlükəsizlik hücumlarının motivasiyası ola bilər — hərbi bölmələr və mülki qruplar hərbi əməliyyatları pozmaq və silahlı münaqişənin nəticəsini dəyişdirmək üçün hacking istifadə edə bilər.\n\nMotivasiyanı anlamaq, təşkilatın nəyin hədəf ola biləcəyini və özünü necə müdafiə edəcəyini müəyyənləşdirməyə kömək edir — kitab vurğulayır ki, bu, Task 2-dəki threat actor növləri ilə əl-ələ işləyir (məsələn, hacktivist → philosophical/political; organized crime → financial gain).\n\n**Sual 1**\nDoqquz motivasiya kateqoriyasından beşini sadalayın.\n\n**Sual 2**\n\"Ethical\" motivasiya digər səkkiz kateqoriyadan nə ilə fərqlənir?\n\n**Sual 3**\nBir nation-state APT hücumunun motivasiyası, adətən hansı iki kateqoriyaya uyğun gəlir?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-exploring-cybersecurity-threats-awtqxg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,4,'Threat Vectors və Attack Surface','70 dəq (kitabın bu bölməsi geniş olduğu üçün 4 task-a bölünüb)',0,'[{"body":"Threat actor-ların təşkilatın məlumat/sistemlərinə çatmaq üçün müəyyən vasitəyə ehtiyacı var. Əvvəlcə **attack surface** (hücum səthi) — hücumçunun istismar edə biləcəyi zəifliyi olan sistem, tətbiq və ya xidmət — kəşf edilməlidir. Sonra, həmin zəifliklərdən birini **threat vector** (təhdid vektoru) — hücumçuların çıxış əldə etmək üçün istifadə etdiyi vasitə — vasitəsilə istismar edərək çıxış əldə edilir. Təhlükəsizlik mütəxəssislərinin məqsədlərindən biri effektiv təhlükəsizlik tədbirləri və risk azaltma strategiyaları vasitəsilə attack surface-in ölçüsünü və mürəkkəbliyini azaltmaqdır.\n\nKitab əsas threat vector kateqoriyalarını təqdim edir:\n\n**Message-Based** — Email ən çox istismar olunan vektorlardan biridir (phishing, spam). Bu hücumlar icrası asandır və eyni anda çoxlu istifadəçiyə qarşı işə salına bilər — hücumçu üçün üstünlük budur ki, geniş hücumu başlatmaq üçün yalnız **bir dəfə** uğur qazanmaq kifayətdir. İstifadəçilərin 99.9%-i phishing mesajını görməzdən gəlsə belə, hücumçuya yalnız bir istifadəçinin giriş məlumatları lazımdır. SMS/instant messaging (smishing) və səsli zənglər (vishing) də bu kateqoriyaya aiddir.\n\n**Wired Networks** — Cəsarətli hücumçular təşkilatın fiziki obyektinə daxil olub, məsələn, foyedəki qorunmasız şəbəkə rozetkasına gizlicə qoşularaq birbaşa şəbəkə çıxışı əldə edə bilər. Fiziki toxunuş əldə edən hücumçu, həmin cihazı kompromis edib zərərli məqsədlərlə istifadə edə bilər deyə fərz olunmalıdır.\n\n**Wireless Networks** — Daha da asan yoldur — hücumçu fiziki binaya girmək məcburiyyətində deyil, avtomobil dayanacağından oturub şəbəkəyə qoşula bilər. Qorunmasız/zəif qorunan wireless şəbəkələr ciddi risk yaradır.\n\n**Systems** — Fərdi sistemlər öz konfiqurasiyasına/quraşdırılmış proqram təminatına görə threat vector rolunu oynaya bilər (açıq portlar, default credential-lar, patch olunmamış proqram, dəstəklənməyən legacy sistemlər).\n\n**Files and Images** — Fərdi fayllar (şəkillər daxil) zərərli kod daşıya bilər — hücumçu istifadəçini bu faylı açmağa aldadır.\n\n**Removable Devices** — USB flash-lar kimi çıxarıla bilən medialar. Klassik nümunə: hücumçu ucuz USB-ləri avtomobil dayanacağında/hava limanında qəsdən \"itirir\", kimsə maraqla onu tapıb kompüterinə taxanda, cihaz sakitcə kompüteri kompromis edib hücumçunun nəzarətinə keçirir.\n\n**Cloud** — Hücumçular populyar bulud xidmətlərini səhv giriş nəzarəti, təhlükəsizlik zəiflikləri və ya təsadüfən dərc edilmiş API açarları/parollar üçün rutin skan edir.\n\n**Supply Chain** — Ən mürəkkəb vektorlardan biri. Mürəkkəb hücumçular təchizat zəncirinə (hardware/software/xidmət provayderləri) müdaxilə edə bilər — hücumçu istehsalçı səviyyəsində və ya çatdırılma zamanı cihaza müdaxilə edərək backdoor əlavə edə bilər ki, müştəri onu şəbəkəsinə qoşanda hücumçuya nəzarət versin. Software provayderlər də hədəf ola bilər — rəsmi yeniləmə mexanizmi vasitəsilə backdoor yerləşdirilə bilər. Managed Service Provider-lərə (MSP) sızan hücumçular, MSP-nin öz müştərilərinin sistemlərinə olan çıxışından istifadə edə bilər.\n\n| Vector | Nümunə | Əsas müdafiə istiqaməti |\n|---|---|---|\n| Message-Based | Phishing email | İstifadəçi təlimi, email filtrasiyası |\n| Wired Networks | Foyedəki açıq rozetka | Fiziki təhlükəsizlik, port təhlükəsizliyi (Module 9) |\n| Wireless | Zəif qorunan Wi-Fi | Güclü şifrələmə (Module 13) |\n| Systems | Patch olunmamış OS | Hardening (Module 11) |\n| Files/Images | Zərərli əlavə | Anti-malware, sandbox |\n| Removable Devices | \"İtirilmiş\" USB | Cihaz nəzarəti siyasəti (Module 11) |\n| Cloud | Açıq S3 bucket | Konfiqurasiya auditi (Module 10) |\n| Supply Chain | Backdoor-lu hardware | Vendor idarəetməsi (GRC path Module 5) |\n\n**Sual 1**\nAttack surface və threat vector arasındakı fərq nədir?\n\n**Sual 2**\nMessage-based hücumların hücumçu üçün əsas üstünlüyü nədir — niyə 99.9% uğursuzluq hücumçunu narahat etmir?\n\n**Sual 3**\nSupply chain hücumu niyə xüsusilə təhlükəlidir və aşkar etmək çətindir?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Threat actor-ları təsnif etmək üçün istifadə olunan dörd atributu sadalayın.\n2. White-hat, black-hat və gray-hat arasındakı fərqi izah edin.\n3. Zero-day hücumu nədir və niyə xüsusilə təhlükəlidir?\n4. Insider threat və Shadow IT arasındakı fərq nədir?\n5. Doqquz motivasiya kateqoriyasından üçünü sadalayın.\n6. Removable Device vector-un klassik nümunəsini təsvir edin.\n7. Supply chain hücumunda MSP-nin (Managed Service Provider) roluna necə hücum edilə bilər?\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-exploring-cybersecurity-threats-awtqxg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO paths(slug,title,description,category,status,order_index) VALUES ('comptia-security-plus','CompTIA Security+','CompTIA Security+ kurikulumu','CompTIA Security+' ,'PUBLISHED',2) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-1','MODULE 1: Today''s Security Professional (Fəsil 1)','PUBLISHED',1 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-data-protection-oyetzc','Data Protection','Data Protection','CompTIA Security+ · MODULE 1: Today''s Security Professional (Fəsil 1)','Fəsil 1-in son room-u. İndiyə qədər kibertəhlükəsizliyin **məqsədlərini** (CIA), **təhdid modellərini** (DAD, Breach Impact) və **nəzarət təsnifatını** (Category/Type) öyrəndiniz. Bu room bunları ən konkret, əl ilə toxuna biləcəyiniz obyektə — **məlumatın özünə** — tətbiq edir. Kibertəhlükəsizlik mütəxəssisləri vaxtlarının böyük hissəsini həssas məlumatın qorunmasına həsr edirlər — bu room-da məlumatın hansı "vəziyyətlərdə" olduğunu, onu necə qoruduğumuzu (şifrələmə, DLP, obfuskasiya) və giriş məhdudiyyətlərini öyrənəcəksiniz.','CompTIA Security+','WALKTHROUGH','INTERMEDIATE'::difficulty,'35 dəq',0,'GREEN',ARRAY['Məlumatın üç vəziyyətini (at rest, in transit, in use) fərqləndirmək','DLP sistemlərinin iki mühitini (agent-based, agentless) və iki mexanizmini (pattern matching, watermarking) izah etmək','Data Minimization texnikalarını (hashing, tokenization, masking) fərqləndirmək və hər birinin zəif nöqtəsini bilmək','Access Restriction (geographic, permission) və Segmentation/Isolation anlayışlarını tətbiq etmək']::text[],'drive/123xLgARe-0xlD5id4KZtPK5PMzOyEtzC.md','PUBLISHED',4,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-1' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Məlumatın Üç Vəziyyəti','35 dəq',0,'[{"body":"# ROOM 4: Data Protection\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 1 — Today''s Security Professional (Fəsil 1)\n**Mənbə:** CompTIA Security+ Study Guide, 9th Ed. — \"Data Protection\" bölməsi\n**Domain uyğunluğu:** 1.0 General Security Concepts (12%) / 3.0 Security Architecture (18%) — obyektiv 3.3\n**Çətinlik:** Easy→Medium\n**Təxmini vaxt:** 35 dəq\n\n## Room haqqında\n\nFəsil 1-in son room-u. İndiyə qədər kibertəhlükəsizliyin **məqsədlərini** (CIA), **təhdid modellərini** (DAD, Breach Impact) və **nəzarət təsnifatını** (Category/Type) öyrəndiniz. Bu room bunları ən konkret, əl ilə toxuna biləcəyiniz obyektə — **məlumatın özünə** — tətbiq edir. Kibertəhlükəsizlik mütəxəssisləri vaxtlarının böyük hissəsini həssas məlumatın qorunmasına həsr edirlər — bu room-da məlumatın hansı \"vəziyyətlərdə\" olduğunu, onu necə qoruduğumuzu (şifrələmə, DLP, obfuskasiya) və giriş məhdudiyyətlərini öyrənəcəksiniz.\n\n## Öyrənmə nəticələri\n\n- Məlumatın üç vəziyyətini (at rest, in transit, in use) fərqləndirmək\n- DLP sistemlərinin iki mühitini (agent-based, agentless) və iki mexanizmini (pattern matching, watermarking) izah etmək\n- Data Minimization texnikalarını (hashing, tokenization, masking) fərqləndirmək və hər birinin zəif nöqtəsini bilmək\n- Access Restriction (geographic, permission) və Segmentation/Isolation anlayışlarını tətbiq etmək\n\nMəlumat qorunma texnikalarını düşünərkən, kitab əvvəlcə məlumatın harada/necə mövcud ola biləcəyini nəzərdən keçirməyi tövsiyə edir — çünki hər vəziyyət fərqli təhlükə profilinə malikdir.\n\n**Data at Rest (Sükunətdə Məlumat)** — sərt disklərdə, lentlərdə, buludda və ya digər saxlama mediasında saxlanılan məlumat. Bu, sistemlərə çıxış əldə edən insayderlər və ya xarici hücumçular tərəfindən oğurluğa məruz qalır — onlar məzmunu \"gəzə\" bilirlər.\n\n**Data in Transit (Ötürülmədə Məlumat)** — şəbəkə üzərində hərəkətdə olan məlumat. Etibarsız şəbəkə üzərində gedərkən, bu, həmin şəbəkəyə çıxışı olan istənilən şəxs tərəfindən dinləmə (eavesdropping) hücumlarına açıqdır.\n\n**Data in Use (İstifadədə Məlumat)** — hazırda kompüter sistemi tərəfindən aktiv istifadə olunan məlumat, o cümlədən emal zamanı yaddaşda saxlanılan məlumat. Sistemə nəzarəti olan hücumçu yaddaşın məzmununu oxuyub həssas məlumatı oğurlaya bilər.\n\n| Vəziyyət | Harada | Əsas təhlükə |\n|---|---|---|\n| At Rest | Disk, lent, bulud | İnsayder/xarici hücumçunun \"gəzməsi\" |\n| In Transit | Şəbəkə üzərində | Dinləmə (eavesdropping) |\n| In Use | RAM/proses yaddaşı | Yaddaş məzmununun oxunması |\n\nBu üç vəziyyət path boyu daim geri qayıdacağınız fundamental çərçivədir — Module 6-da (Application Security) və Module 7-də (Cryptography) hər vəziyyət üçün fərqli şifrələmə yanaşmalarını (disk şifrələməsi, TLS, homomorfik şifrələmə) görəcəksiniz.\n\n**Sual 1**\nMəlumatın üç vəziyyətini sadalayın və hər birinin əsas təhlükəsini yazın.\n\n**Sual 2**\n\"Data in use\" nə deməkdir və niyə bu vəziyyət xüsusi çətinlik yaradır?\n\n**Sual 3**\nNiyə eyni məlumat fərqli vəziyyətlərdə fərqli qorunma texnikası tələb edə bilər?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-data-protection-oyetzc' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'DLP: Data Loss Prevention Sistemləri','35 dəq',0,'[{"body":"**DLP (Data Loss Prevention)** — təşkilatların məlumat itkisi/oğurluğunun qarşısını almaq üçün məlumat idarəetmə siyasətlərini icra etməsinə kömək edən sistemlərdir. Onlar sistemlərdə qorunmamış həssas məlumatı axtarır və şəbəkə trafikini izləyir ki, məlumatın təşkilatdan çıxarılması cəhdlərini aşkarlasın.\n\nDLP iki fərqli mühitdə işləyir:\n\n**Agent-Based DLP** — sistemlərə quraşdırılmış proqram agentləri vasitəsilə işləyir, bu agentlər sistemlərdə həssas məlumatın (sosial sığorta nömrəsi, kart nömrəsi) izlərini axtarır. Bu, gözlənilməz yerlərdə tapılan həssas məlumatın erkən aşkarlanmasına imkan verir — cihaz itirilsə/oğurlansa/kompromis olsa belə, əvvəlcədən şifrələnmiş/silinmiş olarsa, zərər azalır. Agent-based DLP həmçinin sistem konfiqurasiyasını və istifadəçi hərəkətlərini monitorinq edə bilər — məsələn, host-based DLP istifadəçilərin USB removable media cihazlarına çıxışını bloklaya bilər.\n\n**Agentless (Network-Based) DLP** — şəbəkədə yerləşən, çıxan trafiki izləyən xüsusi cihazlardır, şifrələnməmiş həssas məlumat ehtiva edən ötürmələri axtarır və bloklayır.\n\nDLP sistemləri sadəcə siyasəti pozan trafiki bloklaya bilər, bəzi hallarda isə avtomatik şifrələmə tətbiq edə bilər (bu, email-ə fokuslanan DLP sistemlərində geniş yayılıb).\n\nDLP-nin iki hərəkət mexanizmi var:\n\n**Pattern Matching** — sistemlər həssas məlumatın tanınan işarələrinə baxır. Məsələn, kredit kartı və ya sosial sığorta nömrəsinə bənzər formatda rəqəm görəndə avtomatik tetiklənir; oxşar şəkildə, \"Top Secret\" və ya \"Business Confidential\" kimi həssas terminlərin bazasını saxlaya və bu terminləri çıxan ötürmədə görəndə tetiklənə bilər.\n\n**Watermarking** — sistem/administrator həssas sənədlərə elektron etiket tətbiq edir, sonra DLP sistemi bu etiketləri ehtiva edən şifrələnməmiş məzmun üçün sistem/şəbəkələri monitorinq edə bilər. Watermarking texnologiyası müəllif hüququ/mülkiyyət məhdudiyyətlərini icra edən DRM (Digital Rights Management) həllərində də geniş istifadə olunur.\n\n| | Agent-Based | Agentless (Network-Based) |\n|---|---|---|\n| Harada işləyir | Cihazın özündə | Şəbəkədə (cihazlardan kənar) |\n| Nəyi görür | Saxlanılan məlumat + istifadəçi hərəkəti | Çıxan şəbəkə trafiki |\n| Nümunə tətbiq | USB portu bloklamaq | Şifrələnməmiş email-i tutmaq |\n\n**Sual 1**\nAgent-based və Agentless DLP arasındakı fərq nədir?\n\n**Sual 2**\nPattern Matching və Watermarking arasındakı fərqi izah edin.\n\n**Sual 3**\nHost-based DLP-nin USB portlarını bloklaması hansı DLP mühitinə aiddir və bu, hansı təhlükəni azaldır?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-data-protection-oyetzc' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Data Minimization və Obfuscation Texnikaları','35 dəq',0,'[{"body":"**Data Minimization** — müntəzəm saxladığımız həssas məlumatın miqdarını azaldaraq riski azaltmaq texnikasıdır. Bunu əldə etməyin ən yaxşı yolu — məlumatı orijinal biznes məqsədinə artıq ehtiyac olmadıqda sadəcə **məhv etməkdir**.\n\nƏgər məlumatı tam silmək mümkün deyilsə, onu orijinal həssas məlumatı **\"deidentifikasiya\"** edilmiş formata çevirə bilərik — bu proses məlumatı konkret şəxslə əlaqələndirmə qabiliyyətini aradan qaldırır, onun həssaslığını azaldır.\n\nDeidentifikasiyaya alternativ, məlumatı orijinal informasiyanın **geri əldə edilə bilmədiyi** formata çevirməkdir — buna **Data Obfuscation** deyilir. Üç əsas alət:\n\n**Hashing** — hash funksiyası istifadə edərək dəyəri uyğun hash dəyərinə çevirir. Güclü hash funksiyası tətbiq etsək, fayldakı dəyəri hashlanmış dəyərlə əvəz edə bilərik.\n\n**Tokenization** — həssas dəyərləri lookup cədvəli istifadə edərək unikal identifikatorla əvəz edir. Məsələn, geniş tanınan bir dəyəri (tələbə ID-si) təsadüfi yaradılmış 10-rəqəmli nömrə ilə əvəz edə bilərik, sonra lookup cədvəlini saxlayıb lazım olduqda geri tələbə ID-sinə çevirə bilərik. Diqqət: bu yanaşmanı istifadə edirsinizsə, lookup cədvəlini təhlükəsiz saxlamalısınız!\n\n**Masking** — bəzi/bütün həssas sahələri boş simvollarla əvəz edərək məlumatı qismən redaktə edir. Məsələn, kart nömrəsinin son 4 rəqəmindən başqa hamısını X və ya * ilə əvəz edə bilərik ki, kart nömrəsi oxunmaz olsun.\n\n**Hashing-in Zəif Nöqtəsi — Rainbow Table Hücumu:** Hashlanmış dəyərdən orijinal dəyəri birbaşa əldə etmək mümkün olmasa da, bu yanaşmanın ciddi bir zəifliyi var. Əgər kimsə bir sahə üçün mümkün dəyərlərin siyahısına malikdirsə, **rainbow table hücumu** apara bilər — hücumçu namizəd dəyərlərin hash-larını hesablayır, sonra bu hash-ların bizim məlumat faylında olub-olmadığını yoxlayır.\n\nKitabın nümunəsi: fərz edin ki, kollecimizdə imtahandan kəsilmiş bütün tələbələrin siyahısı var, amma biz onların tələbə ID-lərini hashlamışıq. Əgər hücumçunun bütün tələbələrin siyahısı varsa, o, bütün tələbə ID-lərinin hash dəyərlərini hesablaya bilər, sonra hansı hash dəyərlərinin siyahıda olduğunu yoxlaya bilər. Bu səbəbdən, hashing yalnız ehtiyatla istifadə olunmalıdır.\n\n| Texnika | Necə işləyir | Geri əldə edilə bilər? | Əsas zəiflik |\n|---|---|---|---|\n| Hashing | Dəyəri hash funksiyası ilə çevirir | Xeyr (birbaşa) | Rainbow table hücumu |\n| Tokenization | Lookup cədvəli ilə unikal ID əvəz edir | Bəli (lookup cədvəli ilə) | Lookup cədvəlinin təhlükəsizliyi |\n| Masking | Sahələri qismən blank simvolla əvəz edir | Xeyr (qalan hissə görünür) | Görünən hissə hələ məlumat sıza bilər |\n\n**Sual 1**\nData Minimization-un ən sadə üsulu nədir?\n\n**Sual 2**\nTokenization-u istifadə edərkən nəyi xüsusi qorumaq lazımdır və niyə?\n\n**Sual 3**\nRainbow table hücumu necə işləyir? Kitabın tələbə ID nümunəsi ilə izah edin."}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-data-protection-oyetzc' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,4,'Access Restrictions və Segmentation','35 dəq',0,'[{"body":"Son qorunma qatı — kimin/nəyin məlumata çıxış əldə edə biləcəyini məhdudlaşdırmaqdır.\n\n**Access Restrictions** iki əsas növə bölünür:\n\n**Geographic Restrictions (Coğrafi Məhdudiyyətlər)** — istifadəçinin/sistemin fiziki yerləşməsinə əsasən resurslara çıxışı məhdudlaşdırır. Məsələn, təşkilat verilənlər bazasına çıxışı yalnız müəyyən ölkə/regionda yerləşən istifadəçilərlə məhdudlaşdıra bilər — bu, təşkilatın etibarlı şəbəkəsindən kənardan icazəsiz girişin qarşısını almağa kömək edir.\n\n**Permission Restrictions (İcazə Məhdudiyyətləri)** — istifadəçinin rolu/icazə səviyyəsinə əsasən resurslara çıxışı məhdudlaşdırır. Məsələn, bir şirkət maliyyə məlumatına çıxışı yalnız müvafiq arxa fon yoxlamalarından və təlimdən keçmiş icazəli işçilərə verə bilər. (Bu mövzu Module 8-də — Identity and Access Management — dərindən işlənəcək.)\n\nBundan əlavə, təşkilatlar həssas sistemlərə çıxışı onların **şəbəkə yerləşməsinə** əsasən də məhdudlaşdıra bilər:\n\n**Segmentation (Seqmentasiya)** — həssas sistemləri ayrı şəbəkələrdə yerləşdirir, burada onlar bir-biri ilə əlaqə saxlaya bilər, amma digər şəbəkələrdəki sistemlərlə əlaqə saxlamaq üçün sərt məhdudiyyətlərə malikdirlər.\n\n**Isolation (İzolyasiya)** — bir addım daha irəli gedir və sistemi xarici şəbəkələrə/xarici şəbəkələrdən çıxışdan tamamilə kəsir.\n\nBunu bir bina təhlükəsizliyi analoji ilə görün: Access Restrictions — girişdə kimlik yoxlanması (\"bu binaya kimlər girə bilər\"). Segmentation — binanın daxilində müxtəlif otaqların açar kartları ilə ayrılması (mühasibatlıq otağına yalnız müəyyən kartla girmək olar, amma bina daxilində hərəkət mümkündür). Isolation isə tam ayrı, xüsusi girişi olan, əsas binadan fiziki cəhətdən təcrid olunmuş bir otaqdır (Module 1, Room 3-dəki compensating control nümunəsini — köhnəlmiş OS-in izolə edilmiş şəbəkədə saxlanması — xatırlayın, bu, Isolation-un praktiki tətbiqidir).\n\n**Sual 1**\nGeographic və Permission Restrictions arasındakı fərq nədir?\n\n**Sual 2**\nSegmentation və Isolation arasındakı fərq nədir?\n\n**Sual 3**\nRoom 3-dəki compensating control nümunəsi (köhnəlmiş OS-in izolə edilmiş şəbəkədə saxlanması) hansı konseptin praktiki tətbiqidir?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Məlumatın üç vəziyyətini sadalayın.\n2. Agent-based və Agentless DLP arasındakı fərq nədir?\n3. Hashing, Tokenization və Masking arasındakı fərqi bir cümlə ilə hər biri üçün yazın.\n4. Rainbow table hücumu nədir?\n5. Segmentation və Isolation arasındakı fərqi izah edin.\n6. Bir kredit kartı nömrəsinin son 4 rəqəmindən başqa hamısını X ilə əvəz etmək hansı texnikaya aiddir?\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-data-protection-oyetzc' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
