INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-1','MODULE 1: Today''s Security Professional (Fəsil 1)','PUBLISHED',1 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-implementing-security-controls-g9r5cg','Implementing Security Controls','Implementing Security Controls','CompTIA Security+ · MODULE 1: Today''s Security Professional (Fəsil 1)','Room 1-2-də kibertəhlükəsizliyin məqsədlərini (CIA) və təhdid/təsir modellərini (DAD, Breach Impact) öyrəndiniz. İndi sual budur: bu məqsədlərə çatmaq üçün konkret olaraq **nə** qururuq? Cavab — Security Controls (təhlükəsizlik nəzarətləri). Bu room-da CompTIA-nın özünəməxsus nəzarət təsnifat sistemini — dörd Kateqoriya (necə hərəkət edir) və altı Tip (nəyə nail olur) — öyrənəcəksiniz. Bu, imtahanda ən çox sınanan mövzulardan biridir.','CompTIA Security+','WALKTHROUGH','INTERMEDIATE'::difficulty,'40 dəq',0,'GREEN',ARRAY['Gap Analysis konseptini və onun nəzarət qiymətləndirməsindəki rolunu izah etmək','Dörd Security Control Kateqoriyasını (Technical, Operational, Managerial, Physical) fərqləndirmək','Altı Security Control Tipini (Preventive, Deterrent, Detective, Corrective, Compensating, Directive) fərqləndirmək','Compensating Control konseptini real nümunə (PCI DSS) ilə izah etmək','Real ssenaridə bir nəzarəti həm Kateqoriya, həm Tip üzrə düzgün təsnif etmək']::text[],'drive/13L7yCvl5S-J3wq_i8Q-jYaEneYG9r5cg.md','PUBLISHED',3,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-1' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Gap Analysis: Nəzarətin Kifayət Etdiyini Necə Bilirik?','40 dəq',0,'[{"body":"# ROOM 3: Implementing Security Controls\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 1 — Today''s Security Professional (Fəsil 1)\n**Mənbə:** CompTIA Security+ Study Guide, 9th Ed. — \"Implementing Security Controls\" bölməsi\n**Domain uyğunluğu:** 1.0 General Security Concepts (12%) — obyektiv 1.1\n**Çətinlik:** Easy→Medium\n**Təxmini vaxt:** 40 dəq\n\n## Room haqqında\n\nRoom 1-2-də kibertəhlükəsizliyin məqsədlərini (CIA) və təhdid/təsir modellərini (DAD, Breach Impact) öyrəndiniz. İndi sual budur: bu məqsədlərə çatmaq üçün konkret olaraq **nə** qururuq? Cavab — Security Controls (təhlükəsizlik nəzarətləri). Bu room-da CompTIA-nın özünəməxsus nəzarət təsnifat sistemini — dörd Kateqoriya (necə hərəkət edir) və altı Tip (nəyə nail olur) — öyrənəcəksiniz. Bu, imtahanda ən çox sınanan mövzulardan biridir.\n\n## Öyrənmə nəticələri\n\n- Gap Analysis konseptini və onun nəzarət qiymətləndirməsindəki rolunu izah etmək\n- Dörd Security Control Kateqoriyasını (Technical, Operational, Managerial, Physical) fərqləndirmək\n- Altı Security Control Tipini (Preventive, Deterrent, Detective, Corrective, Compensating, Directive) fərqləndirmək\n- Compensating Control konseptini real nümunə (PCI DSS) ilə izah etmək\n- Real ssenaridə bir nəzarəti həm Kateqoriya, həm Tip üzrə düzgün təsnif etmək\n\nTəşkilat öz risk mühitini təhlil edəndən sonra, texniki və biznes liderləri məlumatın CIA-sını qorumaq üçün lazım olan qorunma səviyyəsini müəyyən edirlər. Bunlar **control objectives** (nəzarət obyektivləri) adlanır — arzu olunan təhlükəsizlik vəziyyətinin bəyanatlarıdır, amma özləri heç bir fəaliyyəti həyata keçirmir. **Security Controls** isə bu obyektivləri həqiqətən yerinə yetirən konkret tədbirlərdir.\n\n**Gap Analysis** — kibertəhlükəsizlik mütəxəssisinin nəzarət obyektivlərini nəzərdən keçirib, mövcud nəzarətlərin bu obyektivlərə həqiqətən nail olub-olmadığını yoxlaması prosesidir. Əgər nəzarət obyektivi ilə real nəzarət arasında uyğunsuzluq varsa, bu, bir **gap** (boşluq) sayılır.\n\nBunu bir tikinti analoji ilə görək: control objective — memarın çertyojudur (\"bu divar odadavamlı olmalıdır\"). Security control — faktiki tikilən divardır. Gap Analysis isə inspektorun gəlib divarı yoxlamasıdır — \"çertyojda deyilən materialdan tikilibmi, yoxsa ucuz alternativ istifadə olunub?\" Əgər fərq varsa, bu, gap-dir və düzəldilməlidir.\n\nTapılan boşluqlar potensial risk kimi qəbul edilməli və resurs/vaxt imkan verdikcə aradan qaldırılmalıdır (bu proses, remediation, Module 5-də — Security Assessment and Testing — ətraflı işlənəcək).\n\n**Sual 1**\nControl objective ilə security control arasındakı fərq nədir?\n\n**Sual 2**\nGap Analysis nə edir və nəticəsində nə tapılır?\n\n**Sual 3**\nTikinti analogiyasında \"inspektor\" hansı rolu təmsil edir?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-implementing-security-controls-g9r5cg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Security Control Kateqoriyaları: Necə Hərəkət Edir?','40 dəq',0,'[{"body":"CompTIA nəzarətləri onların **hərəkət mexanizminə** görə dörd kateqoriyaya bölür. Diqqət: bu təsnifat CompTIA-ya məxsusdur — əgər başqa sertifikat üçün oxşar (amma fərqli adlanan) təsnifat öyrənmisinizsə, bunları qarışdırmayın, imtahanda dəqiq CompTIA terminologiyası tələb olunur.\n\n**Technical (Texniki) nəzarətlər** — rəqəmsal sahədə CIA-nı təmin edir. Nümunələr: firewall qaydaları, giriş nəzarəti siyahıları (ACL), müdaxilənin qarşısını alma sistemləri (IPS), şifrələmə.\n\n**Operational (Əməliyyat) nəzarətləri** — texnologiyanı təhlükəsiz idarə etmək üçün qurduğumuz proseslər. Nümunələr: istifadəçi giriş icazələrinin dövri yoxlanması, log monitorinqi, zəiflik idarəetməsi.\n\n**Managerial (İdarəetmə) nəzarətləri** — risk idarəetmə prosesinin mexanikasına fokuslanan prosedur mexanizmləri. Nümunələr: dövri risk qiymətləndirmələri, təhlükəsizlik planlaşdırma tədbirləri, dəyişiklik idarəetməsi/satınalma/layihə idarəetməsi proseslərinə təhlükəsizliyin inteqrasiyası.\n\n**Physical (Fiziki) nəzarətlər** — fiziki dünyaya təsir edən nəzarətlər. Nümunələr: hasarlar, perimetr işıqlandırması, qıfıllar, yanğınsöndürmə sistemləri, oğru siqnalizasiyası.\n\n| Kateqoriya | Sahə | Nümunələr |\n|---|---|---|\n| Technical | Rəqəmsal/sistem | Firewall, ACL, şifrələmə, IPS |\n| Operational | Proseslər (texnologiyanı idarə edən) | Giriş icazəsi baxışı, log monitorinqi |\n| Managerial | Risk idarəetmə mexanikası | Risk qiymətləndirmə, planlaşdırma |\n| Physical | Fiziki dünya | Hasar, qıfıl, yanğınsöndürmə |\n\n**Vacib nüans:** Bir control objective çox vaxt **bir neçə kateqoriyanın kombinasiyasını** tələb edir. Kitabın nümunəsi: \"data mərkəzinə icazəsiz girişin qarşısını almaq\" məqsədinə çatmaq üçün təşkilat həm biometrik qıfıllar (Physical), həm icazəli girişlərin müntəzəm nəzərdən keçirilməsi (Operational), həm dövri risk qiymətləndirmələri (Managerial) tətbiq edə bilər. Tək kateqoriya nadir hallarda kifayət edir.\n\n**Sual 1**\nDörd Security Control Kateqoriyasını sadalayın və hər birinə bir nümunə verin.\n\n**Sual 2**\n\"Log monitorinqi\" hansı kateqoriyaya aiddir və niyə?\n\n**Sual 3**\nNiyə bir control objective çox vaxt bir neçə kateqoriyanın kombinasiyasını tələb edir? Kitabın data mərkəzi nümunəsi ilə izah edin."}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-implementing-security-controls-g9r5cg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Security Control Tipləri: Nəyə Nail Olur?','40 dəq',0,'[{"body":"Kateqoriyalardan fərqli olaraq (necə hərəkət edir), CompTIA nəzarətləri **arzu olunan effektə** görə də təsnif edir — altı tip var:\n\n**Preventive (Qarşısını alan)** — problemin baş verməsinin qarşısını əvvəlcədən alır. Nümunə: firewall, şifrələmə.\n\n**Deterrent (Çəkindirici)** — hücumçunun cəhd etməsinin qarşısını (psixoloji/görünüş baxımından) alır. Nümunə: aqressiv keşik iti, tikanlı məftil hasarı.\n\n**Detective (Aşkarlayıcı)** — artıq baş vermiş təhlükəsizlik hadisələrini müəyyən edir. Nümunə: müdaxilənin aşkarlanması sistemi (IDS).\n\n**Corrective (Düzəldici)** — artıq baş vermiş problemi aradan qaldırır. Nümunə: ransomware hücumundan sonra backup-dan bərpa etmək.\n\n**Compensating (Kompensasiyaedici)** — təhlükəsizlik siyasətinə edilən istisnalarla bağlı riski azaltmaq üçün qurulan nəzarətlər (Task 4-də dərindən işlənəcək).\n\n**Directive (İstiqamətləndirici)** — işçilərə və digərlərinə təhlükəsizlik obyektivlərinə necə nail olacaqlarını bildirir. Nümunə: siyasətlər və prosedurlar (GRC path-dəki Policy/Procedure konseptlərini xatırlayın).\n\n| Tip | Nə vaxt işə düşür | Nümunə |\n|---|---|---|\n| Preventive | Problem baş verməzdən əvvəl | Firewall, şifrələmə |\n| Deterrent | Cəhddən əvvəl (psixoloji) | Keşik iti, tikanlı məftil |\n| Detective | Problem baş verdikdən sonra (aşkarlama) | IDS |\n| Corrective | Problem baş verdikdən sonra (düzəltmə) | Backup-dan bərpa |\n| Compensating | Standart nəzarət mümkün olmayanda | Alternativ, izolə edilmiş şəbəkə |\n| Directive | Davamlı (istiqamətləndirmə) | Siyasət, prosedur |\n\n**Preventive vs Deterrent fərqi (tez-tez qarışdırılır):** Preventive nəzarət hücumu **texniki olaraq mümkünsüz** edir (firewall paketi blokla), Deterrent isə hücumçunu **cəhd etməkdən çəkindirir**, amma texniki olaraq maneə olmaya bilər (bir tabelo \"Bu sahə kameralarla izlənilir\" yazır — hücumçunu ruhdan salır, amma fiziki olaraq onu dayandırmır).\n\n**Detective vs Corrective fərqi:** hər ikisi problem baş verdikdən **sonra** işləyir, amma Detective yalnız \"bu baş verib\" deyir (aşkarlayır), Corrective isə problemi həll edir (düzəldir). IDS sizə \"hücum var\" deyir (Detective) — bu, hücumu dayandırmır. Backup-dan bərpa isə artıq zədələnmiş sistemi əvvəlki vəziyyətinə qaytarır (Corrective).\n\n**Sual 1**\nAltı Security Control Tipini sadalayın.\n\n**Sual 2**\nPreventive və Deterrent nəzarətlər arasındakı fərqi bir nümunə ilə izah edin.\n\n**Sual 3**\nIDS (Intrusion Detection System) hansı tipə aiddir və niyə bu, \"problemi həll edir\" demək deyil?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-implementing-security-controls-g9r5cg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,4,'Compensating Controls: Dərin Baxış','40 dəq',0,'[{"body":"Kitab Compensating Control-lara xüsusi diqqət ayırır, çünki bu konsept praktiki GRC işində çox vaxt yanlış başa düşülür.\n\n**Compensating control** — təşkilat orijinal tələbə (standart nəzarətə) tam əməl edə bilmədikdə, riskin əvəzini ödəmək üçün istifadə olunan alternativ nəzarətdir.\n\nKitab PCI DSS-in (Payment Card Industry Data Security Standard) bu sahədə ən formal prosesə malik olduğunu qeyd edir — PCI DSS compensating control-un qəbul edilməsi üçün üç meyar qoyur:\n\n```\n1. Nəzarət orijinal tələbin MƏQSƏDİNƏ və SƏRTLİYİNƏ uyğun olmalıdır\n2. Nəzarət orijinal tələbin qarşısını almaq istədiyi riski \n   KİFAYƏT QƏDƏR kompensasiya edən müdafiə səviyyəsi təmin etməlidir\n3. Nəzarət digər PCI DSS tələblərindən \"ARTIQ VƏ ƏLAVƏ\" olmalıdır\n```\n\n**Praktiki nümunə (kitabdan):** Bir təşkilat müəyyən bir maşında köhnəlmiş əməliyyat sistemi işlətməli olur, çünki biznes üçün zəruri proqram təminatı yalnız həmin OS versiyasında işləyir. Əksər təhlükəsizlik siyasətləri köhnəlmiş OS-in istifadəsini qadağan edir (çünki bilinən zəifliklərə həssasdır). Təşkilat bu sistemi digər sistemlərlə minimal/heç bir əlaqəsi olmayan **izolə edilmiş şəbəkədə** saxlamağı compensating control kimi seçə bilər.\n\nBu nümunənin göstərdiyi ümumi məntiq: compensating control, hər tələb olunan nəzarəti hər şəraitdə tətbiq etməyin **mümkün olmadığı** reallığı ilə riski mümkün qədər idarə etmək **istəyi** arasında balans yaradır. Bir çox təşkilat (PCI DSS-ə tabe olmasa belə) bu strategiyanı istifadə edir.\n\nVacib əlavə qeyd: compensating control adətən **müvəqqəti istisnaya** cavab kimi qəbul edilir — təşkilat paralel olaraq orijinal tələbin hərfi mənasına və niyyətinə tam uyğunluğu bərpa edəcək **remediation planı** hazırlamalıdır. Yəni compensating control \"əbədi həll\" yox, \"keçid dövrü həlli\" kimi düşünülməlidir.\n\n**Sual 1**\nCompensating control nədir və nə vaxt istifadə olunur?\n\n**Sual 2**\nPCI DSS-in compensating control üçün qoyduğu üç meyarı sadalayın.\n\n**Sual 3**\nKöhnəlmiş OS nümunəsində izolə edilmiş şəbəkə niyə \"əbədi həll\" deyil, \"keçid dövrü həlli\" kimi düşünülməlidir?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Gap Analysis nə edir?\n2. Dörd Security Control Kateqoriyasını sadalayın.\n3. Altı Security Control Tipini sadalayın.\n4. Preventive və Corrective nəzarətlər arasındakı əsas fərq nədir?\n5. Compensating control-un PCI DSS üzrə üç qəbul meyarını yazın.\n6. Data mərkəzinə girişi qorumaq üçün istifadə olunan \"biometrik qıfıl\" hansı Kateqoriyaya, \"dövri risk qiymətləndirməsi\" isə hansı Kateqoriyaya aiddir?\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-implementing-security-controls-g9r5cg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO paths(slug,title,description,category,status,order_index) VALUES ('comptia-security-plus','CompTIA Security+','CompTIA Security+ kurikulumu','CompTIA Security+' ,'PUBLISHED',2) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-1','MODULE 1: Today''s Security Professional (Fəsil 1)','PUBLISHED',1 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-data-breach-risks-2m4kjg','Data Breach Risks','Data Breach Risks','CompTIA Security+ · MODULE 1: Today''s Security Professional (Fəsil 1)','Room 1-də CIA Triadını (Confidentiality, Integrity, Availability) öyrəndiniz — bunlar kibertəhlükəsizliyin **məqsədləridir**. İndi sual budur: bu məqsədlər pozulanda (yəni bir təhlükəsizlik insidenti/breach baş verəndə), bunun konkret **təhdid növü** və **biznes təsiri** nədir? Bu room-da kitabın təqdim etdiyi iki tamamlayıcı çərçivəni — DAD Triadı (CIA-nın "əks üzü") və Breach Impact kateqoriyalarını (maliyyə, reputasiya, strateji, əməliyyat, uyğunluq) öyrənəcəksiniz.','CompTIA Security+','WALKTHROUGH','BEGINNER'::difficulty,'30 dəq',0,'GREEN',ARRAY['DAD Triadının (Disclosure, Alteration, Denial) CIA ilə necə güzgü münasibətində olduğunu izah etmək','DAD Triadını real ssenaridə risk təhlili aləti kimi tətbiq etmək','Breach-in beş təsir kateqoriyasını (Financial, Reputational, Strategic, Operational, Compliance) fərqləndirmək','Real bir insidentdə niyə risklərin çox vaxt bir neçə kateqoriyanı eyni anda kəsdiyini izah etmək']::text[],'drive/1F6KgG5aZhTpqETe4w0-7Tis1Vv2M4kJG.md','PUBLISHED',2,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-1' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'DAD Triadı: CIA-nın Əks Üzü','30 dəq',0,'[{"body":"# ROOM 2: Data Breach Risks\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 1 — Today''s Security Professional (Fəsil 1)\n**Mənbə:** CompTIA Security+ Study Guide, 9th Ed. — \"Data Breach Risks\" bölməsi\n**Domain uyğunluğu:** 1.0 General Security Concepts (12%)\n**Çətinlik:** Easy\n**Təxmini vaxt:** 30 dəq\n\n## Room haqqında\n\nRoom 1-də CIA Triadını (Confidentiality, Integrity, Availability) öyrəndiniz — bunlar kibertəhlükəsizliyin **məqsədləridir**. İndi sual budur: bu məqsədlər pozulanda (yəni bir təhlükəsizlik insidenti/breach baş verəndə), bunun konkret **təhdid növü** və **biznes təsiri** nədir? Bu room-da kitabın təqdim etdiyi iki tamamlayıcı çərçivəni — DAD Triadı (CIA-nın \"əks üzü\") və Breach Impact kateqoriyalarını (maliyyə, reputasiya, strateji, əməliyyat, uyğunluq) öyrənəcəksiniz.\n\n## Öyrənmə nəticələri\n\n- DAD Triadının (Disclosure, Alteration, Denial) CIA ilə necə güzgü münasibətində olduğunu izah etmək\n- DAD Triadını real ssenaridə risk təhlili aləti kimi tətbiq etmək\n- Breach-in beş təsir kateqoriyasını (Financial, Reputational, Strategic, Operational, Compliance) fərqləndirmək\n- Real bir insidentdə niyə risklərin çox vaxt bir neçə kateqoriyanı eyni anda kəsdiyini izah etmək\n\nKitab CIA Triadına paralel bir model təqdim edir: **DAD Triadı** — Disclosure, Alteration, Denial. Bu, kibertəhlükəsizliyin üç əsas **təhdidini** təsvir edir və hər biri CIA-nın bir elementinin birbaşa pozulmasına uyğun gəlir.\n\n**Disclosure (İfşa)** — həssas məlumatın icazəsiz şəxslərə açılması, yəni məlumat itkisi. Confidentiality-nin pozulmasıdır. Hücumçular məlumatı sistemdən çıxarıb aparanda, buna **data exfiltration** deyilir. İfşa təsadüfən də baş verə bilər — məsələn, admin giriş nəzarətini səhv konfiqurasiya edəndə və ya işçi cihazını itirəndə.\n\n**Alteration (Dəyişdirmə)** — məlumatın icazəsiz modifikasiyası, Integrity-nin pozulmasıdır. Hücumçular maliyyə qazancı üçün qeydləri dəyişə bilər (məsələn, hesaba saxta əməliyyat əlavə etmək). Alteration təbii səbəbdən də (\"bit flip\" — gərginlik dalğasının məlumatı korlaması) və ya təsadüfi insan xətasından da (yazı səhvi) baş verə bilər.\n\n**Denial (İnkar/Rədd)** — qanuni istifadəçinin öz məlumatına icazəli çıxışının pozulması, Availability-nin pozulmasıdır. Bu, qəsdli ola bilər (DDoS hücumu) və ya təsadüfi (kritik server nasazlığı, təbii fəlakət).\n\n| CIA elementi | Uyğun DAD təhdidi | Nümunə |\n|---|---|---|\n| Confidentiality | Disclosure | Verilənlər bazası sızması |\n| Integrity | Alteration | Maliyyə qeydinin saxtalaşdırılması |\n| Availability | Denial | DDoS hücumu |\n\n**DAD-ın praktiki gücü:** kitab DAD Triadını risk qiymətləndirməsində sürətli başlanğıc nöqtəsi kimi tövsiyə edir. Məsələn, bir təşkilatın veb-saytını qiymətləndirərkən özünüzə üç sual verə bilərsiniz: (1) Sayt icazəsiz ifşa halında zərər verəcək həssas məlumat saxlayırmı? (2) Hücumçu saytdakı məlumatı dəyişdirsə, bu maliyyə/reputasiya/əməliyyat zərəri yaradarmı? (3) Sayt biznes üçün kritik funksiya yerinə yetirirmi ki, onun dayandırılması ciddi zərər versin?\n\nBunu bir tibbi analoji ilə görək: CIA — həkimin \"sağlamlıq hədəfləri\"dir (ürək sağlam işləsin, orqanlar zədəsiz olsun, bədən funksional olsun). DAD isə eyni bədənin məruz qala biləcəyi \"xəstəlik növləridir\" (infeksiya = disclosure, zədə = alteration, iflic = denial) — hər xəstəlik konkret bir sağlamlıq hədəfini hədəfə alır.\n\n**Sual 1**\nDAD Triadının üç elementini və hər birinin uyğun gəldiyi CIA elementini yazın.\n\n**Sual 2**\n\"Data exfiltration\" termini DAD-ın hansı elementinə aiddir və nə deməkdir?\n\n**Sual 3**\nDAD Triadını istifadə edərək bir veb-saytı qiymətləndirərkən verilə biləcək üç sualı yazın."}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-data-breach-risks-2m4kjg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Breach Impact: Beş Risk Kateqoriyası','30 dəq',0,'[{"body":"Bir insident baş verəndə, onun təsirini necə ölçmək olar? Kitab bunu biznesin ümumi risk kateqoriyalarına uyğun beş qrupa bölür: Financial, Reputational, Strategic, Operational, Compliance.\n\n**Financial Risk (Maliyyə Riski)** — insidentin təşkilata birbaşa pul zərəri. Bu, **birbaşa** (datacenter-in fiziki bərpası, kriminalistika xidmətinin ödənişi) və ya **dolayı** (bir işçi məhsul planları olan noutbuku itirir — noutbukun özü bir neçə min manat dəyərindədir, amma rəqib firmalar həmin planlara çatıb bazara daha tez çıxsa, gəlir itkisi qat-qat böyük ola bilər) ola bilər.\n\n**Reputational Risk (Reputasiya Riski)** — mənfi ictimai reaksiya nəticəsində müştəri, işçi, təchizatçı etimadının itirilməsi. Kitab vurğulayır ki, bunu ölçmək çətindir — maraqlı tərəflər \"artıq sizinlə iş görməyəcəyik\" demirlər, amma qərarları dolayı yolla dəyişə bilər.\n\n**Identity Theft (Şəxsiyyət Oğurluğu)** — bu, ayrıca kateqoriya deyil, amma kitab xüsusi vurğulayır: breach təşkilatın divarlarından kənara — müştərilərə, işçilərə — yayıla bilər. Sosial sığorta nömrələri, bank/kart məlumatları, sürücülük vəsiqəsi, pasport data kimi PII (Personally Identifiable Information) elementləri xüsusi qorunmalıdır, çünki onlar şəxsiyyət oğurluğu üçün ən çox istifadə olunur.\n\n**Strategic Risk (Strateji Risk)** — təşkilatın əsas məqsədlərinə çatmaq qabiliyyətinin azalması. Yuxarıdakı noutbuk nümunəsinə qayıdaq: əgər planların ehtiyat nüsxəsi yoxdursa, məhsulun bazara çıxması gecikə bilər; əgər rəqib bu planlara çatıbsa, rəqib bazara daha tez çıxıb \"ilk hərəkət edən\" üstünlüyünü ala bilər.\n\n**Operational Risk (Əməliyyat Riski)** — təşkilatın gündəlik funksiyalarını yerinə yetirmə qabiliyyətinə təsir. Strateji riskdən fərqi — kitab bunu təsirin **dərəcəsi** ilə ayırır: əgər risk təşkilatın mövcudluğunu/biznes planını təhdid edirsə, bu strategikdir; yalnız səmərəsizlik/gecikmə yaradırsa, bu əməliyyat riskidir.\n\n**Compliance Risk (Uyğunluq Riski)** — breach təşkilatı hüquqi/tənzimləyici tələblərlə ziddiyyətə salır. Kitab konkret nümunə verir: ABŞ-da HIPAA qanunu səhiyyə təşkilatlarının pasiyent məlumatının (PHI) CIA-sını qorumasını tələb edir; pasiyent qeydləri itirilsə, bu, HIPAA pozuntusudur və Səhiyyə Nazirliyi tərəfindən sanksiya/cərimə ilə nəticələnə bilər.\n\n| Kateqoriya | Əsas sual | Nümunə |\n|---|---|---|\n| Financial | Nə qədər pul itiririk? | Kriminalistika xərcləri, itirilmiş gəlir |\n| Reputational | Etimad necə zədələnir? | Media işıqlandırması, müştəri itkisi |\n| Strategic | Əsas məqsədlərə çatmaq çətinləşirmi? | Rəqib məhsul planlarına çatır |\n| Operational | Gündəlik iş axını pozulurmu? | Manual iş-axınına keçid, gecikmələr |\n| Compliance | Qanun/tənzimləmə pozulurmu? | HIPAA/GDPR sanksiyaları |\n\n**Vacib prinsip — risklər kateqoriyaları kəsir:** Kitab qəti vurğulayır ki, bir riski **yalnız bir** kateqoriyaya sığdırmağa çalışmamalısınız. Real breach-lər adətən bir neçə kateqoriyanı eyni anda kəsir. Məsələn, müştəri PII-sinin sızması: media işıqlandırması reputasiya zərəri yaradır → bu, müştəri itkisi ilə maliyyə zərərinə çevrilir → tənzimləyici cərimə əlavə maliyyə zərəri yaradır (compliance riskindən) → müştərilərə şəxsiyyət qorunma xidməti təklif etmək əlavə birbaşa xərcdir.\n\n**Sual 1**\nBeş Breach Impact kateqoriyasını sadalayın.\n\n**Sual 2**\nStrategic Risk və Operational Risk arasındakı fərqi necə ayırd etmək olar?\n\n**Sual 3**\nNiyə bir riski yalnız bir kateqoriyaya \"sıxışdırmaq\" səhv yanaşmadır? Nümunə ilə izah edin.\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. DAD Triadının üç elementini və CIA ilə uyğunluğunu yazın.\n2. \"Data exfiltration\" nə deməkdir?\n3. Beş Breach Impact kateqoriyasını sadalayın.\n4. PII nədir və niyə xüsusi qorunmalıdır?\n5. Bir müştəri PII sızması hadisəsində ən azı üç fərqli risk kateqoriyasının necə iştirak edə biləcəyini izah edin.\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-data-breach-risks-2m4kjg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
