INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-0','MODULE 0: Giriş — İmtahana Baxış','PUBLISHED',0 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-assessment-test-oz-seviyyeni-yoxla-clmmiv','Assessment Test — Öz Səviyyəni Yoxla','Assessment Test — Öz Səviyyəni Yoxla','CompTIA Security+ · MODULE 0: Giriş — İmtahana Baxış','Kitab (Chapple & Seidl) fəsillərə başlamazdan əvvəl bir "Assessment Test" təqdim edir — məqsəd namizədin hazırkı bilik səviyyəsini müəyyən etməkdir ki, hansı sahələrə daha çox vaxt ayırmaq lazım olduğunu bilsin. Bu room, həmin fəlsəfəni tətbiq edən **orijinal diaqnostik testdir** — 5 domendən 2-3 sual, cəmi 15 sual. Bu, kitabın öz test suallarının təkrarı deyil, eyni məqsədə xidmət edən müstəqil bir yoxlama vasitəsidir.','CompTIA Security+','WALKTHROUGH','BEGINNER'::difficulty,'30 dəq',0,'GREEN',ARRAY['Path-ə başlamazdan əvvəl öz bilik profilinizi 5 domen üzrə xəritələndirmək','Zəif olduğunuz domenləri müəyyən edib, path-də həmin Module-lara əlavə vaxt planlaşdırmaq','Diaqnostik testin nəticəsini konkret Module-larla əlaqələndirməyi öyrənmək']::text[],'drive/1M0FyUAvDcxPasqlzahQaypiMfWcLmMiV.md','PUBLISHED',2,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-0' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Assessment Test — Öz Səviyyəni Yoxla','30 dəq',0,'[{"body":"# ROOM 2: Assessment Test — Öz Səviyyəni Yoxla\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 0 — Giriş\n**Mənbə:** Kitabın \"Assessment Test\" konsepti əsasında (orijinal diaqnostik suallar)\n**Çətinlik:** Easy\n**Təxmini vaxt:** 30 dəq\n\n## Room haqqında\n\nKitab (Chapple & Seidl) fəsillərə başlamazdan əvvəl bir \"Assessment Test\" təqdim edir — məqsəd namizədin hazırkı bilik səviyyəsini müəyyən etməkdir ki, hansı sahələrə daha çox vaxt ayırmaq lazım olduğunu bilsin. Bu room, həmin fəlsəfəni tətbiq edən **orijinal diaqnostik testdir** — 5 domendən 2-3 sual, cəmi 15 sual. Bu, kitabın öz test suallarının təkrarı deyil, eyni məqsədə xidmət edən müstəqil bir yoxlama vasitəsidir.\n\n> **Vacib qeyd:** Bu test sizin path daxilindəki başlanğıc nöqtənizi müəyyən etmək üçündür, real imtahanın simulyasiyası deyil (o, Module 18-dədir). Nəticələrinizi mühakimə vasitəsi kimi yox, \"hara diqqət yetirməliyəm\" göstəricisi kimi istifadə edin.\n\n## Öyrənmə nəticələri\n\n- Path-ə başlamazdan əvvəl öz bilik profilinizi 5 domen üzrə xəritələndirmək\n- Zəif olduğunuz domenləri müəyyən edib, path-də həmin Module-lara əlavə vaxt planlaşdırmaq\n- Diaqnostik testin nəticəsini konkret Module-larla əlaqələndirməyi öyrənmək\n\n## Diaqnostik Test (15 sual, 5 domen üzrə)\n\nHər sual bir domenə aiddir. Cavablarınızı qeyd edin, sonda Cavab Açarı ilə yoxlayın.\n\n### Domain 1.0 — General Security Concepts\n\n**S1.** CIA Triadının üç elementi hansılardır?\n\n**S2.** Bir nəzarət mexanizmi zərəri artıq baş verdikdən sonra aşkar edirsə, bu hansı control tipinə aiddir: Preventive, Detective, yoxsa Corrective?\n\n**S3.** \"Non-repudiation\" termini nəyi bildirir?\n\n### Domain 2.0 — Threats, Vulnerabilities, and Mitigations\n\n**S4.** Maliyyə qazancı üçün deyil, ideoloji səbəblərdən hücum edən threat actor kateqoriyası necə adlanır?\n\n**S5.** Fişinq (phishing) hücumunun telefon üzərindən aparılan versiyası necə adlanır?\n\n**S6.** Ransomware nə edir və ənənəvi virusdan əsas fərqi nədir?\n\n### Domain 3.0 — Security Architecture\n\n**S7.** Zero Trust arxitekturasının əsas prinsipi nədir — \"etibar et, sonra yoxla\", yoxsa \"heç vaxt etibar etmə, həmişə yoxla\"?\n\n**S8.** RAID-in məqsədi nədir (qısaca)?\n\n**S9.** Məlumatın \"at rest\", \"in transit\" və \"in use\" vəziyyətləri arasındakı fərq nədir?\n\n### Domain 4.0 — Security Operations\n\n**S10.** SIEM sistemi əsasən nə üçün istifadə olunur?\n\n**S11.** MFA (Multi-Factor Authentication) neçə \"amil\" kateqoriyasından ibarətdir və bunlar hansılardır?\n\n**S12.** Bir insidentin baş verdiyi andan sonra ilk toplanmalı olan sübutun \"order of volatility\" prinsipinə görə niyə vacib olduğunu izah edin.\n\n### Domain 5.0 — Security Program Management and Oversight\n\n**S13.** Risk Appetite və Risk Tolerance arasındakı fərq nədir?\n\n**S14.** Policy, Standard və Procedure arasındakı iyerarxiya necədir?\n\n**S15.** RTO və RPO nəyi ölçür (hər biri üçün bir cümlə)?\n\n## Öz-özünə Qiymətləndirmə\n\nCavablarınızı Cavab Açarı ilə müqayisə edin və hər domendə neçə sualı düzgün cavabladığınızı qeyd edin:\n\n| Domen | Sual # | Doğru cavab sayı (/3) | Prioritet Module-lar |\n|---|---|---|---|\n| 1.0 General Security Concepts | S1-S3 | ___/3 | Module 1, 7 |\n| 2.0 Threats, Vulnerabilities, Mitigations | S4-S6 | ___/3 | Module 2, 3, 4 |\n| 3.0 Security Architecture | S7-S9 | ___/3 | Module 9, 10, 12 |\n| 4.0 Security Operations | S10-S12 | ___/3 | Module 5, 6, 8, 11, 13, 14, 15 |\n| 5.0 Security Program Management | S13-S15 | ___/3 | Module 16, 17 |\n\n**Nəticənizi necə oxumaq lazımdır:**\n\n- **3/3** — Bu domendə əsas anlayışları bilirsiniz; müvafiq Module-larda kitabın \"Exam Essentials\" xülasələrinə sürətli baxış kifayət edə bilər\n- **1-2/3** — Qismən bilik var, amma boşluqlar var; müvafiq Module-ları normal templə keçin\n- **0/3** — Bu domen sizin üçün yenidir; müvafiq Module-lara adi vaxtdan çox ayırmağı planlaşdırın, heç bir Room-u tələsik keçməyin\n\n**Vacib xatırlatma:** Domain 4.0 (Security Operations) imtahanın 28%-ini təşkil edir və ən çox Module-a (7 module) yayılıb. Əgər bu domendə nəticəniz zəifdirsə, bu, path-in ən böyük hissəsinə təsir edəcək — ona görə xüsusi diqqət tövsiyə olunur.\n\n## Yekun Addım\n\nAşağıdakı cədvəli öz nəticələrinizlə doldurun və path-ə başlamazdan əvvəl bunu \"yol xəritəniz\" kimi saxlayın — Module 18-dəki (Exam Readiness) ikinci practice exam-dan sonra bu ilkin nəticələrlə müqayisə etmək, irəliləyişinizi konkret şəkildə görməyə imkan verəcək.\n\n```\nMƏNİM BAŞLANĞIC PROFİLİM (tarix: _______)\n\nDomain 1.0: ___/3   Domain 2.0: ___/3   Domain 3.0: ___/3\nDomain 4.0: ___/3   Domain 5.0: ___/3\n\nƏn zəif domen: _______________\nBu path-də bu domenə aid Module-larda əlavə vaxt planlaşdırıram: BƏLİ / YOX\n```\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-assessment-test-oz-seviyyeni-yoxla-clmmiv' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
