INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-0','MODULE 0: Giriş — İmtahana Baxış','PUBLISHED',0 FROM paths WHERE slug='comptia-security-plus' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'comptia-security-plus-imtahan-formati-ve-strategiyasi-rdabcw','İmtahan Formatı və Strategiyası','İmtahan Formatı və Strategiyası','CompTIA Security+ · MODULE 0: Giriş — İmtahana Baxış','Hər hazırlıq yolunun ilk addımı — nəyə hazırlaşdığınızı dəqiq bilməkdir. Bu room-da SY0-701 imtahanının formatını, xallandırma sistemini, sual növlərini və kitabın özünün tövsiyə etdiyi öyrənmə strategiyasını öyrənəcəksiniz. Məqsəd, path-in qalan 18 modulunu keçməzdən əvvəl "oyun qaydalarını" tam anlamaqdır — bu, həm narahatlığı azaldır, həm də vaxtınızı düzgün paylaşdırmağa kömək edir.','CompTIA Security+','WALKTHROUGH','BEGINNER'::difficulty,'30 dəq',0,'GREEN',ARRAY['SY0-701 imtahanının formatını (sual sayı, vaxt, xallandırma) dəqiq bilmək','Fərqli sual növlərini (multiple-choice, PBQ, drag-and-drop və s.) tanımaq','"Item seeding" konseptini başa düşmək və qeyri-adi suallara necə reaksiya verməyi bilmək','Kitabın təklif etdiyi "90% qaydası" öyrənmə strategiyasını öz hazırlığınıza tətbiq etmək']::text[],'drive/1embvGvA5Z5j3UD9an58ru8lWhDRdAbcW.md','PUBLISHED',1,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='comptia-security-plus' AND m.slug='module-0' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'İmtahanın Əsas Faktları','30 dəq',0,'[{"body":"# ROOM 1: İmtahan Formatı və Strategiyası\n\n**Path:** CompTIA Security+ (SY0-701) Hazırlığı\n**Module:** 0 — Giriş\n**Mənbə:** CompTIA Security+ Study Guide, 9th Ed. (Chapple & Seidl) — \"Introduction\" bölməsi\n**Çətinlik:** Easy\n**Təxmini vaxt:** 30 dəq\n\n## Room haqqında\n\nHər hazırlıq yolunun ilk addımı — nəyə hazırlaşdığınızı dəqiq bilməkdir. Bu room-da SY0-701 imtahanının formatını, xallandırma sistemini, sual növlərini və kitabın özünün tövsiyə etdiyi öyrənmə strategiyasını öyrənəcəksiniz. Məqsəd, path-in qalan 18 modulunu keçməzdən əvvəl \"oyun qaydalarını\" tam anlamaqdır — bu, həm narahatlığı azaldır, həm də vaxtınızı düzgün paylaşdırmağa kömək edir.\n\n## Öyrənmə nəticələri\n\n- SY0-701 imtahanının formatını (sual sayı, vaxt, xallandırma) dəqiq bilmək\n- Fərqli sual növlərini (multiple-choice, PBQ, drag-and-drop və s.) tanımaq\n- \"Item seeding\" konseptini başa düşmək və qeyri-adi suallara necə reaksiya verməyi bilmək\n- Kitabın təklif etdiyi \"90% qaydası\" öyrənmə strategiyasını öz hazırlığınıza tətbiq etmək\n\nSY0-701 — CompTIA-nın vendor-neutral (istehsalçıdan asılı olmayan) kibertəhlükəsizlik sertifikatıdır. Kitab bunu Systems Administrator, Security Administrator, Tier II IT Support Technician kimi rollara hazırlaşanlar üçün tövsiyə edir.\n\n**Əsas rəqəmlər:**\n\n| Parametr | Dəyər |\n|---|---|\n| Sual sayı | Maksimum 90 |\n| Vaxt | 90 dəqiqə |\n| Xallandırma şkalası | 100-900 |\n| Keçid balı | 750 |\n| Qiymət (ABŞ) | $392 |\n| Format | Şəxsən (Pearson VUE test mərkəzi) və ya evdən (onlayn nəzarətçi ilə) |\n\nDiqqət edin: 90 sual/90 dəqiqə o demək deyil ki, hər suala tam 1 dəqiqə var — bəzi suallar (xüsusilə PBQ-lar) daha çox vaxt tələb edir, sadə multiple-choice suallar isə daha az. Kitab bu balansı özünüz idarə etməyi tövsiyə edir.\n\nCompTIA imtahanın nəyi yoxladığını belə təsvir edir: müəssisə mühitlərinin təhlükəsizlik vəziyyətini qiymətləndirmək, uyğun təhlükəsizlik həllərini tövsiyə etmək və tətbiq etmək, hibrid mühitləri izləmək və qorumaq, tənzimləmə/siyasətlərə uyğun fəaliyyət göstərmək, təhlükəsizlik hadisələrini müəyyən etmək və reaksiya vermək.\n\n**Sual 1**\nİmtahanın maksimum sual sayı, vaxt limiti və keçid balı nədir?\n\n**Sual 2**\nNiyə \"90 sual/90 dəqiqə\" bölgüsünü hər suala tam 1 dəqiqə kimi başa düşmək səhv ola bilər?\n\n**Sual 3**\nCompTIA-nın imtahanla yoxlamaq istədiyi bacarıqlardan üçünü sadalayın."}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-imtahan-formati-ve-strategiyasi-rdabcw' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Sual Növləri və İmtahan Xüsusiyyətləri','30 dəq',0,'[{"body":"SY0-701 CompTIA-nın \"performance-based assessment\" adlandırdığı formatdadır — yəni sadəcə çoxseçimli suallarla məhdudlaşmır. Kitaba görə imtahanda bu sual növləri rast gəlinə bilər:\n\n- **Multiple-choice** — standart çoxseçimli suallar\n- **Fill-in-the-blank** — boşluğu doldurma\n- **Multiple-response** — bir neçə düzgün cavabın seçilməsi tələb olunan suallar\n- **Drag-and-drop** — elementləri düzgün yerə sürükləmə\n- **Image-based (PBQ)** — şəkil/diaqram əsasında qərar vermə tələb olunan performance-based sual\n\nKitab bir neçə vacib xəbərdarlıq edir:\n\n**Qeyri-müəyyən suallar:** CompTIA bəzən elə suallar verir ki, dörd variantdan ikisi məntiqi olaraq düzgün görünə bilər, amma yalnız biri seçilməlidir. Bu zaman məsləhət — biliyinizə, məntiqinizə və intuisiyanıza güvənib ən yaxşı cavabı seçib irəli getməkdir, çünki vaxt məhduddur.\n\n**Item Seeding:** CompTIA bəzən xallandırılmayan (unscored) sualları imtahana qatır — bu, psixometrik məlumat toplamaq və gələcək imtahan versiyalarını hazırlamaq üçündür. İmtahana başlamazdan əvvəl sizə bu barədə xəbərdarlıq ediləcək. Əgər bir sual heç bir tanış mövzuya aid görünmürsə, güman ki, bu, seeded sualdır — amma bunu dəqiq bilmək mümkün olmadığı üçün, hər suala ən yaxşı cəhdinizi göstərməlisiniz.\n\n| Xüsusiyyət | Nə deməkdir | Necə reaksiya vermək |\n|---|---|---|\n| Qeyri-dəqiq dil (typo, qəribə ifadə) | Sual mətnində kiçik xətalar ola bilər | Məyus olmayın, sualı cavablandırıb keçin |\n| İkili düzgün görünən variantlar | 4 variantdan 2-si məntiqli görünə bilər | Ən \"best answer\"ı seçin, çox vaxt sərf etməyin |\n| Seeded (xallandırılmayan) suallar | Tanış olmayan, qəribə mövzulu suallar ola bilər | Yenə də ən yaxşı cəhdinizi göstərin, narahat olmayın |\n\n**Sual 1**\nSY0-701-də rast gələ biləcəyiniz beş sual növünü sadalayın.\n\n**Sual 2**\n\"Item seeding\" nədir və niyə mövcuddur?\n\n**Sual 3**\nBir sualda iki variant da düzgün görünürsə, kitabın tövsiyəsi nədir?"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-imtahan-formati-ve-strategiyasi-rdabcw' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Kitabın Öyrənmə Strategiyası: "90% Qaydası"','30 dəq',0,'[{"body":"Kitab müəllifləri konkret bir öyrənmə metodologiyası təklif edir və bu path da həmin metodologiyaya uyğunlaşdırılıb.\n\n**Kitabın strukturunda hər fəsildə olan elementlər:**\n\n- **Exam Notes** — imtahan obyektivinə birbaşa aid vacib məlumat qeydləri\n- **Summary** — fəslin qısa xülasəsi\n- **Exam Essentials** — əsas imtahan mövzularının və kritik biliyin siyahısı\n- **Review Questions** — fəsil sonunda bilik yoxlama sualları\n\n**Kitabın tövsiyə etdiyi strategiya:**\n\nƏgər siz artıq təhlükəsizlik sahəsində işləyirsinizsə, əvvəlcə fəslin Review Questions-una baxın ki, öz səviyyənizi qiymətləndirəsiniz — sonra kitabı əsasən bilik boşluqlarınızı doldurmaq üçün istifadə edin.\n\n**90% Qaydası:** Əgər bir fəslin sualların 90%-dən çoxuna düzgün cavab verə bilirsinizsə, növbəti fəslə keçmək təhlükəsizdir. Əgər bundan az cavab verə bilirsinizsə, fəsli yenidən oxuyun və sualları təkrar cəhd edin — nəticəniz yaxşılaşmalıdır.\n\nBu path-də bu qayda belə tətbiq olunacaq: hər Module-un (fəslin) sonunda Yekun Yoxlama var — əgər siz bu sualların 90%-ə yaxınına inamla cavab verə bilirsinizsə, növbəti Module-a keçin. Əks halda, müvafiq Room-lara qayıdıb təkrar baxın.\n\nƏlavə vacib qeyd (kitabdan): imtahanda sizə fərqli suallar veriləcək, kitabdakı sualların eynisi deyil — imtahan konsepti/obyektivi yoxlayır, sualın özünü əzbərləməyi yox. Ona görə bu path-də də hədəf **əzbər yox, anlayış** olmalıdır.\n\n**Sual 1**\n\"90% Qaydası\" nə deməkdir və bu path-də necə tətbiq olunur?\n\n**Sual 2**\nKitab artıq təcrübəli olan oxuculara hansı fərqli yanaşmanı tövsiyə edir?\n\n**Sual 3**\nNiyə kitabın sualларını sadəcə əzbərləmək kifayət deyil?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. İmtahanın sual sayı, vaxtı və keçid balını sadalayın.\n2. Beş sual növündən üçünü yazın.\n3. \"Item seeding\" konseptini izah edin.\n4. \"90% Qaydası\" nədir?\n5. Niyə imtahanda qeyri-dəqiq/qəribə görünən suallara sakit reaksiya vermək tövsiyə olunur?\n\n---"}]'::jsonb FROM rooms WHERE slug='comptia-security-plus-imtahan-formati-ve-strategiyasi-rdabcw' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
