INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-8','MODULE 8: Bonus','PUBLISHED',8 FROM paths WHERE slug='grc' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'grc-grc-aletleri-landsafti-fd6hbq','GRC Alətləri Landşaftı','GRC Alətləri Landşaftı','GRC PATH · MODULE 8: Bonus','Kursun əvvəlindən bəri öyrəndiyimiz hər şeyi — Policy sənədləri (Module 2), BIA/RTO/RPO (Module 4), Audit prosesi və Control Testing (Module 6) — real təşkilatlar çox vaxt Excel cədvəllərində deyil, **xüsusi GRC proqram təminatlarında** idarə edir. Bu room-da bazarda mövcud olan əsas GRC alətləri kateqoriyalarını, onların fərqlərini və bir təşkilat üçün düzgün alət seçmə meyarlarını öyrənəcəksiniz.','GRC PATH','WALKTHROUGH','BEGINNER'::difficulty,'30 dəq (yeni)',0,'GREEN',ARRAY['GRC alətlərinin əsas kateqoriyalarını fərqləndirə bilmək','Enterprise (Archer, ServiceNow) və agile/yüngül alətlər (LogicGate, Vanta, Drata) arasındakı fərqi izah edə bilmək','Açıq-mənbə (open-source) GRC alternativlərinin nə vaxt məntiqli olduğunu başa düşmək','Alət seçimi üçün əsas meyarları real ssenariyə tətbiq edə bilmək']::text[],'drive/11jTImujtMCslY0SwmDqOEouRRffD6hBQ.md','PUBLISHED',4,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='grc' AND m.slug='module-8' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'GRC Alətlərinin Əsas Kateqoriyaları','30 dəq (yeni)',0,'[{"body":"# ROOM 4: GRC Alətləri Landşaftı\n\n**Path:** GRC Fundamentals\n**Module:** Bonus / İrəliləyiş Mövzular\n**Çətinlik:** Elective\n**Təxmini vaxt:** 30 dəq (yeni)\n\n## Room haqqında\n\nKursun əvvəlindən bəri öyrəndiyimiz hər şeyi — Policy sənədləri (Module 2), BIA/RTO/RPO (Module 4), Audit prosesi və Control Testing (Module 6) — real təşkilatlar çox vaxt Excel cədvəllərində deyil, **xüsusi GRC proqram təminatlarında** idarə edir. Bu room-da bazarda mövcud olan əsas GRC alətləri kateqoriyalarını, onların fərqlərini və bir təşkilat üçün düzgün alət seçmə meyarlarını öyrənəcəksiniz.\n\n**Diqqət:** Bu, məhsul landşaftıdır və sürətlə dəyişir — konkret alətlərin funksionallığı, qiyməti dəyişə bilər. Məqsəd konkret bir alətin təbliğatı deyil, **kateqoriyaları və seçim məntiqini** anlamaqdır.\n\n## Öyrənmə nəticələri\n\n- GRC alətlərinin əsas kateqoriyalarını fərqləndirə bilmək\n- Enterprise (Archer, ServiceNow) və agile/yüngül alətlər (LogicGate, Vanta, Drata) arasındakı fərqi izah edə bilmək\n- Açıq-mənbə (open-source) GRC alternativlərinin nə vaxt məntiqli olduğunu başa düşmək\n- Alət seçimi üçün əsas meyarları real ssenariyə tətbiq edə bilmək\n\nGRC bazarını dörd əsas kateqoriyaya bölmək olar:\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│ 1. ENTERPRISE / LEGACY GRC PLATFORMALARI                        │\n│    Nümunə: RSA Archer, ServiceNow GRC/IRM, IBM OpenPages,      │\n│    MetricStream                                                  │\n│    Xüsusiyyət: Çox geniş funksionallıq, dərin konfiqurasiya,   │\n│    böyük təşkilatlar üçün, tətbiqi uzun və bahalı (aylar,      │\n│    ixtisaslaşmış heyət tələb edir)                               │\n├─────────────────────────────────────────────────────────────┤\n│ 2. AGILE / KONFİQURASİYA-YÖNÜMLÜ GRC PLATFORMALARI              │\n│    Nümunə: LogicGate, Riskonnect, Onspring                      │\n│    Xüsusiyyət: Enterprise platformalara nisbətən daha sürətli   │\n│    tətbiq, \"no-code\" iş axını qurma, orta ölçülü/böyüyən        │\n│    təşkilatlar üçün uyğun                                        │\n├─────────────────────────────────────────────────────────────┤\n│ 3. COMPLIANCE AUTOMATION PLATFORMALARI                            │\n│    Nümunə: Vanta, Drata, Secureframe                            │\n│    Xüsusiyyət: Əsasən SOC 2/ISO 27001 kimi konkret sertifikat  │\n│    məqsədilə, bulud sistemləri ilə avtomatik inteqrasiya        │\n│    (Module 8, Room 3-dəki CCM prinsipinə bənzər), start-up/     │\n│    orta ölçülü şirkətlər üçün sürətli qurulum                    │\n├─────────────────────────────────────────────────────────────┤\n│ 4. AÇIQ-MƏNBƏ (OPEN-SOURCE) ALTERNATİVLƏR                        │\n│    Nümunə: Eramba, CISO Assistant                                │\n│    Xüsusiyyət: Pulsuz/aşağı xərcli, öz infrastrukturunda         │\n│    (self-hosted) işlədilə bilər, texniki heyət tələb edir,      │\n│    kiçik büdcəli və ya məlumat suverenliyi vacib olan            │\n│    təşkilatlar üçün                                                │\n└─────────────────────────────────────────────────────────────┘\n```\n\n**Vacib məntiq:** \"Ən yaxşı\" alət deyə bir şey yoxdur — yalnız **konkret təşkilat üçün ən uyğun** alət var. Bir kateqoriyanın gücü digərinin zəifliyi ola bilər: Enterprise platformalar çox güclüdür, amma kiçik komanda üçün \"artıq ağırlıq\"dır; Compliance Automation alətləri sürətlidir, amma dərin, çoxfunksiyalı risk idarəetməsi tələb edən böyük bank üçün kifayət etməyə bilər.\n\n**Sual 1**\nDörd GRC alət kateqoriyasını sadalayın və hər birindən bir nümunə verin.\n\n**Sual 2**\nEnterprise platformaların əsas güclü və zəif tərəfi nədir?\n\n**Sual 3**\nAçıq-mənbə alətlər hansı tip təşkilat üçün xüsusilə məntiqli ola bilər?"}]'::jsonb FROM rooms WHERE slug='grc-grc-aletleri-landsafti-fd6hbq' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Alət Seçimi Meyarları','30 dəq (yeni)',0,'[{"body":"Bir GRC aləti seçərkən nəzərə alınmalı əsas meyarlar bunlardır:\n\n**1. Təşkilatın ölçüsü və yetkinliyi** — Kiçik, hələ formalaşan GRC proqramı üçün ağır enterprise platforma mənasızdır (istifadə olunmayan funksionallıq üçün pul xərcləmək); əksinə, böyük, mürəkkəb risk mühitinə malik bank üçün yüngül compliance automation aləti kifayət etməyə bilər.\n\n**2. Əsas məqsəd** — Əgər əsas hədəf konkret sertifikat (SOC 2, ISO 27001) əldə etməkdirsə, Compliance Automation platforması sürətli yol ola bilər. Əgər hədəf geniş, çoxfunksiyalı risk idarəetməsi (əməliyyat riski, üçüncü tərəf riski, audit idarəetməsi birlikdə) qurmaqdırsa, Enterprise/Agile platforma daha uyğundur.\n\n**3. Mövcud texnologiya stack-i ilə inteqrasiya** — Module 8, Room 3-dəki (CCM) kimi, alət mövcud sistemlərlə (bulud provayderləri, identity provayderləri, ticketing sistemləri) nə qədər asan inteqrasiya oluna bilir? Artıq bir ITSM platforması (məsələn ServiceNow) istifadə edən təşkilat üçün eyni ekosistemdə GRC modulunu əlavə etmək inteqrasiya baxımından üstünlük verə bilər.\n\n**4. Büdcə və implementasiya vaxtı** — Enterprise platformalar adətən yüksək lisenziya xərci və uzun (aylarla) implementasiya tələb edir, ixtisaslaşmış konsultant lazım ola bilər; agile və compliance automation alətləri adətən daha sürətli (həftələr) işə düşür.\n\n**5. Məlumat suverenliyi/nəzarət tələbləri** — Bəzi sənayelər (dövlət, maliyyə) və ya ölkələr məlumatın öz infrastrukturunda saxlanmasını tələb edə bilər — bu hallarda açıq-mənbə, self-hosted alətlər üstünlük qazanır.\n\n**Qərar ağacı (sadələşdirilmiş):**\n\n```\nSual 1: Əsas məqsəd konkret sertifikatdırmı (SOC 2/ISO 27001)?\n  → BƏLİ: Compliance Automation platformasına bax\n  → XEYR: Sual 2-yə keç\n\nSual 2: Təşkilat böyükdür, çoxfunksiyalı risk idarəetməsi lazımdır?\n  → BƏLİ, böyük büdcə var: Enterprise platformaya bax\n  → BƏLİ, amma büdcə/vaxt məhduddur: Agile platformaya bax\n  → XEYR (kiçik/orta, sadə ehtiyac): Sual 3-ə keç\n\nSual 3: Məlumat suverenliyi/büdcə kritik məhdudiyyətdirmi?\n  → BƏLİ: Açıq-mənbə alternativə bax\n  → XEYR: Agile və ya Compliance Automation arasında seç\n```\n\n**Sual 1**\nBeş əsas seçim meyarını sadalayın.\n\n**Sual 2**\nNiyə \"ən güclü/ən bahalı alət həmişə ən yaxşı seçimdir\" fikri səhvdir?\n\n**Sual 3**\nMövcud texnologiya stack-i ilə inteqrasiya niyə vacib bir meyardır?"}]'::jsonb FROM rooms WHERE slug='grc-grc-aletleri-landsafti-fd6hbq' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Praktiki Tapşırıq: TechNova üçün Alət Tövsiyəsi','30 dəq (yeni)',0,'[{"body":"TechNova MMC-nin CISO-su (Module 2, Room 2-dəki governance strukturunu xatırlayın) sizdən GRC aləti seçimi üçün ilkin tövsiyə hazırlamağınızı xahiş edib.\n\n**TechNova-nın vəziyyəti:**\n\n```\n- 250 işçi, orta ölçülü fintech şirkət\n- Hazırda əsasən Excel cədvəllərində risk register və audit \n  tapıntılarını izləyir — bu, artıq idarəolunmaz hala gəlib\n- Yaxın hədəf: 6 ay ərzində SOC 2 Type II sertifikatını əldə \n  etmək (əsas müştəri tələbidir)\n- Orta müddətli hədəf (1-2 il): daxili audit (Module 6), risk \n  idarəetməsi (Module 3) və üçüncü tərəf təhlükəsizlik \n  qiymətləndirmələrini vahid platformada birləşdirmək\n- Büdcə məhduddur — böyük ilkin investisiya (məsələn, \n  altı-rəqəmli enterprise lisenziya) hazırda mümkün deyil\n- Maliyyə sektorunda fəaliyyət göstərdiyi üçün məlumatların \n  harada saxlanacağına həssasdır, amma hələlik özəl \n  infrastruktur tələbi yoxdur\n```\n\n**Sizin tapşırığınız:**\n\n**Addım 1** — Task 2-dəki qərar ağacını TechNova-nın vəziyyətinə tətbiq edin\n\n**Addım 2** — Qısamüddətli (0-6 ay) və orta müddətli (1-2 il) üçün ayrı-ayrı tövsiyə verin — bunlar eyni alət ola, ya da olmaya bilər\n\n**Addım 3** — Tövsiyənizi əsaslandırın (hansı meyarlar bu qərara gətirdi?)\n\n**Kömək üçün nümunə həll strukturu:**\n\n```\nQISAMÜDDƏTLİ TÖVSİYƏ (0-6 ay): Compliance Automation Platforması\n\nƏsaslandırma:\nQərar ağacının 1-ci sualına cavab \"BƏLİ\"dir — əsas hədəf konkret \nsertifikatdır (SOC 2 Type II). Compliance Automation platformaları \nməhz bu ssenari üçün optimallaşdırılıb: bulud sistemləri ilə \navtomatik inteqrasiya vasitəsilə sübut (evidence) toplanmasını \nsürətləndirir (Module 8, Room 3-dəki CCM prinsipinə bənzər), \nimplementasiya həftələrlə (aylarla deyil) başa çatır və büdcə \nenterprise platformalardan aşağıdır. Bu, TechNova-nın 6 aylıq \nhədəfinə və məhdud büdcəsinə uyğun gəlir.\n\nORTA MÜDDƏTLİ TÖVSİYƏ (1-2 il): Agile GRC Platformasına Keçidi \nNəzərdən Keçirin\n\nƏsaslandırma:\nOrta müddətdə TechNova-nın hədəfi genişlənir — təkcə sertifikat \nyox, daxili audit, risk idarəetməsi və üçüncü tərəf \nqiymətləndirmələrini əhatə edən vahid platforma. Bu, Compliance \nAutomation alətlərinin əsas güclü tərəfindən (dar, sertifikat-\nyönümlü fokus) kənara çıxır. Agile platforma (Enterprise yox, \nçünki büdcə və komanda ölçüsü hələ tam enterprise səviyyəsinə \nuyğun olmaya bilər) daha geniş funksionallıq təklif edərkən, \nimplementasiya sürəti və xərci enterprise platformalardan aşağı \nqalır.\n\nQEYD: Açıq-mənbə alternativ bu mərhələdə tövsiyə edilmir, çünki \nTechNova-nın hazırda özəl infrastruktur/self-hosted tələbi yoxdur \nvə məhdud texniki heyət resursu bu cür alətin idarə olunmasını \nçətinləşdirə bilər.\n```\n\n**Öz-özünə keyfiyyət yoxlaması (Checklist):**\n\n```\n☐ Qərar ağacı addım-addım TechNova-nın konkret məlumatlarına \n  tətbiq edilib\n☐ Qısamüddətli və orta müddətli tövsiyələr aydın ayrılıb\n☐ Hər tövsiyə üçün ən azı 2 konkret meyara (büdcə, vaxt, \n  funksionallıq həcmi və s.) istinad edilib\n☐ Açıq-mənbə seçiminin niyə (hazırda) uyğun olmadığı izah \n  edilib\n```\n\n**Sual 1**\nNiyə TechNova üçün ilkin mərhələdə Enterprise platforma (Archer, ServiceNow GRC) tövsiyə edilmir?\n\n**Sual 2**\nOrta müddətli tövsiyədə niyə yenidən Enterprise deyil, Agile platforma seçildi?\n\n**Sual 3**\nƏgər TechNova gələcəkdə 1000+ işçiyə böyüsə və Avropa bankları ilə tənzimləyici səviyyəli əməkdaşlığa girsə, bu, alət seçimi tövsiyəsini necə dəyişdirərdi?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Dörd GRC alət kateqoriyasını sadalayın.\n2. Alət seçimində əsas beş meyarı sadalayın.\n3. Compliance Automation platformaları hansı ssenaridə xüsusilə güclüdür?\n4. Açıq-mənbə GRC alətləri hansı şəraitdə tövsiyə olunur?\n5. TechNova ssenarisində qısamüddətli və orta müddətli tövsiyələr niyə fərqli idi?\n\n---"}]'::jsonb FROM rooms WHERE slug='grc-grc-aletleri-landsafti-fd6hbq' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO paths(slug,title,description,category,status,order_index) VALUES ('grc','GRC PATH','GRC PATH kurikulumu','GRC PATH' ,'PUBLISHED',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-8','MODULE 8: Bonus','PUBLISHED',8 FROM paths WHERE slug='grc' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'grc-continuous-controls-monitoring-ccm-csjxlg','Continuous Controls Monitoring (CCM)','Continuous Controls Monitoring (CCM)','GRC PATH · MODULE 8: Bonus','Module 6-da audit prosesini öyrənəndə diqqət etdiniz ki, Room 2-dəki (Module 6) nümunə test yalnız **10 hadisəlik nümunə (sample)** üzərində, **il bir dəfə** aparılırdı. Bu, ənənəvi audit-in təbiətidir — "point-in-time" (müəyyən vaxt nöqtəsində) bir görüntü çəkir. Amma bir sual yaranır: əgər problem may ayında yaranıb, oktyabrda düzəlibsə, illik audit (dekabrda aparılan) bunu heç görməyə bilər. Bu boşluğu aradan qaldıran yanaşma **Continuous Controls Monitoring (CCM)**-dir.','GRC PATH','WALKTHROUGH','BEGINNER'::difficulty,'30 dəq',0,'GREEN',ARRAY['CCM-in ənənəvi (point-in-time) audit-dən fərqini izah edə bilmək','CCM-in necə işlədiyini (məlumat mənbələri, exception-based yanaşma) təsvir edə bilmək','Hansı nəzarətlərin CCM-ə uyğun, hansılarının uyğun olmadığını müəyyən edə bilmək','Real ssenaridə CCM tətbiqi üçün namizəd nəzarətləri seçə bilmək']::text[],'drive/1Mhrfnj6R7jqv4N3OU9NFE5VNktcsJXLg.md','PUBLISHED',3,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='grc' AND m.slug='module-8' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Point-in-Time Audit vs Continuous Monitoring','30 dəq',0,'[{"body":"# ROOM 3: Continuous Controls Monitoring (CCM)\n\n**Path:** GRC Fundamentals\n**Module:** Bonus / İrəliləyiş Mövzular\n**Çətinlik:** Elective\n**Təxmini vaxt:** 30 dəq\n\n## Room haqqında\n\nModule 6-da audit prosesini öyrənəndə diqqət etdiniz ki, Room 2-dəki (Module 6) nümunə test yalnız **10 hadisəlik nümunə (sample)** üzərində, **il bir dəfə** aparılırdı. Bu, ənənəvi audit-in təbiətidir — \"point-in-time\" (müəyyən vaxt nöqtəsində) bir görüntü çəkir. Amma bir sual yaranır: əgər problem may ayında yaranıb, oktyabrda düzəlibsə, illik audit (dekabrda aparılan) bunu heç görməyə bilər. Bu boşluğu aradan qaldıran yanaşma **Continuous Controls Monitoring (CCM)**-dir.\n\nBu room-da CCM-in nə olduğunu, ənənəvi audit-dən necə fərqləndiyini və TechNova-nın hansı nəzarətləri CCM-ə uyğun namizəd olduğunu öyrənəcəksiniz.\n\n## Öyrənmə nəticələri\n\n- CCM-in ənənəvi (point-in-time) audit-dən fərqini izah edə bilmək\n- CCM-in necə işlədiyini (məlumat mənbələri, exception-based yanaşma) təsvir edə bilmək\n- Hansı nəzarətlərin CCM-ə uyğun, hansılarının uyğun olmadığını müəyyən edə bilmək\n- Real ssenaridə CCM tətbiqi üçün namizəd nəzarətləri seçə bilmək\n\nƏnənəvi audit modelini bir metafora ilə düşünək: bu, ilin müəyyən günündə çəkilən bir **fotoşəkil**dir — o an üçün doğrudur, amma şəkil çəkiləndən sonra baş verənləri göstərmir. CCM isə **canlı video** kimidir — davamlı olaraq izləyir və dəyişiklikləri real-vaxta yaxın aşkar edir.\n\n```\nƏNƏNƏVİ AUDIT (Point-in-Time)          CCM (Continuous)\n──────────────────────────             ──────────────────\nTezlik: İllik/rüblük                   Tezlik: Davamlı (gündəlik/\n                                         real-vaxta yaxın)\n\nMetod: Manual sample testi             Metod: Avtomatlaşdırılmış,\n(Module 6, Room 2-dəki                  bütün populyasiyanı \n10 hadisəlik nümunə kimi)               əhatə edən yoxlama\n\nAşkarlama: Problem baş verəndən        Aşkarlama: Problem baş \naylar sonra tapıla bilər                verdikdən qısa müddət \n                                         sonra bildiriş gəlir\n\nƏhatə: Nümunə (məs. 10/hamısı)         Əhatə: 100% (bütün \n                                         tranzaksiyalar/hadisələr)\n\nResurs: Auditor-un vaxtı ilə           Resurs: İlkin qurulum \nməhdud                                  bahalı, sonra aşağı \n                                         əməliyyat xərci\n```\n\n**Vacib məntiq:** CCM audit-i **əvəz etmir**, ona **əlavə edir**. Audit hələ də strateji baxış, risk qiymətləndirməsi və müstəqil təsdiqləmə (assurance) verir; CCM isə gündəlik \"gözətçi\" rolunu oynayır. Yaxşı GRC proqramında hər ikisi birlikdə işləyir: CCM problemi tez tapır, audit isə bu problemin kök səbəbini, sistemin ümumi effektivliyini daha dərindən araşdırır.\n\n**Sual 1**\nPoint-in-time audit ilə CCM arasındakı fərqi \"fotoşəkil vs canlı video\" metaforası ilə izah edin.\n\n**Sual 2**\nCCM audit-i tamamilə əvəz edirmi? Niyə?\n\n**Sual 3**\nCCM-in ilkin qurulumu niyə \"bahalı\", sonrakı istifadəsi isə niyə \"aşağı xərcli\" hesab olunur?"}]'::jsonb FROM rooms WHERE slug='grc-continuous-controls-monitoring-ccm-csjxlg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'CCM Necə İşləyir?','30 dəq',0,'[{"body":"CCM-in işləmə məntiqi üç addımdan ibarətdir:\n\n```\n1. MƏLUMAT MƏNBƏYİNƏ QOŞULMA\n   Sistem (məs. Active Directory, maliyyə sistemi, log \n   platforması) ilə avtomatik inteqrasiya qurulur\n\n2. QAYDA/HƏDD MÜƏYYƏNLƏŞDİRMƏ\n   \"Normal\" vəziyyət təyin edilir (məs. \"hesab bağlanması \n   4 saat ərzində olmalıdır\") — bu, Room 1-dəki (Module 6) \n   Criteria konseptinin avtomatlaşdırılmış formasıdır\n\n3. EXCEPTION-BASED BİLDİRİŞ\n   Sistem yalnız QAYDANI POZAN hallar (exceptions) barədə \n   bildiriş göndərir — auditor min hadisəni əl ilə yoxlamır, \n   yalnız sistemin işarələdiyi anomaliyalara baxır\n```\n\n**\"Exception-based\" yanaşmanın gücü:** Ənənəvi auditda auditor 1000 hadisədən 10-nu (1%) təsadüfi seçib yoxlayır. CCM-də isə sistem bütün 1000 hadisəni avtomatik yoxlayır, amma auditor-un diqqətinə yalnız **qaydanı pozan** hadisələri (məsələn, 12-sini) çıxarır. Bu, həm əhatəni 1%-dən 100%-ə çıxarır, həm də auditor-un vaxtını daha səmərəli istifadə edir — çünki insan diqqəti yalnız real problemlərə yönəlir.\n\n**CCM-ə uyğun (yaxşı namizəd) nəzarətlərin xüsusiyyətləri:**\n\n```\n✓ Yüksək tezlikli, təkrarlanan proses (məs. gündəlik yüzlərlə \n  tranzaksiya)\n✓ Rəqəmsal sistemdə baş verir (log/məlumat mövcuddur)\n✓ Aydın, ölçülə bilən qayda var (məs. \"4 saat ərzində\", \n  \"iki səviyyəli təsdiq\")\n✓ Yüksək risk daşıyır (uyğunsuzluğun tez aşkarlanması vacibdir)\n```\n\n**CCM-ə uyğun OLMAYAN nəzarətlərin xüsusiyyətləri:**\n\n```\n✗ Subyektiv qiymətləndirmə tələb edir (məs. \"işçinin davranışı \n  peşəkardırmı?\")\n✗ Nadir hallarda baş verir (məs. ildə 1-2 dəfə olan strateji \n  qərar)\n✗ Rəqəmsal iz buraxmır (məs. şifahi razılaşma, fiziki müşahidə)\n✗ Aydın ədədi hədd yoxdur (məs. \"təhlükəsizlik mədəniyyəti \n  güclüdürmü?\")\n```\n\n**Sual 1**\nCCM-in üç addımlı işləmə məntiqini sadalayın.\n\n**Sual 2**\n\"Exception-based\" yanaşma niyə auditor-un vaxtını daha səmərəli istifadə etməyə kömək edir?\n\n**Sual 3**\nCCM-ə uyğun olmayan bir nəzarət nümunəsi verin və niyə uyğun olmadığını izah edin."}]'::jsonb FROM rooms WHERE slug='grc-continuous-controls-monitoring-ccm-csjxlg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Praktiki Tapşırıq: TechNova üçün CCM Namizədlərini Seçin','30 dəq',0,'[{"body":"TechNova MMC-nin daxili audit komandası CCM proqramını işə salmaq istəyir, amma büdcə məhdud olduğu üçün əvvəlcə yalnız 2 nəzarəti CCM-ə keçirə bilər. Aşağıda 5 namizəd nəzarət verilib.\n\n```\nNamizəd A: İstifadəçi Giriş İdarəetməsi\n(Module 6-dan tanış — HR bildirişindən sonra 4 saat ərzində \nhesab bağlanması)\n- Aylıq ~15-20 işdən çıxma hadisəsi\n- Active Directory log-larında tam iz var\n\nNamizəd B: Board İclaslarının Keyfiyyəti\n- İldə 4 dəfə Board iclası keçirilir\n- Qiymətləndirmə meyarı: \"müzakirələr strateji səviyyədə \n  keyfiyyətlidirmi?\"\n\nNamizəd C: Kritik Patch-lərin Vaxtında Quraşdırılması\n(Module 6, Room 3-dəki patch management nümunəsindən tanış)\n- Gündə onlarla server, patch sistemi loglar saxlayır\n- Aydın qayda: 14 gün ərzində quraşdırılmalı\n\nNamizəd D: Podratçılarla Müqavilə Danışıqları Prosesi\n- İldə 3-4 yeni podratçı müqaviləsi\n- Hər müqavilə fərqli, hüquqi komanda tərəfindən fərdi \n  qiymətləndirilir\n\nNamizəd E: Maliyyə Tranzaksiyalarında İki Səviyyəli Təsdiq\n- Gündə yüzlərlə ödəniş tranzaksiyası\n- Aydın qayda: $10,000-dan yuxarı hər tranzaksiya 2 fərqli \n  şəxs tərəfindən təsdiqlənməlidir, sistemdə iz saxlanılır\n```\n\n**Sizin tapşırığınız:**\n\n**Addım 1** — Hər namizədi Task 2-dəki dörd meyara (tezlik, rəqəmsal iz, aydın qayda, risk səviyyəsi) görə qiymətləndirin\n\n**Addım 2** — Ən uyğun 2 namizədi seçin\n\n**Addım 3** — Seçilməyən namizədlər üçün alternativ yanaşma təklif edin (məsələn, ənənəvi illik audit davam etməlidir)\n\n**Kömək üçün nümunə həll (Namizəd B üzrə):**\n\n```\nNAMİZƏD B: Board İclaslarının Keyfiyyəti\n\nQiymətləndirmə:\n✗ Tezlik: Aşağı (ildə cəmi 4 dəfə) — CCM-in gücü yüksək \n  tezlikli proseslərdə göstərilir, burada əlavə dəyər azdır\n✗ Rəqəmsal iz: Məhdud — iclas protokolları var, amma \n  \"keyfiyyət\" özü rəqəmsal ölçülə bilməz\n✗ Aydın qayda: Yoxdur — \"strateji səviyyədə keyfiyyətli \n  müzakirə\" subyektiv qiymətləndirmədir, ədədi hədd təyin \n  etmək mümkün deyil\n△ Risk səviyyəsi: Yüksək (strateji qərarların keyfiyyəti \n  vacibdir), amma bu, CCM-in həll edə biləcəyi risk növü \n  deyil\n\nNƏTİCƏ: CCM-ə UYĞUN DEYİL. Bu, ənənəvi keyfiyyətli \nqiymətləndirmə (məsələn, Board effektivliyi sorğusu, xarici \ngovernance konsultantının rəyi) tələb edən sahədir — \navtomatlaşdırıla bilməz.\n```\n\n**Öz-özünə keyfiyyət yoxlaması (Checklist):**\n\n```\n☐ Hər 5 namizəd 4 meyara görə ayrı-ayrı qiymətləndirilib\n☐ Seçilən 2 namizəd üçün bütün/əksər meyarlar müsbətdir\n☐ Seçilməyən namizədlər üçün konkret səbəb göstərilib (hansı \n  meyar uyğun gəlmir)\n☐ Seçilməyənlər üçün real alternativ təklif edilib (sadəcə \n  \"audit edilməsin\" deyil)\n```\n\n**Sual 1**\nNamizəd A və E niyə ən güclü CCM namizədləridir? Ortaq xüsusiyyətlərini müqayisə edin.\n\n**Sual 2**\nNamizəd D (podratçı müqavilələri) niyə CCM-ə uyğun deyil, amma yenə də vacib bir nəzarətdir?\n\n**Sual 3**\nƏgər TechNova gələcəkdə büdcəni artırıb 3-cü namizədi əlavə etmək istəsə, Namizəd C ilə hansı digər namizəd arasında seçim etməli və niyə?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Point-in-time audit ilə CCM arasındakı əsas fərqi izah edin.\n2. CCM-in üç addımlı işləmə məntiqini sadalayın.\n3. \"Exception-based\" yanaşma nə deməkdir?\n4. CCM-ə uyğun nəzarətin dörd xüsusiyyətini sadalayın.\n5. TechNova ssenarisində hansı iki namizəd seçildi və niyə?\n\n---"}]'::jsonb FROM rooms WHERE slug='grc-continuous-controls-monitoring-ccm-csjxlg' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
