INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-8','MODULE 8: Bonus','PUBLISHED',8 FROM paths WHERE slug='grc' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'grc-esg-reporting-e-giris-rzmxeh','ESG Reporting-ə Giriş','ESG Reporting-ə Giriş','GRC PATH · MODULE 8: Bonus','GRC-nin "G" (Governance) və "C" (Compliance) hərflərini artıq dərindən öyrəndik. Bu room-da GRC dünyasında getdikcə daha çox yer tutan bir mövzuya toxunacağıq: **ESG (Environmental, Social, Governance)** — yəni ekoloji, sosial və idarəetmə göstəricilərinin hesabatlılığı. ESG artıq könüllü bir "yaxşı niyyət" fəaliyyəti deyil — Avropa İttifaqında **CSRD** (Corporate Sustainability Reporting Directive) adlı qanunvericiliklə məcburi hesabatlılıq halına gəlib.','GRC PATH','WALKTHROUGH','BEGINNER'::difficulty,'25 dəq',0,'GREEN',ARRAY['ESG-nin üç komponentini və GRC ilə əlaqəsini izah edə bilmək','"Double Materiality" (İkiqat Əhəmiyyətlilik) konseptini başa düşmək','CSRD-nin əsas tələblərini və 2026-cı il Omnibus dəyişikliklərinin təsirini izah edə bilmək','Real bir şirkətin CSRD əhatə dairəsinə düşüb-düşmədiyini qiymətləndirə bilmək']::text[],'drive/1AvcJhC9JJOOoZBxLcJUKnRoFZ9rZMXeh.md','PUBLISHED',2,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='grc' AND m.slug='module-8' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'ESG Nədir və GRC ilə Necə Əlaqəlidir?','25 dəq',0,'[{"body":"# ROOM 2: ESG Reporting-ə Giriş\n\n**Path:** GRC Fundamentals\n**Module:** Bonus / İrəliləyiş Mövzular\n**Çətinlik:** Elective\n**Təxmini vaxt:** 25 dəq\n\n## Room haqqında\n\nGRC-nin \"G\" (Governance) və \"C\" (Compliance) hərflərini artıq dərindən öyrəndik. Bu room-da GRC dünyasında getdikcə daha çox yer tutan bir mövzuya toxunacağıq: **ESG (Environmental, Social, Governance)** — yəni ekoloji, sosial və idarəetmə göstəricilərinin hesabatlılığı. ESG artıq könüllü bir \"yaxşı niyyət\" fəaliyyəti deyil — Avropa İttifaqında **CSRD** (Corporate Sustainability Reporting Directive) adlı qanunvericiliklə məcburi hesabatlılıq halına gəlib.\n\nBu room qısa bir giriş xarakteri daşıyır — məqsəd ESG-nin əsas məntiqini və TechNova kimi şirkətlərin bu tələblərə necə yanaşmalı olduğunu anlamaqdır.\n\n**Diqqət:** Bu sahə də sürətlə dəyişir — 2025-2026-cı illərdə \"Omnibus\" adlanan islahat paketi CSRD-nin əhatə dairəsini əhəmiyyətli dərəcədə daraltdı. Aşağıdakı məlumat 2026-cı ilin ortasındakı vəziyyəti əks etdirir.\n\n## Öyrənmə nəticələri\n\n- ESG-nin üç komponentini və GRC ilə əlaqəsini izah edə bilmək\n- \"Double Materiality\" (İkiqat Əhəmiyyətlilik) konseptini başa düşmək\n- CSRD-nin əsas tələblərini və 2026-cı il Omnibus dəyişikliklərinin təsirini izah edə bilmək\n- Real bir şirkətin CSRD əhatə dairəsinə düşüb-düşmədiyini qiymətləndirə bilmək\n\n**ESG** üç sahəni əhatə edir:\n\n```\nE — ENVIRONMENTAL (Ekoloji)\n    Karbon izi, enerji istifadəsi, tullantı idarəetməsi, \n    iqlim dəyişikliyinə uyğunlaşma\n\nS — SOCIAL (Sosial)\n    İşçi hüquqları, iş yerində müxtəliflik, tədarük zəncirində \n    insan hüquqları, cəmiyyətə təsir\n\nG — GOVERNANCE (İdarəetmə)\n    Board strukturu, əmək haqqı şəffaflığı, korrupsiyaya qarşı \n    tədbirlər, etika — bax, Module 2-də öyrəndiyimiz Governance \n    prinsipləri birbaşa buraya bağlıdır!\n```\n\n**ESG Reporting** — bir şirkətin bu üç sahədəki fəaliyyətini strukturlaşdırılmış, ölçülə bilən formada, xarici auditə açıq şəkildə açıqlamasıdır. Bu, Module 6-da öyrəndiyimiz Audit prinsipləri ilə birbaşa əlaqəlidir: ESG hesabatları da, maliyyə hesabatları kimi, **assurance** (yəni müstəqil təsdiqləmə) tələb edir.\n\n**Niyə ESG GRC-nin bir hissəsi sayılır?** Çünki ESG riskləri (məsələn, iqlim dəyişikliyi nəticəsində tədarük zəncirinin pozulması, və ya işçi hüquqları pozuntusu nəticəsində reputasiya zərəri) artıq **maliyyə riski** kimi qəbul edilir. İnvestorlar, banklar və reytinq agentlikləri ESG göstəricilərini kredit qərarlarında, investisiya qərarlarında istifadə edirlər.\n\n**Double Materiality (İkiqat Əhəmiyyətlilik):** Bu, ESG hesabatlılığının əsas prinsipidir və iki istiqamətli baxışı tələb edir:\n\n```\nİSTİQAMƏT 1: \"OUTSIDE-IN\" (Xaricdən-daxilə)\nDünyanın (iqlim dəyişikliyi, tənzimləmə dəyişiklikləri) \nşirkətə maliyyə təsiri necədir?\n→ Nümunə: \"İqlim dəyişikliyi nəticəsində yeni karbon vergisi \n  bizim istehsal xərcimizi necə artıra bilər?\"\n\nİSTİQAMƏT 2: \"INSIDE-OUT\" (Daxildən-xaricə)\nŞirkətin fəaliyyəti dünyaya (ətraf mühitə, cəmiyyətə) necə \ntəsir edir?\n→ Nümunə: \"Bizim istehsal prosesimiz nə qədər karbon emissiyası \n  yaradır?\"\n```\n\nBir şirkət ESG hesabatında yalnız bir sahəni deyil, hər ikisini əhatə etməlidir — yəni \"biz dünyaya necə təsir edirik\" VƏ \"dünya bizə necə təsir edir\" sualları birlikdə qiymətləndirilir. Yalnız bir istiqamətə fokuslanmaq (məsələn, yalnız \"bizə təsir\" barədə düşünmək) natamam ESG təhlili sayılır.\n\n**Sual 1**\nESG-nin üç komponentini sadalayın və \"G\" komponentinin Module 2-dəki Governance mövzusu ilə əlaqəsini izah edin.\n\n**Sual 2**\nESG niyə artıq təkcə \"yaxşı niyyət\" fəaliyyəti deyil, maliyyə riski kimi qəbul edilir?\n\n**Sual 3**\nDouble Materiality-nin iki istiqamətini nümunələrlə izah edin."}]'::jsonb FROM rooms WHERE slug='grc-esg-reporting-e-giris-rzmxeh' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'CSRD və Onun 2026-cı il Omnibus Dəyişiklikləri','25 dəq',0,'[{"body":"**CSRD (Corporate Sustainability Reporting Directive)** — Avropa İttifaqının şirkətləri ESG göstəricilərini rəsmi, standartlaşdırılmış formada (**ESRS** — European Sustainability Reporting Standards adlanan konkret standartlar əsasında) hesabat verməyə məcbur edən direktividir.\n\n**2025-2026-cı illərdə baş verən əsas dəyişiklik — \"Omnibus\" islahatı:** Avropa Komissiyası biznes tərəfindən bildirilən \"həddindən artıq bürokratik yük\" narahatlığına cavab olaraq, CSRD-nin əhatə dairəsini əhəmiyyətli dərəcədə daraltdı:\n\n```\nƏVVƏLKİ VƏZİYYƏT (Omnibus-dan əvvəl)\n→ Təxminən 50,000 şirkət CSRD əhatə dairəsində idi (250+ \n  işçi olan bütün böyük şirkətlər)\n\nOMNIBUS-DAN SONRA (2026-cı ilin fevralında rəsmiləşib)\n→ Ölçü hədləri yüksəldilib, əhatə dairəsi ~80% azalıb\n→ Yalnız ən böyük şirkətlər (adətən 1,000+ işçi və müəyyən \n  dövriyyə həddini keçən) icbari qalıb\n→ ESRS standartları özü sadələşdirilir (məlumat nöqtələrinin \n  sayı əhəmiyyətli azalır, bütün könüllü aşkarlamalar ləğv edilir)\n→ Assurance (təsdiqləmə) tələbi \"limited assurance\" (məhdud \n  təminat) səviyyəsində qalır — daha ciddi \"reasonable \n  assurance\" səviyyəsinə keçid təxirə salınıb\n```\n\n**Vacib məntiq:** Omnibus islahatı **hesabatlılığın tamamilə ləğv edilməsi** demək deyil — bu, əhatə dairəsinin daralması və tələblərin sadələşdirilməsi deməkdir. Hətta əhatə dairəsindən çıxan şirkətlər belə, iki səbəbdən ESG məlumatına ehtiyac duya bilər:\n\n1. **Dolayı təzyiq** — Böyük müştəri/tərəfdaş şirkətlər (özləri CSRD əhatəsində olanlar) öz tədarük zəncirindəki kiçik şirkətlərdən ESG məlumatı tələb edə bilər (Room 1-də (Module 2) öyrəndiyimiz \"asılılıqları xəritələndirmək\" məntiqinə bənzər).\n2. **Bazar təzyiqi** — Banklar, investorlar və reytinq agentlikləri ESG göstəricilərini risk qiymətləndirməsinə daxil etməyə davam edir, hətta hüquqi tələb olmasa belə.\n\n**Vaxt xətti (2026-cı ilin ortasına görə):**\n\n```\n2025 (Wave 1)  → NFRD altında hesabat verən köhnə şirkətlər \n                  artıq hesabat verməyə başlayıb\n2026 (Wave 2)  → Böyük AB şirkətləri (yeni, yüksəldilmiş \n                  həddə uyğun olanlar) FY2025 məlumatları \n                  üzrə hesabat verir\nFevral 2026     → Omnibus islahat direktivi rəsmən qəbul edilib\nFY2027          → Sadələşdirilmiş ESRS standartlarının tətbiqi \n                  gözlənilir\n2029            → Müəyyən AB xarici gəliri olan qeyri-AB \n                  şirkətləri (Wave 4) FY2028 üzrə hesabat \n                  verməyə başlayacaq\n```\n\n**Sual 1**\nOmnibus islahatının CSRD əhatə dairəsinə təsiri nə oldu (təxmini rəqəmlə)?\n\n**Sual 2**\nOmnibus islahatından sonra əhatə dairəsindən çıxan bir şirkət niyə yenə də ESG məlumatı toplamağa ehtiyac duya bilər?\n\n**Sual 3**\n\"Limited assurance\" ilə \"reasonable assurance\" arasındakı fərq nə ola bilər? (İpucu: Room 2-də (Module 6) öyrəndiyimiz sübut gücü iyerarxiyasını xatırlayın)"}]'::jsonb FROM rooms WHERE slug='grc-esg-reporting-e-giris-rzmxeh' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Praktiki Tapşırıq: TechNova CSRD Əhatə Dairəsindədirmi?','25 dəq',0,'[{"body":"TechNova MMC-nin hüquq departamenti sizdən CSRD əhatə dairəsi ilə bağlı ilkin qiymətləndirmə istəyib.\n\n**TechNova haqqında məlumat:**\n\n```\n- İşçi sayı: 250 (Module 2-dəki ssenaridən tanış)\n- TechNova Azərbaycanda qeydiyyatdan keçib, AB-də hüquqi \n  qurumu (subsidiary) yoxdur\n- Lakin TechNova-nın AB-də fəaliyyət göstərən bir neçə iri \n  fintech şirkəti ilə partnyorluğu var, onlara ödəniş \n  infrastrukturu təqdim edir\n- Bu partnyor şirkətlərdən biri (özü CSRD əhatəsində olan \n  böyük bir AB şirkəti) TechNova-dan \"tədarük zənciri ESG \n  məlumatı\" təqdim etməyi xahiş edib\n```\n\n**Sizin tapşırığınız:**\n\n**Addım 1** — TechNova birbaşa CSRD-nin icbari əhatə dairəsindədirmi? (Task 2-dəki meyarları tətbiq edin)\n\n**Addım 2** — TechNova-nın bu tələbə niyə yenə də cavab verməli ola biləcəyini izah edin (Task 2-dəki \"dolayı təzyiq\" konseptini tətbiq edin)\n\n**Addım 3** — TechNova-nın hazırlaya biləcəyi minimum ESG məlumat dəstini təklif edin (E, S, G hər birindən ən azı bir göstərici)\n\n**Kömək üçün nümunə həll (Addım 1 üzrə):**\n\n```\nADDIM 1 — BİRBAŞA ƏHATƏ DAİRƏSİ:\n\nTechNova birbaşa CSRD icbari əhatə dairəsində DEYİL, çünki:\n- AB-də qeydiyyatlı hüquqi qurumu (subsidiary) yoxdur — CSRD \n  əsasən AB-də qeydiyyatlı şirkətlərə (və müəyyən həddi \n  keçən AB gəliri olan qeyri-AB şirkətlərə, Wave 4) aiddir\n- İşçi sayı (250) Omnibus-dan sonra yüksəldilmiş hədlərə görə \n  çox güman ki, icbari hədlərin altındadır\n\nNəticə: TechNova-ya hüquqi baxımdan CSRD birbaşa tətbiq \nolunmur, amma bu, ESG sualının tamamilə əlaqəsiz olduğu \ndemək deyil (bax Addım 2).\n```\n\n**Öz-özünə keyfiyyət yoxlaması (Checklist):**\n\n```\n☐ Addım 1-də birbaşa əhatə dairəsi düzgün qiymətləndirilib \n  (AB qurumu yoxluğu və işçi sayı nəzərə alınıb)\n☐ Addım 2-də \"dolayı təzyiq\" konsepti konkret partnyor \n  münasibətinə istinadla izah edilib\n☐ Addım 3-də hər üç sahədən (E/S/G) ən azı bir konkret, \n  ölçülə bilən göstərici təklif edilib\n☐ Göstəricilər TechNova-nın fəaliyyət sahəsinə (fintech, \n  ödəniş infrastrukturu) uyğundur, ümumi/təsadüfi deyil\n```\n\n**Sual 1**\nTechNova-nın AB-də hüquqi qurumu olmaması niyə vacib amildir?\n\n**Sual 2**\nPartnyor şirkətin ESG məlumatı tələb etməsi TechNova üçün hüquqi öhdəlikdirmi, yoxsa kommersiya təzyiqidir? Fərq nə üçün vacibdir?\n\n**Sual 3**\nTechNova-nın G (Governance) göstəricisi kimi hansı konkret məlumatı təqdim edə biləcəyini Module 2-dəki mövzularla (Policy, Board strukturu) əlaqələndirərək izah edin.\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. ESG-nin üç komponentini sadalayın.\n2. Double Materiality-nin iki istiqamətini izah edin.\n3. Omnibus islahatı CSRD-yə hansı əsas dəyişikliyi gətirdi?\n4. Əhatə dairəsindən kənarda olan bir şirkət niyə yenə də ESG hazırlığına ehtiyac duya bilər?\n5. TechNova ssenarisində əsas nəticə nə idi — TechNova-nın CSRD ilə əlaqəsi tamamilə yoxdurmu?\n\n---"}]'::jsonb FROM rooms WHERE slug='grc-esg-reporting-e-giris-rzmxeh' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
