INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-6','MODULE 6: Audit & Assessment','PUBLISHED',6 FROM paths WHERE slug='grc' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'grc-audit-hesabati-hazirlamaq-sablon-bdatzv','Audit Hesabatı Hazırlamaq (Şablon)','Audit Hesabatı Hazırlamaq (Şablon)','GRC PATH · MODULE 6: Audit & Assessment','Room 1-də audit lifecycle-ını, Room 2-də isə Fieldwork mərhələsində sübut toplamağı öyrəndik — hətta TechNova-nın giriş idarəetməsi nəzarətini test edib bir tapıntı (finding) aşkar etdik: 10 hadisədən 2-si 4 saatlıq criteria-nı pozub, səbəb isə həftəsonu/tətil günlərinin sistemdə düzgün hesablanmaması idi.','GRC PATH','WALKTHROUGH','ADVANCED'::difficulty,'50 dəq (praktiki — şablon)',0,'GREEN',ARRAY['Bir Audit Hesabatının standart strukturunu tanımaq','"5 C" modelini (Condition, Criteria, Cause, Effect, Recommendation) tətbiq edərək tapıntı yaza bilmək','Risk səviyyəsi (High/Medium/Low) təyin etmə məntiqini başa düşmək','Management Response konsepsiyasını izah edə bilmək','Room 2-dəki test nəticələrinə əsaslanaraq tam bir audit finding yazmaq']::text[],'drive/18_I7ihBKKF0DZrS_K0zB5JgqsYbDAtzV.md','PUBLISHED',3,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='grc' AND m.slug='module-6' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Audit Hesabatının Strukturu','50 dəq (praktiki — şablon)',0,'[{"body":"# ROOM 3: Audit Hesabatı Hazırlamaq (Şablon)\n\n**Path:** GRC Fundamentals\n**Module:** Audit & Assessment\n**Çətinlik:** Hard\n**Təxmini vaxt:** 50 dəq (praktiki — şablon)\n\n## Room haqqında\n\nRoom 1-də audit lifecycle-ını, Room 2-də isə Fieldwork mərhələsində sübut toplamağı öyrəndik — hətta TechNova-nın giriş idarəetməsi nəzarətini test edib bir tapıntı (finding) aşkar etdik: 10 hadisədən 2-si 4 saatlıq criteria-nı pozub, səbəb isə həftəsonu/tətil günlərinin sistemdə düzgün hesablanmaması idi.\n\nİndi bu tapıntını **Reporting** mərhələsinə köçürmək vaxtıdır. Yaxşı toplanmış sübut, zəif yazılmış hesabatla öz dəyərini itirə bilər — idarəetmə (management) tapıntını başa düşməzsə və ya ciddiyə almazsa, heç bir dəyişiklik baş verməyəcək. Bu room-da bir audit hesabatının strukturunu və konkret bir \"finding\"-i necə yazmağı öyrənəcəksiniz.\n\n## Öyrənmə nəticələri\n\n- Bir Audit Hesabatının standart strukturunu tanımaq\n- \"5 C\" modelini (Condition, Criteria, Cause, Effect, Recommendation) tətbiq edərək tapıntı yaza bilmək\n- Risk səviyyəsi (High/Medium/Low) təyin etmə məntiqini başa düşmək\n- Management Response konsepsiyasını izah edə bilmək\n- Room 2-dəki test nəticələrinə əsaslanaraq tam bir audit finding yazmaq\n\nBir Audit Hesabatı, ölçüsündən asılı olmayaraq, aşağıdakı standart bölmələrdən ibarətdir:\n\n```\n┌────────────────────────────────────────────────────────────┐\n│ 1. EXECUTIVE SUMMARY (İcraçı Xülasə)                          │\n│    Bir səhifədə: nə audit olundu, əsas nəticə nədir?          │\n├────────────────────────────────────────────────────────────┤\n│ 2. BACKGROUND & OBJECTIVES (Kontekst və Məqsəd)                │\n│    Niyə bu audit aparıldı, hansı sual cavablandırılır?         │\n├────────────────────────────────────────────────────────────┤\n│ 3. SCOPE & METHODOLOGY (Əhatə dairəsi və Metodologiya)         │\n│    Nə yoxlanıldı, hansı üsullarla (Room 2-dəki test üsulları)  │\n├────────────────────────────────────────────────────────────┤\n│ 4. FINDINGS (Tapıntılar)                                       │\n│    Hər tapıntı: Condition, Criteria, Cause, Effect,             │\n│    Recommendation + Risk Rating                                 │\n├────────────────────────────────────────────────────────────┤\n│ 5. MANAGEMENT RESPONSE (İdarəetmənin Cavabı)                   │\n│    Menecerlərin tapıntıya cavabı, düzəliş planı, tarix          │\n├────────────────────────────────────────────────────────────┤\n│ 6. OVERALL CONCLUSION (Ümumi Nəticə)                            │\n│    Nəzarət mühiti ümumilikdə necə qiymətləndirilir?             │\n└────────────────────────────────────────────────────────────┘\n```\n\n**Executive Summary** — Board və üst rəhbərlik çox vaxt yalnız bu hissəni oxuyur. Ona görə bir paraqrafda ən vacib nəticə (məsələn, \"1 Yüksək, 2 Orta risk tapıntısı aşkar olundu\") aydın yazılmalıdır. Texniki detala getmək lazım deyil.\n\n**Background & Objectives** — Room 1-dəki Planning mərhələsindən gəlir: niyə bu sahə seçildi (məsələn, keçmiş insident), auditin məqsədi nə idi.\n\n**Scope & Methodology** — Nə (hansı sistem, hansı dövr) və necə (hansı test üsulları — Inquiry/Observation/Inspection/Reperformance) yoxlanıldığı bildirilir. Bu, hesabatın **etibarlılığını** göstərir — oxucu \"bu nəticə nə qədər etibarlıdır?\" sualına cavab tapır.\n\n**Findings** — Hesabatın \"ürəyi\". Hər tapıntı struktura malikdir (bunu Task 2-də ətraflı görəcəyik).\n\n**Management Response** — Yaxşı audit hesabatı birtərəfli deyil — tapıntı ilə qarşılaşan menecer öz mövqeyini (razıdır/qismən razıdır/razı deyil) və düzəliş planını (nə vaxta qədər, kim həyata keçirəcək) yazır. Bu, hesabata hesabatlıq (accountability) qatır.\n\n**Overall Conclusion** — Bütün tapıntıları ümumiləşdirərək, audit edilən sahənin ümumi nəzarət mühitinin (control environment) nə qədər güclü olduğuna dair yekun rəy verilir.\n\n**Sual 1**\nAltı standart bölməni sadalayın və hər birinin əsas funksiyasını yazın.\n\n**Sual 2**\nNiyə Executive Summary-də texniki detala getmək tövsiyə olunmur?\n\n**Sual 3**\nManagement Response bölməsi hesabata nə əlavə edir? Bu bölmə olmasa nə itirilər?"}]'::jsonb FROM rooms WHERE slug='grc-audit-hesabati-hazirlamaq-sablon-bdatzv' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Tapıntı Yazmaq: "5 C" Modeli','50 dəq (praktiki — şablon)',0,'[{"body":"Hər audit tapıntısı (finding) beş komponentdən ibarət olmalıdır — bu, \"**5 C**\" modeli adlanır:\n\n```\nCONDITION  →  \"Nə tapdıq?\" (faktiki vəziyyət)\nCRITERIA   →  \"Nə olmalı idi?\" (standart/gözlənti)\nCAUSE      →  \"Niyə belə oldu?\" (kök səbəb)\nEFFECT     →  \"Nəticədə nə risk/zərər yarana bilər?\"\nRECOMMENDATION → \"Nə edilməlidir?\"\n```\n\nBu beş komponentin **hər biri** olmadan tapıntı natamam sayılır:\n\n- Yalnız **Condition + Criteria** yazsanız → oxucu \"bəs niyə?\" sualını verir (Cause yoxdur)\n- **Cause** olmadan → tövsiyə səthi qalır (simptomu, kök səbəbi yox, düzəldir)\n- **Effect** olmadan → menecer \"bu, həqiqətən vacibdirmi?\" deyə düşünür, prioritetləşdirmir\n- **Recommendation** olmadan → tapıntı sadəcə tənqiddir, konstruktiv həll təklifi yoxdur\n\n**Nümunə (fərqli bir mövzu üzərində — patch management):**\n\n```\nCONDITION:\nTest edilən 15 serverdən 4-də kritik təhlükəsizlik patch-ləri \nson 90 gündə quraşdırılmayıb.\n\nCRITERIA:\nTechNova Patch Management Standard-ına görə, kritik (critical/\nhigh severity) patch-lər aşkar olunduqdan sonra 14 gün ərzində \nquraşdırılmalıdır.\n\nCAUSE:\nPatch quraşdırma prosesi manual həyata keçirilir və məsul \nşəxsin işgüzar səfər/məzuniyyət dövründə əvəzedici təyin \nolunmayıb, nəticədə proses gecikib.\n\nEFFECT:\nBu serverlər məlum zəifliklərə (known vulnerabilities) açıq \nqalır, bu da icazəsiz giriş və ya məlumat sızması riskini \nartırır. Xüsusilə bu serverlərdən biri müştəri ödəniş \nməlumatlarını emal etdiyi üçün risk daha yüksəkdir.\n\nRECOMMENDATION:\n1) Patch quraşdırma prosesi avtomatlaşdırılsın (mümkün olduğu \nqədər), 2) Manual proseslər üçün əvəzedici mexanizm (backup \nowner) təyin edilsin, 3) Aylıq patch statusu hesabatı CISO-ya \ntəqdim olunsun.\n```\n\n**Risk Rating (Risk Səviyyəsi):** Hər tapıntıya bir risk səviyyəsi verilir — bu, Effect-in ciddiliyi və Condition-un tezliyi/əhatə dairəsi əsasında müəyyən edilir:\n\n| Səviyyə | Meyar | Nümunə |\n|---|---|---|\n| **High (Yüksək)** | Ciddi maliyyə/hüquqi/reputasiya zərəri, geniş əhatə, dərhal tədbir tələb edir | Müştəri məlumatlarının qorunmasız qalması |\n| **Medium (Orta)** | Orta səviyyəli təsir, məhdud əhatə, qısa müddətdə düzəldilməlidir | Yuxarıdakı giriş idarəetməsi tapıntısı |\n| **Low (Aşağı)** | Minimal təsir, prosesin təkmilləşdirilməsi xarakterli | Sənədləşmədə kiçik uyğunsuzluq |\n\n**Vacib məntiq:** Risk Rating **subyektiv təxmin deyil** — Effect bölməsindəki konkret zərər təsviri ilə əsaslandırılmalıdır. Əgər auditor \"High\" deyirsə, Effect bölməsində bunu dəstəkləyən konkret izah olmalıdır (məsələn, \"müştəri ödəniş məlumatlarını emal edir\" kimi).\n\n**Sual 1**\n\"5 C\" modelinin beş komponentini sadalayın.\n\n**Sual 2**\nCause olmadan yazılan bir tövsiyə niyə \"səthi\" sayılır? Nümunə ilə izah edin.\n\n**Sual 3**\nRisk Rating necə müəyyən edilir — hansı iki amilə əsaslanır?"}]'::jsonb FROM rooms WHERE slug='grc-audit-hesabati-hazirlamaq-sablon-bdatzv' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Praktiki Tapşırıq: Tam Audit Finding Yazın','50 dəq (praktiki — şablon)',0,'[{"body":"İndi Room 2-də test etdiyiniz TechNova-nın giriş idarəetməsi nəzarəti üçün **tam bir audit finding** yazacaqsınız — \"5 C\" modelini və risk rating-i tətbiq edərək.\n\n**Xatırlatma (Room 2-dən):**\n- 10 hadisədən 2-si (№4 və №8) 4 saatlıq criteria-nı pozub\n- Hər iki hal həftəsonu/tətil dövrü ilə üst-üstə düşür\n- Root cause: sistemdə iş saatı hesablanmasının qeyri-standart günləri (həftəsonu/tətil) nəzərə almaması\n- Gecikmə müddətləri: 68.9 saat və 137.5 saat (kriteriyanı əhəmiyyətli dərəcədə üstələyib)\n\n**Sizin tapşırığınız:**\n\n**Addım 1** — Condition yazın (konkret ədədlərlə: neçə/neçə, hansı faiz)\n\n**Addım 2** — Criteria yazın (hansı standart/tələbə istinad edir)\n\n**Addım 3** — Cause yazın (Room 2-dəki pattern analizini əsas götürün)\n\n**Addım 4** — Effect yazın (bu boşluq nəticəsində hansı risk yaranır?)\n\n**Addım 5** — Recommendation yazın (minimum 2 konkret addım)\n\n**Addım 6** — Risk Rating təyin edin və əsaslandırın (High/Medium/Low)\n\n**Addım 7** — Management Response üçün nümunə cavab yazın (menecerin tapıntıya necə cavab verəcəyini təsəvvür edin)\n\n**Kömək üçün qismən nümunə (yalnız Condition və Criteria):**\n\n```\nCONDITION:\nTest edilən 10 hadisədən 2-də (20%) işdən çıxan işçilərin \nsistem girişi 4 iş saatlıq həddi əhəmiyyətli dərəcədə üstələyərək \nbağlanıb (68.9 saat və 137.5 saat). Hər iki hal işdən çıxmanın \nhəftəsonu/tətil dövrünə düşdüyü hallarla üst-üstə düşür.\n\nCRITERIA:\nTechNova Access Control Standard, bölmə 4.2-yə görə, İT \ndepartamenti HR bildirişindən sonra 4 iş saatı ərzində bütün \nsistem girişlərini ləğv etməlidir.\n```\n\n**Öz-özünə keyfiyyət yoxlaması (Checklist):**\n\n```\n☐ Condition konkret ədədlərlə yazılıb (10-dan 2-si, 20%, saat \n  fərqləri)\n☐ Criteria konkret standarta (bölmə nömrəsi ilə) istinad edir\n☐ Cause Room 2-dəki pattern-ə (həftəsonu/tətil) əsaslanır, \n  spekulyativ deyil\n☐ Effect konkret risk təsvir edir (təkcə \"pis nəticə ola bilər\" \n  yox, nə cür zərər)\n☐ Recommendation ən azı 2 konkret, icra oluna bilən addımdan \n  ibarətdir\n☐ Risk Rating seçimi Effect-dəki izahla üst-üstə düşür (High \n  desəniz, Effect də ciddi olmalıdır)\n☐ Management Response realist görünür (nə \"hər şeyi tam qəbul \n  edirik\", nə \"heç nə səhv deyil\" — balanslaşdırılmış)\n```\n\n**Sual 1**\nBu tapıntı üçün hansı Risk Rating (High/Medium/Low) seçdiniz və niyə? (Room 2-dəki qismən effektivlik nəticəsini nəzərə alın)\n\n**Sual 2**\nRecommendation-da texniki (sistemin düzəldilməsi) və prosessual (əvəzedici mexanizm) tədbirləri ayrı-ayrı düşünmək niyə faydalıdır?\n\n**Sual 3**\nYazdığınız Management Response-da menecer tapıntını tam qəbul etməyib, qismən razılaşıbsa (məsələn, \"avtomatlaşdırma bahalıdır, əvəzinə manual yoxlama tezliyini artıracağıq\" desə), bu, hesabatın dəyərini azaldırmı? Niyə?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Audit hesabatının altı standart bölməsini sadalayın.\n2. \"5 C\" modelinin beş komponentini və onların sırasını izah edin.\n3. Risk Rating-in \"subyektiv təxmin deyil\" olması nə deməkdir?\n4. Management Response bölməsinin hesabata gətirdiyi əsas dəyər nədir?\n5. TechNova giriş idarəetməsi tapıntısında Cause və Effect arasındakı əlaqəni bir cümlə ilə izah edin.\n\n---"}]'::jsonb FROM rooms WHERE slug='grc-audit-hesabati-hazirlamaq-sablon-bdatzv' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO paths(slug,title,description,category,status,order_index) VALUES ('grc','GRC PATH','GRC PATH kurikulumu','GRC PATH' ,'PUBLISHED',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-6','MODULE 6: Audit & Assessment','PUBLISHED',6 FROM paths WHERE slug='grc' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'grc-control-testing--sxc1w','Control Testing','Control Testing','GRC PATH · MODULE 6: Audit & Assessment','Room 1-də audit lifecycle-ının Fieldwork mərhələsində "sübut toplanır" dedik — amma bu, dəqiq olaraq necə edilir? Sadəcə kiməsə "bunu edirsinizmi?" deyə soruşmaq kifayət edirmi? Cavab: xeyr. Auditor-un fikri, hətta ən dürüst insandan alınsa belə, **sübut** sayılmır — çünki insanlar səhv edə, unuda və ya vəziyyəti fərqli görə bilərlər. Bu problemi həll edən yanaşma **Control Testing**-dir.','GRC PATH','WALKTHROUGH','ADVANCED'::difficulty,'45 dəq (praktiki)',0,'GREEN',ARRAY['Nəzarət növlərini (preventive, detective, corrective) fərqləndirə bilmək','Dörd əsas test üsulunu (inquiry, observation, inspection, reperformance) izah edə bilmək','Sübutun keyfiyyət iyerarxiyasını başa düşmək','Nümunə (sample) seçimi məntiqini tətbiq edə bilmək','Real test nəticələrinə əsasən "nəzarət effektivdir/deyil" nəticəsi çıxara bilmək']::text[],'drive/1-tGA0PAoBjqJ1y0AljtqeFQeO9-sxc1W.md','PUBLISHED',2,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='grc' AND m.slug='module-6' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Nəzarət Növləri (Control Types)','45 dəq (praktiki)',0,'[{"body":"# ROOM 2: Control Testing\n\n**Path:** GRC Fundamentals\n**Module:** Audit & Assessment\n**Çətinlik:** Medium-Hard\n**Təxmini vaxt:** 45 dəq (praktiki)\n\n## Room haqqında\n\nRoom 1-də audit lifecycle-ının Fieldwork mərhələsində \"sübut toplanır\" dedik — amma bu, dəqiq olaraq necə edilir? Sadəcə kiməsə \"bunu edirsinizmi?\" deyə soruşmaq kifayət edirmi? Cavab: xeyr. Auditor-un fikri, hətta ən dürüst insandan alınsa belə, **sübut** sayılmır — çünki insanlar səhv edə, unuda və ya vəziyyəti fərqli görə bilərlər. Bu problemi həll edən yanaşma **Control Testing**-dir.\n\nBu room-da nəzarətlərin (control) növlərini, onları test etmə üsullarını və toplanan sübutun keyfiyyətini necə qiymətləndirməyi öyrənəcək, sonra TechNova MMC-nin real nəzarətini test edəcəksiniz.\n\n## Öyrənmə nəticələri\n\n- Nəzarət növlərini (preventive, detective, corrective) fərqləndirə bilmək\n- Dörd əsas test üsulunu (inquiry, observation, inspection, reperformance) izah edə bilmək\n- Sübutun keyfiyyət iyerarxiyasını başa düşmək\n- Nümunə (sample) seçimi məntiqini tətbiq edə bilmək\n- Real test nəticələrinə əsasən \"nəzarət effektivdir/deyil\" nəticəsi çıxara bilmək\n\nNəzarətlər (control) — riski azaltmaq üçün qurulan tədbirlərdir. Onları zaman baxımından üç növə ayırmaq olar:\n\n```\n   RİSK YARANMAZDAN ƏVVƏL         RİSK BAŞ VERƏNDƏ            RİSK BAŞ VERDİKDƏN SONRA\n   ┌──────────────────┐          ┌──────────────────┐        ┌──────────────────┐\n   │   PREVENTIVE      │         │   DETECTIVE        │       │   CORRECTIVE       │\n   │  (Qarşısıalıcı)   │────────▶│  (Aşkaredici)      │──────▶│  (Düzəldici)       │\n   └──────────────────┘          └──────────────────┘        └──────────────────┘\n   Riskin baş verməsinin          Riskin baş verdiyini         Baş vermiş problemi\n   qarşısını alır                 aşkar edir                   düzəldir/zərəri azaldır\n```\n\n**Preventive Control** — Riskin baş verməsinin qarşısını əvvəlcədən alır.\n> Nümunə: MFA (çoxfaktorlu autentifikasiya), giriş icazələri (permissions), firewall qaydaları.\n\n**Detective Control** — Risk artıq baş veribsə, bunu aşkar edir.\n> Nümunə: Log monitorinq sistemi, anomaliya bildirişləri, illik audit-in özü.\n\n**Corrective Control** — Baş vermiş problemi düzəldir və ya zərəri minimuma endirir.\n> Nümunə: İnsident cavab planı (incident response), backup-dan bərpa prosesi, zərərli proqramın karantinə alınması.\n\n**Vacib məntiq:** Yaxşı təhlükəsizlik proqramı bu üç növü **birlikdə** istifadə edir — yalnız Preventive-ə güvənmək təhlükəlidir, çünki heç bir preventive control 100% effektiv deyil (bax: \"defense in depth\" prinsipi). Auditor bir sahəni yoxlayanda, təkcə \"preventive control varmı?\" yox, \"əgər bu control keçilərsə, bunu aşkar edən (detective) nəzarət varmı?\" sualını da verir.\n\n**Praktiki misal — TechNova-nın giriş idarəetməsi (Room 1-dəki ssenari):**\n\n| Nəzarət növü | Konkret nümunə |\n|---|---|\n| Preventive | HR bildirişi əsasında hesabın avtomatik deaktivasiyası prosesi |\n| Detective | Aylıq \"aktiv hesablar vs aktiv işçilər\" tutuşdurma hesabatı |\n| Corrective | Uyğunsuzluq aşkar olunanda hesabın dərhal manual bağlanması prosesi |\n\n**Sual 1**\nÜç nəzarət növünü sadalayın və hər birinin nə vaxt işə düşdüyünü izah edin.\n\n**Sual 2**\nNiyə yalnız Preventive control-lara güvənmək riskli hesab olunur?\n\n**Sual 3**\nTechNova-nın giriş idarəetməsi nümunəsində Detective control konkret olaraq nəyi aşkar edir?"}]'::jsonb FROM rooms WHERE slug='grc-control-testing--sxc1w' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Test Üsulları və Sübutun Keyfiyyəti','45 dəq (praktiki)',0,'[{"body":"Auditor bir nəzarətin faktiki işlədiyini yoxlamaq üçün dörd əsas üsuldan istifadə edir. Bunlar **sübut gücünə görə** aşağıdan yuxarıya sıralanır:\n\n```\nZƏİF SÜBUT                                          GÜCLÜ SÜBUT\n    │                                                      │\n    ▼                                                      ▼\n┌──────────┐   ┌─────────────┐   ┌─────────────┐   ┌─────────────────┐\n│ INQUIRY   │──▶│ OBSERVATION  │──▶│ INSPECTION   │──▶│ REPERFORMANCE    │\n│ (Sorğu)   │   │ (Müşahidə)   │   │ (Yoxlama)    │   │ (Yenidən icra)   │\n└──────────┘   └─────────────┘   └─────────────┘   └─────────────────┘\n```\n\n**1. Inquiry (Sorğu)** — İşçidən prosesi necə etdiyini soruşmaq. **Ən zəif sübutdur**, çünki yalnız sözə əsaslanır, sübut sənədi yoxdur. Tək başına heç vaxt kifayət etmir, digər üsullarla dəstəklənməlidir.\n\n> Nümunə: \"İşdən çıxan işçinin hesabını necə bağlayırsınız?\" — İT işçisi prosesi izah edir.\n\n**2. Observation (Müşahidə)** — Auditor prosesin icra olunmasını canlı izləyir. Sorğudan güclüdür, amma yalnız **müşahidə anında** doğrudur — insanlar auditor izlədiyini bilərkən fərqli davrana bilər (bu, \"Hawthorne effekti\" adlanır).\n\n> Nümunə: Auditor İT işçisinin bir hesabı canlı olaraq necə bağladığını izləyir.\n\n**3. Inspection (Sənəd/sistem yoxlanması)** — Konkret sənəd, log və ya sistem qeydini yoxlamaq. Güclü sübutdur, çünki obyektivdir və geriyə dönük yoxlanıla bilər.\n\n> Nümunə: Active Directory-dəki hesab bağlanma tarixini HR-ın işdən çıxma tarixi ilə müqayisə etmək (log/sənəd əsasında).\n\n**4. Reperformance (Yenidən icra)** — Auditor prosesi özü təkrar həyata keçirir və eyni nəticəni alıb-almadığını yoxlayır. **Ən güclü sübutdur**, çünki auditor şəxsən nəticəni doğrulayır, heç bir vasitəçiyə etibar etmir.\n\n> Nümunə: Auditor özü bir test hesabı yaradıb, sonra onu deaktiv edərək, prosesin sənədləşdirildiyi kimi işlədiyini yoxlayır.\n\n**Hansı üsulu nə vaxt seçmək?** Bu, riskin səviyyəsindən asılıdır — yüksək riskli sahələrdə (məsələn, maliyyə tranzaksiyaları, kritik giriş nəzarəti) auditor Inspection və ya Reperformance kimi güclü sübut tələb edir; aşağı riskli, rəsmi sahələrdə Inquiry və Observation kifayət edə bilər.\n\n**Sample (Nümunə) seçimi:** Auditor adətən **bütün** hadisələri (məsələn, bütün işdən çıxan işçiləri) yoxlaya bilmir, ona görə təsadüfi və ya risk-əsaslı nümunə seçir. Vacib qayda: nümunə **populyasiyanı təmsil etməlidir** — yalnız \"asan tapılan\" və ya \"problemsiz göründüyü bilinən\" hadisələri seçmək (bu, \"cherry-picking\" adlanır) sübutun etibarlılığını sıfırlayır.\n\n**Sual 1**\nDörd test üsulunu ən zəifdən ən güclüyə doğru sıralayın və hər birini bir cümlə ilə təsvir edin.\n\n**Sual 2**\n\"Hawthorne effekti\" nədir və Observation üsulunun etibarlılığına necə təsir edir?\n\n**Sual 3**\n\"Cherry-picking\" nə deməkdir və niyə sample seçimində bundan qaçınmaq lazımdır?"}]'::jsonb FROM rooms WHERE slug='grc-control-testing--sxc1w' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Praktiki Tapşırıq: TechNova-nın Giriş İdarəetməsi Nəzarətini Test Edin','45 dəq (praktiki)',0,'[{"body":"Room 1-dəki audit planına əsasən, siz artıq Fieldwork mərhələsindəsiniz. Aşağıda son 12 ayda TechNova-dan işdən çıxan **10 işçinin** nümunəsi (sample) və onların hesab bağlanma məlumatları verilib. Criteria (meyar) xatırladaq: **HR bildirişindən sonra 4 iş saatı ərzində hesab bağlanmalıdır.**\n\n```\n№  | İşdən çıxma tarixi | HR bildirişi vaxtı | Hesab bağlanma vaxtı | Fərq (saat)\n───┼────────────────────┼─────────────────────┼───────────────────────┼─────────────\n1  | 14 Yan, 17:00       | 14 Yan, 17:10        | 14 Yan, 18:45          | 1.6 saat  ✓\n2  | 22 Yan, 09:00       | 22 Yan, 09:15        | 22 Yan, 11:00          | 1.75 saat ✓\n3  | 03 Fev, 16:00       | 04 Fev, 10:00        | 04 Fev, 12:30          | 2.5 saat  ✓\n4  | 11 Fev, 12:00       | 11 Fev, 12:05        | 15 Fev, 09:00          | 68.9 saat ✗\n5  | 19 Mar, 14:00       | 19 Mar, 14:20        | 19 Mar, 17:30          | 3.17 saat ✓\n6  | 02 Apr, 10:00       | 02 Apr, 10:10        | 02 Apr, 15:00          | 4.83 saat ✗\n7  | 15 May, 11:00       | 15 May, 11:05        | 15 May, 13:00          | 1.92 saat ✓\n8  | 28 May, 15:00       | 28 May, 15:30        | 04 İyun, 09:00         | 137.5 saat ✗\n9  | 09 İyun, 09:00      | 09 İyun, 09:10       | 09 İyun, 11:45         | 2.58 saat ✓\n10 | 20 İyul, 13:00      | 20 İyul, 13:15       | 20 İyul, 16:00         | 2.75 saat ✓\n```\n\n**Sizin tapşırığınız:**\n\n**Addım 1** — Hər bir hadisə üçün Criteria-ya (4 saat) uyğun olub-olmadığını təyin edin (yuxarıda ✓/✗ ilə işarələnib, siz bunun məntiqini izah edin)\n\n**Addım 2** — Uyğunsuzluq faizini hesablayın (neçə/10 hadisə criteria-nı pozub?)\n\n**Addım 3** — Uyğunsuzluqların (№4 və №8) ümumi xüsusiyyətini axtarın (pattern analizi) — bu, \"root cause\" tapmağa kömək edir\n\n**Addım 4** — Bu nəticələrə əsasən nəzarətin **effektiv** olub-olmadığı barədə qərar (conclusion) yazın\n\n**Kömək üçün nümunə həll strukturu:**\n\n```\nNƏTİCƏLƏRİN TƏHLİLİ:\n\nUyğunsuzluq faizi: 2/10 = 20% (Hadisə #4 və #8)\n\nPattern müşahidəsi:\n- Hadisə #4: işdən çıxma Cümə günü (11 Fev, 12:00) baş verib, \n  hesab bağlanması növbəti Bazar ertəsi/Çərşənbə axşamına \n  düşüb — bu, HƏFTƏSONU/İŞ GÜNÜ FASİLƏSİ ilə bağlı ola bilər.\n- Hadisə #8: eyni şəkildə, işdən çıxma 28 May, sonrakı bağlanma \n  4 İyun-da — arada uzun fasilə var, mümkün ki, bayram/tətil \n  dövrü.\n\nEhtimal olunan səbəb (Root Cause):\nProses \"4 iş saatı\" tələbini nəzərdə tutur, amma sistemdə iş \nsaatı hesablanması düzgün konfiqurasiya olunmayıb — həftəsonu/\nbayram günləri \"saat sayılmaya\" daxil edilmir, nəticədə real \ngecikmə criteria-nı üstələyir.\n\nQƏRAR (Conclusion):\nNəzarət QİSMƏN EFFEKTİVDİR. Normal iş günlərində proses \ncriteria-ya uyğun işləyir (8/10 hadisə), amma həftəsonu/tətil \nkimi qeyri-standart vaxtlarda sistemli boşluq mövcuddur. Bu, \nRoom 3-də yazılacaq audit hesabatına \"Orta\" risk səviyyəli \ntapıntı kimi daxil edilməlidir, çünki bu boşluq nəticəsində \nişdən çıxan işçinin girişi bir neçə gün açıq qala bilər.\n```\n\n**Öz-özünə keyfiyyət yoxlaması (Checklist):**\n\n```\n☐ Uyğunsuzluq faizi düzgün hesablanıb (2/10 = 20%)\n☐ Pattern (ortaq xüsusiyyət) tapılıb, təsadüfi sayılmayıb\n☐ Root cause fərziyyəsi məlumatlara əsaslanır (spekulyasiya \n  deyil, cədvəldəki tarixlərə istinad edir)\n☐ Yekun qərar \"Effektiv / Qismən Effektiv / Effektiv deyil\" \n  formatında aydın verilib\n☐ Qərar həddindən artıq sərt (bir istisnaya görə \"tamamilə \n  effektiv deyil\" demək) və ya həddindən artıq yumşaq \n  (20%-i görməzdən gəlmək) deyil\n```\n\n**Sual 1**\nNiyə 2/10 uyğunsuzluq faizini görüb dərhal \"nəzarət tamamilə effektiv deyil\" nəticəsinə gəlmək düzgün deyil?\n\n**Sual 2**\nPattern analizi (həftəsonu/tətil əlaqəsi) niyə sadəcə \"20% xəta var\" deməkdən daha dəyərlidir?\n\n**Sual 3**\nBu tapıntı üçün hansı test üsulu istifadə olunub (Inquiry/Observation/Inspection/Reperformance)? Niyə?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Üç nəzarət növünü (Preventive/Detective/Corrective) sadalayın və hər birinə bir nümunə verin.\n2. Dörd test üsulunu sübut gücünə görə sıralayın.\n3. Reperformance niyə ən güclü sübut sayılır?\n4. \"Cherry-picking\" sample seçimində niyə problemlidir?\n5. TechNova nümunəsində aşkar olunan tapıntının root cause-u nə idi və bu, hansı risk səviyyəsinə uyğun gəlir?\n\n---"}]'::jsonb FROM rooms WHERE slug='grc-control-testing--sxc1w' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO paths(slug,title,description,category,status,order_index) VALUES ('grc','GRC PATH','GRC PATH kurikulumu','GRC PATH' ,'PUBLISHED',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
