INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'grc-security-policy-yazmaq-case-study-o6xopa','Security Policy Yazmaq (Case Study)','Security Policy Yazmaq (Case Study)','GRC PATH · MODULE 2: Governance & Policy','Room 1 və Room 2-də sənəd iyerarxiyasını və governance strukturunu nəzəri şəkildə öyrəndik. İndi vaxtı gəldi ki, nəzəriyyəni əməli tətbiq edək: **əvvəldən sona qədər real bir Security Policy sənədi yazmaq**. Bu, GRC sahəsində işləyən mütəxəssislərin ən çox rastlaşdığı praktiki tapşırıqlardan biridir — istər yeni bir sahə üçün ilk dəfə policy yazasınız, istərsə köhnə bir sənədi yeniləyəsiniz.','GRC PATH','WALKTHROUGH','INTERMEDIATE'::difficulty,'60 dəq (praktiki — sənəd hazırlama)',0,'GREEN',ARRAY['Bir Security Policy sənədinin standart strukturunu (komponentlərini) tanımaq','Yaxşı yazılmış policy ilə zəif yazılmış policy arasındakı fərqi ayırd edə bilmək','Real ssenari əsasında tam funksional bir Acceptable Use Policy (AUP) yazmaq','Yazılmış policy-ni keyfiyyət meyarlarına görə özü-özünü qiymətləndirə bilmək']::text[],'drive/1kpQ6lhpGxylJqpJMMbzNej_P2Bo6xoPA.md','PUBLISHED',3,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='grc' AND m.slug='module-2' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Policy Sənədinin Standart Komponentləri','60 dəq (praktiki — sənəd hazırlama)',0,'[{"body":"# ROOM 3: Security Policy Yazmaq (Case Study)\n\n**Path:** GRC Fundamentals\n**Module:** Governance & Policy\n**Çətinlik:** Medium\n**Təxmini vaxt:** 60 dəq (praktiki — sənəd hazırlama)\n\n## Room haqqında\n\nRoom 1 və Room 2-də sənəd iyerarxiyasını və governance strukturunu nəzəri şəkildə öyrəndik. İndi vaxtı gəldi ki, nəzəriyyəni əməli tətbiq edək: **əvvəldən sona qədər real bir Security Policy sənədi yazmaq**. Bu, GRC sahəsində işləyən mütəxəssislərin ən çox rastlaşdığı praktiki tapşırıqlardan biridir — istər yeni bir sahə üçün ilk dəfə policy yazasınız, istərsə köhnə bir sənədi yeniləyəsiniz.\n\nBu room-da siz **TechNova MMC** adlı fərz edilən bir şirkət üçün işləyəcəksiniz — bu ssenari sonrakı modullarda da istifadə olunacaq, ona görə şirkəti yaxşı tanımaq faydalı olacaq.\n\n**TechNova MMC haqqında:** Orta ölçülü fintech şirkətidir (≈250 işçi), onlayn ödəniş həlləri təqdim edir, müştəri məlumatları (maliyyə və şəxsi) saxlayır, həm ofisdən, həm uzaqdan işləyən komandaya malikdir və maliyyə sektoru tənzimləyicilərinə hesabat verməli olur.\n\n## Öyrənmə nəticələri\n\n- Bir Security Policy sənədinin standart strukturunu (komponentlərini) tanımaq\n- Yaxşı yazılmış policy ilə zəif yazılmış policy arasındakı fərqi ayırd edə bilmək\n- Real ssenari əsasında tam funksional bir Acceptable Use Policy (AUP) yazmaq\n- Yazılmış policy-ni keyfiyyət meyarlarına görə özü-özünü qiymətləndirə bilmək\n\nYaxşı yazılmış hər Security Policy sənədi, mövzusundan asılı olmayaraq, təxminən eyni struktur skeletinə malikdir. Bu struktur təsadüfi deyil — hər komponent müəyyən bir suala cavab verir və onun olmaması sənədi icra edilə bilməz edir.\n\n```\n┌──────────────────────────────────────────────────────────┐\n│ 1. PURPOSE (Məqsəd)                                       │\n│    Bu policy niyə mövcuddur? Hansı riski azaldır?         │\n├──────────────────────────────────────────────────────────┤\n│ 2. SCOPE (Əhatə dairəsi)                                   │\n│    Kimə/nəyə aiddir? Kimə aid deyil?                       │\n├──────────────────────────────────────────────────────────┤\n│ 3. POLICY STATEMENT (Əsas öhdəlik/qaydalar)                │\n│    Konkret olaraq nə tələb olunur/qadağandır?              │\n├──────────────────────────────────────────────────────────┤\n│ 4. ROLES & RESPONSIBILITIES (Rollar və məsuliyyətlər)      │\n│    Kim nəyə cavabdehdir?                                   │\n├──────────────────────────────────────────────────────────┤\n│ 5. COMPLIANCE & ENFORCEMENT (Uyğunluq və icra)              │\n│    Əməl edilməzsə nə baş verir?                             │\n├──────────────────────────────────────────────────────────┤\n│ 6. EXCEPTIONS (İstisnalar)                                  │\n│    Qaydadan kənara çıxmaq mümkündürmü, necə?                │\n├──────────────────────────────────────────────────────────┤\n│ 7. REVIEW & OWNERSHIP (Nəzərdən keçirmə və sahiblik)        │\n│    Sənəd kimə məxsusdur, nə vaxt yenilənir?                 │\n└──────────────────────────────────────────────────────────┘\n```\n\nHər komponenti ətraflı görək:\n\n**1. Purpose** — Bir-iki cümlə ilə niyə bu sənədin mövcud olduğunu izah edir. Yaxşı Purpose bölməsi konkret riskə istinad edir (\"icazəsiz giriş riskini azaltmaq üçün\"), ümumi ifadələrdən (\"təhlükəsizliyi təmin etmək üçün\") qaçır.\n\n**2. Scope** — Kimlər (bütün işçilər? podratçılar? yalnız İT?), hansı sistemlər (bütün sistemlər? yalnız istehsal mühiti?) əhatə olunur. Scope-un aydın olmaması ən çox rast gəlinən policy zəifliyidir — \"kim aid deyil\" sualı çox vaxt unudulur.\n\n**3. Policy Statement** — Sənədin \"ürəyi\"dir. Burada konkret tələblər, qadağalar və gözləntilər yazılır. Diqqət: Room 1-də öyrəndiyimiz kimi, burada həddindən artıq texniki detala (məsələn, \"parol 12 simvol olmalıdır\") getmək əvəzinə, mücərrəd səviyyədə qalıb detalı Standard sənədinə yönləndirmək daha düzgündür.\n\n**4. Roles & Responsibilities** — \"Kim nəyə cavabdehdir?\" sualını cavablandırır. Məsələn: \"İşçilər... etməlidir\", \"Menecerlər... təmin etməlidir\", \"İT departamenti... həyata keçirməlidir\". Bu bölmə olmadan policy icra oluna bilməz, çünki heç kim öz vəzifəsini bilmir.\n\n**5. Compliance & Enforcement** — Əməl edilməməsinin nəticələrini bildirir (xəbərdarlıq, intizam tədbiri, iş münasibətlərinin xitamı). Bu bölmə policy-ni \"tövsiyə\"dən \"məcburi qayda\"ya çevirir.\n\n**6. Exceptions** — Real həyatda hər qaydaya 100% əməl etmək mümkün olmaya bilər (məsələn, xüsusi bir layihə üçün müvəqqəti istisna lazım ola bilər). Yaxşı policy bunu əvvəlcədən nəzərdə tutur və istisna prosesini (kim təsdiqləyir, necə sənədləşdirilir) müəyyən edir — əks halda insanlar sadəcə qaydanı gizli şəkildə pozurlar.\n\n**7. Review & Ownership** — Sənədin \"sahibi\" kimdir (adətən CISO və ya müəyyən rol) və nə tezlikdə (illik, 2 illik) nəzərdən keçiriləcək. Sahibsiz və tarixsiz policy-lər köhnəlir və istifadədən düşür.\n\n**Ümumi səhvlər:**\n\n| Səhv | Niyə problemlidir |\n|---|---|\n| Scope-u dəqiq göstərməmək | Kimin əməl etməli olduğu bəlli olmur |\n| Purpose-u ümumi yazmaq | Sənəd \"niyə\" sualını cavablandırmır, işçilər ciddiyə almır |\n| Texniki detalı Policy-yə salmaq | Kiçik dəyişiklik üçün Board təsdiqi tələb olunur (bax Room 1) |\n| Enforcement bölməsini buraxmaq | Sənəd faktiki \"tövsiyə\" səviyyəsinə düşür, məcburi olmur |\n| Owner/Review tarixini yazmamaq | Sənəd köhnəlir, heç kim yeniləməyə cavabdeh olmur |\n\n**Sual 1**\nYeddi standart komponenti sadalayın və hər birinin cavab verdiyi sualı yazın.\n\n**Sual 2**\n\"Exceptions\" bölməsi niyə vacibdir? Bu bölmə olmasa nə baş verə bilər?\n\n**Sual 3**\nƏn çox rast gəlinən policy zəifliklərindən üçünü seçib izah edin."}]'::jsonb FROM rooms WHERE slug='grc-security-policy-yazmaq-case-study-o6xopa' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Nümunə Policy-ni Tənqidi Təhlil Etmək','60 dəq (praktiki — sənəd hazırlama)',0,'[{"body":"Aşağıda TechNova MMC-nin köhnə, zəif yazılmış bir \"Remote Work Security Policy\" parçası verilib. Bunu Task 1-dəki komponentlərlə müqayisə edərək zəifliklərini tapın.\n\n```\nREMOTE WORK SECURITY POLICY (KÖHNƏ VERSİYA)\n\nİşçilər evdən işləyərkən təhlükəsizliyə diqqət etməlidirlər.\nŞirkət kompüterlərindən düzgün istifadə olunmalıdır. Açıq \nWi-Fi-dan istifadə etmək məsləhət deyil. Əməl edilməzsə, \nmüvafiq tədbirlər görülə bilər. Bu sənəd İT departamenti \ntərəfindən hazırlanıb.\n```\n\nBu parçanı təhlil etsək:\n\n- **Purpose yoxdur** — sənəd niyə mövcuddur, hansı riski azaldır, deyilmir.\n- **Scope qeyri-müəyyəndir** — \"işçilər\" kimlərdir? Yalnız tam ştat, yoxsa podratçılar da? Hansı sistemlərə aiddir?\n- **Policy Statement çox mücərrəddir** — \"diqqətli olmalıdırlar\", \"düzgün istifadə olunmalıdır\" kimi ifadələr ölçülə bilən deyil, heç bir konkret tələb yoxdur.\n- **\"Məsləhət deyil\" ifadəsi** — bu, Guideline dilidir (Room 1-i xatırlayın), Policy-də məcburi dil (\"qadağandır\", \"tələb olunur\") istifadə olunmalıdır.\n- **Roles & Responsibilities yoxdur** — kim nəyə cavabdehdir, deyilmir.\n- **Enforcement qeyri-müəyyəndir** — \"müvafiq tədbirlər\" nə deməkdir? Konkret olmalıdır.\n- **Owner/Review tarixi yoxdur** — sənədin nə vaxt yeniləndiyi, kim tərəfindən sahiblənildiyi bəlli deyil (yalnız \"İT departamenti hazırlayıb\" yazılıb, bu, sahiblik deyil, müəlliflikdir).\n\nBu, real təşkilatlarda çox rast gəlinən bir problemdir: sənəd \"yazılıb\", amma icra edilə bilməz, çünki heç bir konkret öhdəlik və ya ölçü yoxdur. Auditor bu cür sənədi görəndə \"policy mövcuddur, amma effektiv deyil\" nəticəsinə gəlir.\n\n**Sual 1**\nYuxarıdakı köhnə policy-də Task 1-dəki yeddi komponentdən hansıları tamamilə yoxdur?\n\n**Sual 2**\n\"Məsləhət deyil\" ifadəsi niyə Policy dilinə uyğun deyil? Bunun əvəzinə hansı dil istifadə olunmalıdır?\n\n**Sual 3**\nAuditor belə bir sənədi görəndə niyə \"mövcuddur, amma effektiv deyil\" nəticəsinə gəlir?"}]'::jsonb FROM rooms WHERE slug='grc-security-policy-yazmaq-case-study-o6xopa' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Praktiki Tapşırıq: Acceptable Use Policy (AUP) Yazın','60 dəq (praktiki — sənəd hazırlama)',0,'[{"body":"İndi TechNova MMC üçün **tam funksional bir Acceptable Use Policy (Qəbul Edilə Bilən İstifadə Siyasəti)** yazacaqsınız. Bu sənəd işçilərin şirkət IT resurslarından (kompüter, e-poçt, internet, daxili sistemlər) necə istifadə edə biləcəyini tənzimləyir.\n\n**Ssenari təfərrüatları:**\n\n```\n- TechNova MMC-də 250 işçi var, həm ofisdən, həm uzaqdan işləyirlər\n- İşçilərə şirkət noutbuku, e-poçt hesabı və daxili sistemlərə \n  giriş verilir\n- Şirkət maliyyə sektoru tənzimləyicisinə hesabat verməlidir \n  (bu, sənədin \"niyə\" sualına cavab ola bilər)\n- Keçmişdə bir insident olub: işçi şəxsi USB-dən naməlum fayl \n  şirkət kompüterinə köçürüb, bu, kiçik bir zərərli proqram \n  yoluxmasına səbəb olub\n```\n\n**Addım 1 — Purpose yazın** (bu sənəd niyə mövcuddur, hansı riski azaldır?)\n\n**Addım 2 — Scope təyin edin** (kimə aiddir, kimə aid deyil?)\n\n**Addım 3 — Policy Statement yazın** (minimum 4 konkret qayda/tələb — icazə verilən və qadağan olunan fəaliyyətlər daxil olmaqla)\n\n**Addım 4 — Roles & Responsibilities yazın** (ən azı 2 rol: işçilər və İT/Təhlükəsizlik departamenti üçün)\n\n**Addım 5 — Compliance & Enforcement yazın** (əməl edilməzsə nə baş verəcək?)\n\n**Addım 6 — Exceptions bölməsini yazın** (istisna necə tələb oluna bilər?)\n\n**Addım 7 — Review & Ownership yazın** (sənədin sahibi kim, nə vaxt yenilənəcək?)\n\n**Kömək üçün nümunə həll (yalnız Purpose və Scope bölmələri üzrə):**\n\n```\n1. PURPOSE\n\nBu Siyasət TechNova MMC-nin İT resurslarının (kompüterlər, \ne-poçt, daxili sistemlər, internet girişi) məsuliyyətli və \ntəhlükəsiz şəkildə istifadə olunmasını təmin etmək üçün \nhazırlanmışdır. Məqsəd, icazəsiz giriş, zərərli proqram \nyoluxması və məlumat sızması risklərini azaltmaq, eyni zamanda \nşirkətin maliyyə tənzimləyicisi qarşısındakı uyğunluq \nöhdəliklərini yerinə yetirməkdir.\n\n2. SCOPE\n\nBu Siyasət aşağıdakılara aiddir:\n- Bütün tam ştat və yarım ştat işçilər\n- Podratçılar və müvəqqəti işçilər (şirkət sistemlərinə giriş \n  imkanı olduğu müddətcə)\n- Şirkətə məxsus bütün noutbuk, masaüstü kompüter, mobil \n  cihazlar və daxili sistemlər\n\nBu Siyasət aşağıdakılara aid DEYİL:\n- İşçilərin tamamilə şəxsi cihazları (əgər onlar şirkət \n  sistemlərinə qoşulmursa)\n- Müştərilər və üçüncü tərəf tərəfdaşlar (onlar üçün ayrıca \n  müqavilə şərtləri tətbiq olunur)\n```\n\n**Öz-özünə keyfiyyət yoxlaması (Checklist):**\n\n```\n☐ Purpose konkret riskə istinad edir (ümumi ifadə deyil)\n☐ Scope həm \"kimə aiddir\", həm \"kimə aid deyil\" hissəsini əhatə edir\n☐ Policy Statement-də minimum 4 konkret qayda var (mücərrəd \n  ifadələr deyil)\n☐ Ən azı bir qayda ssenaridəki USB insidentinə istinad edir \n  və ya onu önləyəcək xarakterdədir\n☐ Roles & Responsibilities-də ən azı 2 fərqli rol var\n☐ Enforcement bölməsi konkretdir (\"müvafiq tədbirlər\" kimi \n  qeyri-müəyyən ifadə YOXDUR)\n☐ Exceptions bölməsi kim təsdiqləyəcəyini göstərir\n☐ Review & Ownership bölməsində sahib rolu və konkret müddət \n  (məs. \"illik\") var\n☐ Sənəddə \"tövsiyə olunur\" kimi Guideline dili YOXDUR — məcburi \n  dil istifadə olunub (\"tələb olunur\", \"qadağandır\")\n```\n\n**Sual 1**\nYazdığınız Policy Statement-də USB/zərərli proqram insidentini önləyəcək hansı konkret qaydanı daxil etdiniz?\n\n**Sual 2**\nRoles & Responsibilities bölmənizdə işçi ilə İT departamentinin məsuliyyəti arasındakı fərq nədir?\n\n**Sual 3**\nYazdığınız sənədi Task 2-dəki \"köhnə versiya\" ilə müqayisə edin — hansı 2 konkret fərq sənədinizi daha icra edilə bilən edir?\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Bir Security Policy sənədinin yeddi standart komponentini sadalayın.\n2. \"Purpose\" bölməsinin yaxşı yazılması üçün nəyə diqqət edilməlidir?\n3. Niyə Policy Statement-də çox texniki detala getmək tövsiyə olunmur?\n4. Exceptions bölməsi olmayan policy-nin real həyatda hansı riski var?\n5. Auditor bir policy sənədini \"effektiv deyil\" adlandıranda, adətən hansı komponentlərin çatışmazlığından danışır?\n\n---"}]'::jsonb FROM rooms WHERE slug='grc-security-policy-yazmaq-case-study-o6xopa' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO paths(slug,title,description,category,status,order_index) VALUES ('grc','GRC PATH','GRC PATH kurikulumu','GRC PATH' ,'PUBLISHED',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO learning_modules(path_id,slug,title,status,order_index) SELECT id,'module-2','MODULE 2: Governance & Policy','PUBLISHED',2 FROM paths WHERE slug='grc' ON CONFLICT(path_id,slug) DO UPDATE SET title=excluded.title,status='PUBLISHED';
INSERT INTO rooms(module_id,slug,title,short_title,eyebrow,description,category,type,difficulty,duration_label,points,accent,objectives,source_file,status,order_index,published_at) SELECT m.id,'grc-governance-strukturlari-board-ciso-komiteler-lggxiw','Governance Strukturları (Board, CISO, Komitələr)','Governance Strukturları (Board, CISO, Komitələr)','GRC PATH · MODULE 2: Governance & Policy','Room 1-də öyrəndik ki, Policy sənədləri kim tərəfindən təsdiqlənir — amma "Board" və ya "CISO" dedikdə əslində kim nəzərdə tutulur, bu rollar bir-birindən nə ilə fərqlənir və qərar hansı ardıcıllıqla verilir? Bir təşkilatda təhlükəsizlik qərarları xaotik şəkildə yox, müəyyən bir strukturla verilir — bu struktura **governance** deyilir. Governance-i olmayan təşkilatda hər kəs öz təhlükəsizlik qərarını özü verir, məsuliyyət bulanıq olur və nəticədə boşluqlar yaranır.','GRC PATH','WALKTHROUGH','INTERMEDIATE'::difficulty,'35 dəq',0,'GREEN',ARRAY['Governance anlayışını və onun idarəçilikdən (management) fərqini izah edə bilmək','Board, CISO, Risk Committee və Security Steering Committee-nin rol və məsuliyyətlərini fərqləndirmək','"Three Lines of Defense" modelini izah edə bilmək','Real ssenaridə qərarın hansı səviyyədə verilməli olduğunu müəyyən edə bilmək']::text[],'drive/1SL5AlWv0J9cUFChBm9cTSpFI2DlgGXIW.md','PUBLISHED',2,now() FROM learning_modules m JOIN paths p ON p.id=m.path_id WHERE p.slug='grc' AND m.slug='module-2' ON CONFLICT(slug) DO UPDATE SET title=excluded.title,description=excluded.description,status='PUBLISHED';
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,1,'Governance Nədir?','35 dəq',0,'[{"body":"# ROOM 2: Governance Strukturları (Board, CISO, Komitələr)\n\n**Path:** GRC Fundamentals\n**Module:** Governance & Policy\n**Çətinlik:** Medium\n**Təxmini vaxt:** 35 dəq\n\n## Room haqqında\n\nRoom 1-də öyrəndik ki, Policy sənədləri kim tərəfindən təsdiqlənir — amma \"Board\" və ya \"CISO\" dedikdə əslində kim nəzərdə tutulur, bu rollar bir-birindən nə ilə fərqlənir və qərar hansı ardıcıllıqla verilir? Bir təşkilatda təhlükəsizlik qərarları xaotik şəkildə yox, müəyyən bir strukturla verilir — bu struktura **governance** deyilir. Governance-i olmayan təşkilatda hər kəs öz təhlükəsizlik qərarını özü verir, məsuliyyət bulanıq olur və nəticədə boşluqlar yaranır.\n\nBu room-da təhlükəsizlik governance-inin əsas iştirakçılarını (Board, CISO, komitələr) və onların bir-biri ilə necə əlaqələndiyini öyrənəcəksiniz.\n\n## Öyrənmə nəticələri\n\n- Governance anlayışını və onun idarəçilikdən (management) fərqini izah edə bilmək\n- Board, CISO, Risk Committee və Security Steering Committee-nin rol və məsuliyyətlərini fərqləndirmək\n- \"Three Lines of Defense\" modelini izah edə bilmək\n- Real ssenaridə qərarın hansı səviyyədə verilməli olduğunu müəyyən edə bilmək\n\n**Governance** — qərarların kim tərəfindən, hansı prosesə əsasən və hansı məsuliyyətlə veriləcəyini müəyyən edən strukturdur. Diqqət edin: governance **qərarları özü vermir**, sadəcə **kimin, necə qərar verəcəyini** müəyyənləşdirir. Bu, \"Management\" (idarəçilik) ilə tez-tez qarışdırılır, amma onlar fərqli səviyyələrdir:\n\n- **Governance** = \"Kim qərar verməli, hansı prinsiplə?\" (strateji, nəzarət səviyyəsi)\n- **Management** = \"Qərarı necə icra edirik?\" (əməliyyat səviyyəsi)\n\nBir analogiya: bir gəminin kapitanı (Governance) hara getdiklərini və hansı prinsiplərlə hərəkət edəcəklərini müəyyənləşdirir; mühərrik otağındakı komanda (Management) isə gəminin faktiki işləməsini təmin edir. Kapitan mühərriki özü işlətmir, amma onun necə işləyəcəyinə dair qaydalar qoyur və nəticəyə cavabdehdir.\n\n**Niyə governance vacibdir?** Governance-siz təşkilatda üç problem yaranır:\n\n```\n1. MƏSULİYYƏT BULANIQLIĞI\n   \"Bu qərarı kim verməli idi?\" sualına aydın cavab yoxdur — \n   fəlakət anında hər kəs bir-birini günahlandırır.\n\n2. UYĞUNSUZLUQ\n   Fərqli departamentlər eyni riskə fərqli cavab verir — \n   biri şifrələməni məcburi edir, digəri etmir.\n\n3. STRATEJİ-ƏMƏLİYYAT QOPUQLUĞU\n   Board səviyyəsində qəbul edilən risk iştahı (risk appetite) \n   əməliyyat səviyyəsinə heç vaxt çatmır, texniki komanda öz \n   başına hərəkət edir.\n```\n\nGovernance strukturu bu üç problemi aradan qaldırmaq üçün rolları aydın təyin edir və qərar axınını yuxarıdan aşağıya (strategiyadan icraya) və aşağıdan yuxarıya (hesabatlıqdan nəzarətə) təmin edir.\n\n**Sual 1**\nGovernance ilə Management arasındakı əsas fərq nədir?\n\n**Sual 2**\nGovernance-in olmaması nəticəsində yarana biləcək üç əsas problemi sadalayın.\n\n**Sual 3**\nGəmi analogiyasında kapitan niyə \"Governance\", mühərrik otağı komandası isə niyə \"Management\" sayılır?"}]'::jsonb FROM rooms WHERE slug='grc-governance-strukturlari-board-ciso-komiteler-lggxiw' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,2,'Əsas Rollar: Board, CISO və Komitələr','35 dəq',0,'[{"body":"Təhlükəsizlik governance-ində dörd əsas iştirakçı var, hər birinin fərqli səlahiyyət və məsuliyyət dairəsi var:\n\n**BOARD OF DIRECTORS (İdarə Heyəti)**\n- Ən yüksək nəzarət orqanıdır, təşkilatın bütün risklərinə (təkcə təhlükəsizlik yox) cavabdehdir\n- Risk appetite-i (nə qədər risk qəbul edilə biləcəyini) təsdiqləyir\n- Böyük büdcə tələb edən təhlükəsizlik investisiyalarını təsdiqləyir\n- Ciddi insidentlər zamanı son hesabatlıq nöqtəsidir (məsələn, tənzimləyici orqanlar qarşısında)\n- **Texniki detallarla məşğul olmur** — CISO-dan strateji səviyyədə hesabat alır\n\n**CISO (Chief Information Security Officer)**\n- Təhlükəsizlik proqramının baş icraçısıdır, Board-a (və ya CEO-ya) hesabat verir\n- Policy-ləri hazırlayır və Board-a təsdiq üçün təqdim edir\n- Risk qiymətləndirmələrini aparır və nəticələri Board-a çatdırır\n- Təhlükəsizlik komandasını idarə edir, Standard və Procedure-ların yaradılmasına nəzarət edir\n- Governance (strateji) ilə Management (əməliyyat) arasında körpü rolunu oynayır\n\n**SECURITY STEERING COMMITTEE (Təhlükəsizlik İdarəetmə Komitəsi)**\n- CISO, İT rəhbəri, Hüquq, HR və biznes bölmələrinin nümayəndələrindən ibarət kross-funksional qrupdur\n- Təhlükəsizlik təşəbbüslərini biznes prioritetləri ilə uzlaşdırır (məsələn, yeni bir sistemin tətbiqi həm təhlükəsizlik, həm maliyyə, həm hüquqi tərəfləri əhatə edir)\n- Adətən rüblük yığışır, orta səviyyəli qərarları (Standard-ların təsdiqi kimi) verir\n\n**RISK COMMITTEE (Risk Komitəsi)**\n- Bütün təşkilat səviyyəli riskləri (təkcə kibertəhlükəsizlik yox, maliyyə, əməliyyat, reputasiya riskləri də daxil) qiymətləndirir\n- Adətən Board-un alt komitəsidir və birbaşa Board-a hesabat verir\n- Risk registerini (risklərin siyahısı və prioritetləşdirilməsini) nəzərdən keçirir\n\nBu dörd səviyyə arasında məlumat axını iki istiqamətdə işləyir:\n\n```\n        BOARD OF DIRECTORS\n        (Risk appetite təsdiqi, böyük büdcə qərarları)\n              ↑ hesabat        ↓ istiqamət/təsdiq\n        RISK COMMITTEE ←──────→ CISO\n        (Təşkilat səviyyəli risk)  (Təhlükəsizlik proqramı)\n                                    ↑ hesabat    ↓ icra istiqaməti\n                          SECURITY STEERING COMMITTEE\n                          (Biznes-texnika uzlaşdırması)\n                                    ↑ hesabat    ↓ icra istiqaməti\n                          TƏHLÜKƏSİZLİK KOMANDASI\n                          (Standard/Procedure icrası)\n```\n\n**Vacib məntiq:** Nə qədər yuxarı gedirik, qərarlar bir o qədər **strateji və nadir** olur; nə qədər aşağı enirik, qərarlar bir o qədər **texniki və tez-tez** olur. Bir qərarın hansı səviyyədə veriləcəyini müəyyən edən əsas amil — **onun təsirinin genişliyi və maliyyə/hüquqi riskin böyüklüyüdür**. Məsələn, \"hansı antivirus proqramını seçək\" texniki komandanın işidir, amma \"milyon dollarlıq yeni təhlükəsizlik platformasına investisiya edək\" Board-un təsdiqini tələb edir.\n\n**Sual 1**\nCISO-nun governance (Board) ilə management (təhlükəsizlik komandası) arasında \"körpü\" rolunu oynaması nə deməkdir?\n\n**Sual 2**\nSecurity Steering Committee ilə Risk Committee arasındakı əsas fərq nədir?\n\n**Sual 3**\nBir qərarın hansı səviyyədə veriləcəyini müəyyən edən əsas amil nədir?"}]'::jsonb FROM rooms WHERE slug='grc-governance-strukturlari-board-ciso-komiteler-lggxiw' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
INSERT INTO tasks(room_id,order_index,title,duration_label,points,sections) SELECT id,3,'Praktiki Tapşırıq: Qərar Hansı Səviyyədə Verilməlidir?','35 dəq',0,'[{"body":"TechNova MMC-də aşağıdakı dörd situasiya yaranıb. Sizin tapşırığınız hər situasiya üçün qərarın hansı səviyyədə (Board / CISO / Security Steering Committee / Risk Committee / Təhlükəsizlik komandası) veriləcəyini müəyyən etmək və səbəbini izah etməkdir.\n\n```\nSituasiya 1:\nTechNova yeni bir bulud provayderinə keçmək istəyir — bu, \n$2 milyon illik xərc və şirkətin bütün müştəri məlumatlarının \nyeni infrastrukturda saxlanmasını nəzərdə tutur.\n\nSituasiya 2:\nTəhlükəsizlik komandası fərqli bir log monitorinq alətinə \nkeçmək istəyir, cari alətin lisenziya xərci bitib, alternativ \nalət oxşar funksionallığa malikdir və büdcə fərqi minimaldır.\n\nSituasiya 3:\nYeni marketinq kampaniyası üçün müştəri məlumatlarının üçüncü \ntərəf analitika şirkəti ilə paylaşılması təklif olunur — bu, \nhəm hüquqi (KVKT/GDPR uyğunluğu), həm maliyyə, həm marketinq \nmaraqlarını əhatə edir.\n\nSituasiya 4:\nİllik risk qiymətləndirməsində aşkar olunub ki, TechNova-nın \nəməliyyat riski (kibertəhlükəsizlik + tədarük zənciri + maliyyə \nsabitliyi birlikdə) yüksəkdir və bu, təşkilatın ümumi risk \nprofilinə təsir edir.\n```\n\n**Kömək üçün nümunə həll (Situasiya 1 üzrə):**\n\n```\nSituasiya 1 → BOARD OF DIRECTORS\n\nSəbəb: Bu qərar üç meyara görə Board səviyyəsinə aiddir: \n(1) Böyük maliyyə həcmi ($2 milyon illik) — bu, adi əməliyyat \nbüdcəsindən kənardır və kapital qərarı sayılır; (2) Strateji \ntəsir — bütün müştəri məlumatlarının yeni infrastruktura \nkeçməsi uzunmüddətli risk profilini dəyişir; (3) Geri dönüşü \nçətindir — bulud provayder dəyişikliyi illər sürən öhdəlik \nyaradır. CISO bu qərarı hazırlaya və tövsiyə edə bilər, amma \nson təsdiq Board-dan gəlməlidir.\n```\n\n**Öz-özünə keyfiyyət yoxlaması (Checklist):**\n\n```\n☐ Hər 4 situasiya üçün konkret səviyyə seçilib\n☐ Hər seçim üçün ən azı bir konkret meyar göstərilib (maliyyə \n  həcmi, strateji təsir, geri dönüş çətinliyi, kross-funksional \n  təbiət və s.)\n☐ \"Bu qərarı kim texniki cəhətdən hazırlaya bilər, kim son \n  təsdiqi verməlidir\" fərqi nəzərə alınıb\n☐ Kross-funksional (bir neçə departamenti əhatə edən) \n  situasiyalar düzgün tanınıb\n```\n\n**Sual 1**\nSituasiya 2 niyə Board yox, Təhlükəsizlik komandası (və ya ən çox CISO) səviyyəsində qərarlaşdırıla bilər?\n\n**Sual 2**\nSituasiya 3 niyə Security Steering Committee-yə uyğun gəlir? Hansı xüsusiyyəti onu kross-funksional edir?\n\n**Sual 3**\nSituasiya 4 niyə Risk Committee-nin işidir, təkcə CISO-nun deyil? (İpucu: risk növlərinin əhatə dairəsini düşünün)\n\n## Yekun Yoxlama (Summary Quiz)\n\n1. Governance ilə Management arasındakı fərqi bir cümlə ilə izah edin.\n2. Board, CISO, Security Steering Committee və Risk Committee-nin əsas rolunu qısaca sadalayın.\n3. Qərarın hansı səviyyədə veriləcəyini müəyyən edən əsas meyarlar hansılardır?\n4. CISO-nun \"körpü rolu\" nə deməkdir və niyə vacibdir?\n5. TechNova ssenarisindəki dörd situasiyadan hansı ən çox kross-funksional komitə tələb edir və niyə?\n\n---"}]'::jsonb FROM rooms WHERE slug='grc-governance-strukturlari-board-ciso-komiteler-lggxiw' ON CONFLICT(room_id,order_index) DO UPDATE SET title=excluded.title,sections=excluded.sections,duration_label=excluded.duration_label;
